-- mysql_tl_admin_汇总.sql
-- 汇总 mysql_tl_admin 目录的 96 个函数/存储过程脚本，按原文件名排序。
-- 执行前请选择目标数据库，并在同一数据库中依次安装共享对象：
-- bjts/mysql_added/mysql_extra.sql
-- bjts/mysql_added/mysql_extra_seq_nextval_fix.sql
-- 使用支持 DELIMITER 的客户端一次执行整个文件。
-- 各段保留原脚本的 DROP/CREATE、注释及 DELIMITER 语句。
-- 单独脚本更新后，应重新生成本汇总文件。

-- ======================================================================
-- [001/096] BEGIN SOURCE: FUNC_GET_XJ_SWJG.sql
-- ======================================================================
DELIMITER $$

DROP PROCEDURE IF EXISTS FUNC_GET_XJ_SWJG$$

CREATE PROCEDURE FUNC_GET_XJ_SWJG(IN P_SJ_SWCODE VARCHAR(4000))
routine_body: BEGIN
    IF SUBSTR(P_SJ_SWCODE, 1, 1) = '2' THEN
        SELECT VIR_SWJGDM AS SWJG_DM
          FROM DM_SWJG_VIRTUAL
         WHERE SWJG_DM = P_SJ_SWCODE
           AND YXBZ = 'Y'
           AND VIR_FLAG = '0';
    ELSE
        SELECT SWJG_DM AS SWJG_DM
          FROM DM_SWJG
         WHERE SWJG_DM_SJ = P_SJ_SWCODE
           AND TSJG_BZ = '1';
    END IF;
END$$

DELIMITER ;

-- END SOURCE: FUNC_GET_XJ_SWJG.sql

-- ======================================================================
-- [002/096] BEGIN SOURCE: FUNC_ZB_TSJHZX_HZB_HZJS.sql
-- ======================================================================
DELIMITER $$

DROP FUNCTION IF EXISTS FUNC_ZB_TSJHZX_HZB_HZJS$$

CREATE function FUNC_ZB_TSJHZX_HZB_HZJS(p_tszb_yn VARCHAR(4000),p_zbjg_dm VARCHAR(4000))
RETURNS integer
NOT DETERMINISTIC
MODIFIES SQL DATA
BEGIN

  -- 退税指标计划执行汇总表，汇总计算LX=2汇总类指标机关
  if length(p_tszb_yn)<>6 then
    return -1;
  end if;
  if p_zbjg_dm is null then
    -- 计算市辖区小计
    update ZB_TSJHZX_HZB AS A SET byxdjhe = (SELECT sum(IFNULL(byxdjhe, 0))
from ZB_TSJHZX_HZB B where B.Tszb_yn=A.Tszb_yn and
         B.ZBJG_DM in (select zbjg_dm from DM_ZBJG C where C.SJ_ZBJG=A.Zbjg_Dm and C.Yxbz='Y')),
    byzhtse = (SELECT sum(IFNULL(byzhtse, 0))
from ZB_TSJHZX_HZB B where B.Tszb_yn=A.Tszb_yn and
         B.ZBJG_DM in (select zbjg_dm from DM_ZBJG C where C.SJ_ZBJG=A.Zbjg_Dm and C.Yxbz='Y')),
    byybltse = (SELECT sum(IFNULL(byybltse, 0))
from ZB_TSJHZX_HZB B where B.Tszb_yn=A.Tszb_yn and
         B.ZBJG_DM in (select zbjg_dm from DM_ZBJG C where C.SJ_ZBJG=A.Zbjg_Dm and C.Yxbz='Y'))
         where A.Tszb_yn=p_tszb_yn and
         exists(select 1 from DM_ZBJG D where D.zbjg_dm=A.zbjg_dm and D.lx='2' and substr(D.zbjg_dm,-1,1)='X');

    -- 计算各地市小计
    update ZB_TSJHZX_HZB AS A SET byxdjhe = (SELECT sum(IFNULL(byxdjhe, 0))
from ZB_TSJHZX_HZB B where B.Tszb_yn=A.Tszb_yn and
         B.ZBJG_DM in (select zbjg_dm from DM_ZBJG C where C.SJ_ZBJG=A.Zbjg_Dm and C.Yxbz='Y')),
    byzhtse = (SELECT sum(IFNULL(byzhtse, 0))
from ZB_TSJHZX_HZB B where B.Tszb_yn=A.Tszb_yn and
         B.ZBJG_DM in (select zbjg_dm from DM_ZBJG C where C.SJ_ZBJG=A.Zbjg_Dm and C.Yxbz='Y')),
    byybltse = (SELECT sum(IFNULL(byybltse, 0))
from ZB_TSJHZX_HZB B where B.Tszb_yn=A.Tszb_yn and
         B.ZBJG_DM in (select zbjg_dm from DM_ZBJG C where C.SJ_ZBJG=A.Zbjg_Dm and C.Yxbz='Y'))
         where A.Tszb_yn=p_tszb_yn and
         exists(select 1 from DM_ZBJG D where D.zbjg_dm=A.zbjg_dm and D.lx='2' and D.Sj_Zbjg='13300');

    -- 计算全省所有地区（除直属分局外）小计
    update ZB_TSJHZX_HZB AS A SET byxdjhe = (SELECT sum(IFNULL(byxdjhe, 0))
from ZB_TSJHZX_HZB B where B.Tszb_yn=A.Tszb_yn and
         B.ZBJG_DM in (select zbjg_dm from DM_ZBJG C where C.SJ_ZBJG=A.Zbjg_Dm and C.Yxbz='Y')),
    byzhtse = (SELECT sum(IFNULL(byzhtse, 0))
from ZB_TSJHZX_HZB B where B.Tszb_yn=A.Tszb_yn and
         B.ZBJG_DM in (select zbjg_dm from DM_ZBJG C where C.SJ_ZBJG=A.Zbjg_Dm and C.Yxbz='Y')),
    byybltse = (SELECT sum(IFNULL(byybltse, 0))
from ZB_TSJHZX_HZB B where B.Tszb_yn=A.Tszb_yn and
         B.ZBJG_DM in (select zbjg_dm from DM_ZBJG C where C.SJ_ZBJG=A.Zbjg_Dm and C.Yxbz='Y'))
         where A.Tszb_yn=p_tszb_yn and
         exists(select 1 from DM_ZBJG D where D.zbjg_dm=A.zbjg_dm and D.lx='2' and D.Sj_Zbjg='133');

    -- 计算全省小计
    update ZB_TSJHZX_HZB AS A SET byxdjhe = (SELECT sum(IFNULL(byxdjhe, 0))
from ZB_TSJHZX_HZB B where B.Tszb_yn=A.Tszb_yn and
         B.ZBJG_DM in (select zbjg_dm from DM_ZBJG C where C.SJ_ZBJG=A.Zbjg_Dm and C.Yxbz='Y')),
    byzhtse = (SELECT sum(IFNULL(byzhtse, 0))
from ZB_TSJHZX_HZB B where B.Tszb_yn=A.Tszb_yn and
         B.ZBJG_DM in (select zbjg_dm from DM_ZBJG C where C.SJ_ZBJG=A.Zbjg_Dm and C.Yxbz='Y')),
    byybltse = (SELECT sum(IFNULL(byybltse, 0))
from ZB_TSJHZX_HZB B where B.Tszb_yn=A.Tszb_yn and
         B.ZBJG_DM in (select zbjg_dm from DM_ZBJG C where C.SJ_ZBJG=A.Zbjg_Dm and C.Yxbz='Y'))
         where A.Tszb_yn=p_tszb_yn and
         exists(select 1 from DM_ZBJG D where D.zbjg_dm=A.zbjg_dm and D.lx='2' and D.Sj_Zbjg='1');

  end if;

  return 1;
END$$

DELIMITER ;

-- END SOURCE: FUNC_ZB_TSJHZX_HZB_HZJS.sql

-- ======================================================================
-- [003/096] BEGIN SOURCE: FUNC_ZB_TSJHZX_HZB_INIT.sql
-- ======================================================================
DELIMITER $$

DROP FUNCTION IF EXISTS FUNC_ZB_TSJHZX_HZB_INIT$$

CREATE function FUNC_ZB_TSJHZX_HZB_INIT
(p_tszb_ny VARCHAR(4000),p_zbjg_dm VARCHAR(4000))
RETURNS integer
NOT DETERMINISTIC
MODIFIES SQL DATA
BEGIN
  DECLARE zbHzbCnt DECIMAL(38,10);
  DECLARE v_syjzjhe DECIMAL(16,2);
  DECLARE v_bnljbltse DECIMAL(16,2);
  DECLARE v_bnljzhtse DECIMAL(16,2);
  DECLARE v_bnljxdjhe DECIMAL(16,2);
  DECLARE v_bnljjhwcl DECIMAL(6,2);
  DECLARE v_nd varchar(4);


  DECLARE v_zbjg VARCHAR(11);

  -- 退税指标计划执行汇总表，记录创建
  if length(p_tszb_ny)<>6 then
    return -1;
  end if;

  BEGIN
  DECLARE BJTS_FETCH_DONE_001 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_FETCH_CURSOR_001 CURSOR FOR
select zbjg_dm from DM_ZBJG
         where yxbz='Y' and (p_zbjg_dm is null or zbjg_dm=p_zbjg_dm);
  OPEN BJTS_FETCH_CURSOR_001;
  BJTS_FETCH_LOOP_001: LOOP
      BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_FETCH_DONE_001 = TRUE;
      FETCH BJTS_FETCH_CURSOR_001 INTO v_zbjg;
    END;
    IF BJTS_FETCH_DONE_001 THEN
      LEAVE BJTS_FETCH_LOOP_001;
    END IF;


      begin
  DECLARE BJTS_SQLCODE_002 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_002 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR NOT FOUND
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_002 = MYSQL_ERRNO, BJTS_SQLERRM_002 = MESSAGE_TEXT;
          SET zbHzbCnt =0;

  END;
select count(*) into zbHzbCnt from ZB_TSJHZX_HZB
          where zbjg_dm=v_zbjg and tszb_yn=p_tszb_ny ;
        end;

      if  zbHzbCnt=0 then
        SET v_nd = substr(p_tszb_ny,1,4);
        -- 取上月结转
        begin
  DECLARE BJTS_SQLCODE_001 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_001 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR NOT FOUND
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_001 = MYSQL_ERRNO, BJTS_SQLERRM_001 = MESSAGE_TEXT;
            SET v_syjzjhe =0;
            SET v_bnljbltse =0;
            SET v_bnljzhtse =0;
            SET v_bnljxdjhe =0;

  END;
select IFNULL(byjhye, 0),
                 IFNULL(byybltse, 0)+IFNULL(bnljbltse, 0),
                 IFNULL(byzhtse, 0)+IFNULL(bnljzhtse, 0),
                 IFNULL(byxdjhe, 0)+IFNULL(bnljxdjhe, 0)
          into v_syjzjhe,v_bnljbltse,v_bnljzhtse,v_bnljxdjhe from
          (select byjhye,byybltse,byzhtse,byxdjhe,bnljbltse,bnljzhtse,bnljxdjhe from ZB_TSJHZX_HZB
                 where zbjg_dm=v_zbjg and tszb_yn like ORA_CONCAT(v_nd, '%') order by tszb_yn desc
          )pt where 1=1
LIMIT 1;
          end;

        -- 取截止上月的累计
/*        select nvl(sum(byybltse),0),nvl(sum(byzhtse),0),nvl(sum(byxdjhe),0) into v_bnljbltse,v_bnljzhtse,v_bnljxdjhe
        from ZB_TSJHZX_HZB
                 where zbjg_dm=v_zbjg and tszb_yn like v_nd || '%';
*/
        -- 本年累计计划完成率
        SET v_bnljjhwcl = case when v_bnljxdjhe+v_bnljzhtse=0 then 0
                       else round((v_bnljbltse)/(v_bnljxdjhe+v_bnljzhtse)*100,2) end;

        -- 插入本月记录
        insert into ZB_TSJHZX_HZB(zbjg_dm,tszb_yn,syjzjhe,byjhze,byjhye,bnljbltse,bnljzhtse,bnljxdjhe,bnljjhwcl)
               values(v_zbjg,p_tszb_ny,v_syjzjhe,v_syjzjhe,v_syjzjhe,v_bnljbltse,v_bnljzhtse,v_bnljxdjhe,v_bnljjhwcl);
      end if;


  END LOOP BJTS_FETCH_LOOP_001;
  CLOSE BJTS_FETCH_CURSOR_001;
END;

  return 1;
END$$

DELIMITER ;

-- END SOURCE: FUNC_ZB_TSJHZX_HZB_INIT.sql

-- ======================================================================
-- [004/096] BEGIN SOURCE: FUNC_ZB_TSJHZX_HZB_INIT__BAK.sql
-- ======================================================================
DELIMITER $$

DROP FUNCTION IF EXISTS FUNC_ZB_TSJHZX_HZB_INIT__BAK$$

CREATE function FUNC_ZB_TSJHZX_HZB_INIT__BAK
(p_tszb_ny VARCHAR(4000),p_zbjg_dm VARCHAR(4000))
RETURNS integer
NOT DETERMINISTIC
MODIFIES SQL DATA
BEGIN
  DECLARE zbHzbCnt DECIMAL(38,10);
  DECLARE v_syjzjhe DECIMAL(16,2);
  DECLARE v_bnljbltse DECIMAL(16,2);
  DECLARE v_bnljzhtse DECIMAL(16,2);
  DECLARE v_bnljxdjhe DECIMAL(16,2);
  DECLARE v_bnljjhwcl DECIMAL(6,2);
  DECLARE v_nd varchar(4);


  DECLARE v_zbjg VARCHAR(11);

  -- 退税指标计划执行汇总表，记录创建
  if length(p_tszb_ny)<>6 then
    return -1;
  end if;

  BEGIN
  DECLARE BJTS_FETCH_DONE_001 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_FETCH_CURSOR_001 CURSOR FOR
select zbjg_dm from DM_ZBJG
         where yxbz='Y' and (p_zbjg_dm is null or zbjg_dm=p_zbjg_dm);
  OPEN BJTS_FETCH_CURSOR_001;
  BJTS_FETCH_LOOP_001: LOOP
      BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_FETCH_DONE_001 = TRUE;
      FETCH BJTS_FETCH_CURSOR_001 INTO v_zbjg;
    END;
    IF BJTS_FETCH_DONE_001 THEN
      LEAVE BJTS_FETCH_LOOP_001;
    END IF;


      begin
  DECLARE BJTS_SQLCODE_002 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_002 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR NOT FOUND
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_002 = MYSQL_ERRNO, BJTS_SQLERRM_002 = MESSAGE_TEXT;
          SET zbHzbCnt =0;

  END;
select count(*) into zbHzbCnt from ZB_TSJHZX_HZB
          where zbjg_dm=v_zbjg and tszb_yn=p_tszb_ny ;
        end;

      if  zbHzbCnt=0 then
        SET v_nd = substr(p_tszb_ny,1,4);
        -- 取上月结转
        begin
  DECLARE BJTS_SQLCODE_001 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_001 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR NOT FOUND
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_001 = MYSQL_ERRNO, BJTS_SQLERRM_001 = MESSAGE_TEXT;
            SET v_syjzjhe =0;

  END;
select IFNULL(byjhye, 0) into v_syjzjhe from
          (select byjhye from ZB_TSJHZX_HZB
                 where zbjg_dm=v_zbjg and tszb_yn like ORA_CONCAT(v_nd, '%') order by tszb_yn desc
          )pt where 1=1
LIMIT 1;
          end;

        -- 取截止上月的累计
        select IFNULL(sum(byybltse), 0),IFNULL(sum(byzhtse), 0),IFNULL(sum(byxdjhe), 0) into v_bnljbltse,v_bnljzhtse,v_bnljxdjhe
        from ZB_TSJHZX_HZB
                 where zbjg_dm=v_zbjg and tszb_yn like ORA_CONCAT(v_nd, '%');

    -- 本年累计计划完成率
    SET v_bnljjhwcl = case when v_bnljxdjhe+v_bnljzhtse=0 then 0
      else round((v_bnljbltse)/(v_bnljxdjhe+v_bnljzhtse)*100,2) end;

        -- 插入本月记录
        insert into ZB_TSJHZX_HZB(zbjg_dm,tszb_yn,syjzjhe,byjhze,byjhye,bnljbltse,bnljzhtse,bnljxdjhe,bnljjhwcl)
               values(v_zbjg,p_tszb_ny,v_syjzjhe,v_syjzjhe,v_syjzjhe,v_bnljbltse,v_bnljzhtse,v_bnljxdjhe,v_bnljjhwcl);
      end if;


  END LOOP BJTS_FETCH_LOOP_001;
  CLOSE BJTS_FETCH_CURSOR_001;
END;

  return 1;
END$$

DELIMITER ;

-- END SOURCE: FUNC_ZB_TSJHZX_HZB_INIT__BAK.sql

-- ======================================================================
-- [005/096] BEGIN SOURCE: PRO_RECORD_TASK_DELE.sql
-- ======================================================================
DELIMITER $$

DROP PROCEDURE IF EXISTS PRO_RECORD_TASK_DELE$$

CREATE PROCEDURE PRO_RECORD_TASK_DELE
/* 删除企业端作废单证备案 */
(
  IN V_NSRSBH VARCHAR(4000),
	IN V_SSNYPC VARCHAR(4000)
)
routine_body: BEGIN

  DELETE FROM EDOC_FILE_INFO WHERE EDOC_ID IN
    (SELECT EDOC_ID FROM EDOC_CATALOG_SECOND WHERE ENTRY_ID IN
    (SELECT ENTRY_ID FROM EDOC_CATALOG_FIRST WHERE nsrsbh = V_NSRSBH AND SBNYPC = V_SSNYPC AND ENTRY_ID NOT IN
    (SELECT ENTRY_ID FROM EDOC_CATALOG_FIRST WHERE nsrsbh = V_NSRSBH AND SBNYPC <> V_SSNYPC)));

  DELETE FROM EDOC_CATALOG_SECOND WHERE ENTRY_ID IN
    (SELECT ENTRY_ID FROM EDOC_CATALOG_FIRST WHERE nsrsbh = V_NSRSBH AND SBNYPC = V_SSNYPC AND ENTRY_ID NOT IN
    (SELECT ENTRY_ID FROM EDOC_CATALOG_FIRST WHERE nsrsbh = V_NSRSBH AND SBNYPC <> V_SSNYPC));

  DELETE FROM EDOC_CATALOG_FIRST WHERE nsrsbh = V_NSRSBH AND SBNYPC = V_SSNYPC;
  DELETE FROM EDOC_RECORD_TASK WHERE nsrsbh = V_NSRSBH AND SBNYPC = V_SSNYPC;
  COMMIT;

  LEAVE routine_body;
END$$

DELIMITER ;

-- END SOURCE: PRO_RECORD_TASK_DELE.sql

