-- ======================================================================
-- [015/096] BEGIN SOURCE: PRO_TJBB_CHECK_DTBB.sql
-- ======================================================================
DELIMITER $$

DROP PROCEDURE IF EXISTS PRO_TJBB_CHECK_DTBB$$

CREATE PROCEDURE PRO_TJBB_CHECK_DTBB
/****************************************************
 * 报表上报前的表间逻辑关系检查
 ***************************************************/
(
  IN V_SWCODE VARCHAR(4000),
  IN V_SSNY VARCHAR(4000),
  IN V_BBDLDM VARCHAR(4000),
  OUT V_ERROR DECIMAL(38,10),
  OUT V_MSG VARCHAR(4000)
)
routine_body: BEGIN
  DECLARE LD_SYSDATE       DATETIME;
  DECLARE LC_THISMONTH     VARCHAR(6);
  DECLARE LC_PREVMONTH     VARCHAR(6);

  DECLARE LN_AMT_TARGET    DECIMAL(16,4);
  DECLARE LN_AMT_REFER     DECIMAL(16,4);

  SET V_ERROR =0;
  SET V_MSG = ' ';

  IF V_SSNY IS NOT NULL THEN
    SET LD_SYSDATE =STR_TO_DATE(ORA_CONCAT(V_SSNY, '01'), '%Y%m%d');
  ELSE
    SET LD_SYSDATE =CURRENT_TIMESTAMP;
  END IF;
  SET LC_THISMONTH =DATE_FORMAT(LD_SYSDATE, '%Y%m');
  SET LC_PREVMONTH =DATE_FORMAT(DATE_ADD(LD_SYSDATE, INTERVAL -1 MONTH), '%Y%m');

  -- 0、清除原有制表数据，准备重新制表
  BEGIN
  DECLARE BJTS_SQLCODE_003 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_003 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_003 = MYSQL_ERRNO, BJTS_SQLERRM_003 = MESSAGE_TEXT;
      SET V_ERROR = BJTS_SQLCODE_003;
      SET V_MSG = BJTS_SQLERRM_003;

  END;
DELETE FROM TJBB_SB_JYXX WHERE SWJGDM=V_SWCODE AND BBDLDM=V_BBDLDM;
    COMMIT;
  END;
  IF V_ERROR <> 0 THEN
    LEAVE routine_body;
  END IF;

  IF V_BBDLDM='B01' THEN
    BEGIN
      SELECT T.ZH_TMSE_XJ
        INTO LN_AMT_TARGET
        FROM TJBB_DT_B01100 T
       WHERE T.SWJGDM=V_SWCODE AND T.SSNY=LC_THISMONTH AND T.BBLC='01';
      SELECT T.HJ_TSE
        INTO LN_AMT_REFER
        FROM TJBB_DT_B01101 T
       WHERE T.SWJGDM=V_SWCODE AND T.SSNY=LC_THISMONTH AND T.BBLC='01';
      IF ROUND(ABS(LN_AMT_TARGET - LN_AMT_REFER),0)>2 THEN
        INSERT INTO TJBB_SB_JYXX(ID,SWJGDM,SSNY,BBDLDM,BBDM,MSG_TYPE,MSG_LEVEL,MSG)
             SELECT SEQ_NEXTVAL('SEQ_TJBB_SB_JYXX'),V_SWCODE,LC_THISMONTH,V_BBDLDM,'B01100','1','2','出口退（免）税情况分析月报表（主表）,暂缓办理退（免）税额小计应与附表《暂缓退（免）税统计月报表》对应栏一致'
;
        COMMIT;
      END IF;

      SELECT T.BY_TMSE_XJ
        INTO LN_AMT_TARGET
        FROM TJBB_DT_B01100 T
       WHERE T.SWJGDM=V_SWCODE AND T.SSNY=LC_THISMONTH AND T.BBLC='01';
      SELECT T.HJ_TSE
        INTO LN_AMT_REFER
        FROM TJBB_DT_B01102 T
       WHERE T.SWJGDM=V_SWCODE AND T.SSNY=LC_THISMONTH AND T.BBLC='01';
      IF ROUND(ABS(LN_AMT_TARGET - LN_AMT_REFER),0)>2 THEN
        INSERT INTO TJBB_SB_JYXX(ID,SWJGDM,SSNY,BBDLDM,BBDM,MSG_TYPE,MSG_LEVEL,MSG)
             SELECT SEQ_NEXTVAL('SEQ_TJBB_SB_JYXX'),V_SWCODE,LC_THISMONTH,V_BBDLDM,'B01100','1','2','出口退（免）税情况分析月报表（主表）,不予办理退（免）税额小计应与附表《不予办理退（免）税统计月报表》对应栏一致'
;
        COMMIT;
      END IF;

      SELECT T.RDHS
        INTO LN_AMT_TARGET
        FROM TJBB_DT_B01100 T
       WHERE T.SWJGDM=V_SWCODE AND T.SSNY=LC_THISMONTH AND T.BBLC='01';
      SELECT T.RDHS
        INTO LN_AMT_REFER
        FROM TJBB_DT_B01108 T
       WHERE T.SWJGDM=V_SWCODE AND T.SSNY=LC_THISMONTH AND T.BBLC='01';
      IF ROUND(ABS(LN_AMT_TARGET - LN_AMT_REFER),0)>0 THEN
        INSERT INTO TJBB_SB_JYXX(ID,SWJGDM,SSNY,BBDLDM,BBDM,MSG_TYPE,MSG_LEVEL,MSG)
             SELECT SEQ_NEXTVAL('SEQ_TJBB_SB_JYXX'),V_SWCODE,LC_THISMONTH,V_BBDLDM,'B01100','1','2','出口退（免）税情况分析月报表（主表）,备案户数应与《出口退（免）税情况分析月报表（本月情况）》对应栏一致'
;
        COMMIT;
      END IF;
      SELECT T.RDHS
        INTO LN_AMT_REFER
        FROM TJBB_DT_B01109 T
       WHERE T.SWJGDM=V_SWCODE AND T.SSNY=LC_THISMONTH AND T.BBLC='01';
      IF ROUND(ABS(LN_AMT_TARGET - LN_AMT_REFER),0)>0 THEN
        INSERT INTO TJBB_SB_JYXX(ID,SWJGDM,SSNY,BBDLDM,BBDM,MSG_TYPE,MSG_LEVEL,MSG)
             SELECT SEQ_NEXTVAL('SEQ_TJBB_SB_JYXX'),V_SWCODE,LC_THISMONTH,V_BBDLDM,'B01100','1','2','出口退（免）税情况分析月报表（主表）,备案户数应与《出口退（免）税情况分析月报表（累计情况）》对应栏一致'
;
        COMMIT;
      END IF;

      SELECT T.SBHS
        INTO LN_AMT_TARGET
        FROM TJBB_DT_B01100 T
       WHERE T.SWJGDM=V_SWCODE AND T.SSNY=LC_THISMONTH AND T.BBLC='01';
      SELECT T.SBHS
        INTO LN_AMT_REFER
        FROM TJBB_DT_B01109 T
       WHERE T.SWJGDM=V_SWCODE AND T.SSNY=LC_THISMONTH AND T.BBLC='01';
      IF ROUND(ABS(LN_AMT_TARGET - LN_AMT_REFER),0)>0 THEN
        INSERT INTO TJBB_SB_JYXX(ID,SWJGDM,SSNY,BBDLDM,BBDM,MSG_TYPE,MSG_LEVEL,MSG)
             SELECT SEQ_NEXTVAL('SEQ_TJBB_SB_JYXX'),V_SWCODE,LC_THISMONTH,V_BBDLDM,'B01100','1','2','出口退（免）税情况分析月报表（主表）,申报户数应与《出口退（免）税情况分析月报表（累计情况）》对应栏一致'
;
        COMMIT;
      END IF;

      SELECT T.SB_CKE_XJ
        INTO LN_AMT_TARGET
        FROM TJBB_DT_B01100 T
       WHERE T.SWJGDM=V_SWCODE AND T.SSNY=LC_THISMONTH AND T.BBLC='01';
      SELECT T.SB_CKE_XJ
        INTO LN_AMT_REFER
        FROM TJBB_DT_B01109 T
       WHERE T.SWJGDM=V_SWCODE AND T.SSNY=LC_THISMONTH AND T.BBLC='01';
      IF ROUND(ABS(LN_AMT_TARGET - LN_AMT_REFER),0)>2 THEN
        INSERT INTO TJBB_SB_JYXX(ID,SWJGDM,SSNY,BBDLDM,BBDM,MSG_TYPE,MSG_LEVEL,MSG)
             SELECT SEQ_NEXTVAL('SEQ_TJBB_SB_JYXX'),V_SWCODE,LC_THISMONTH,V_BBDLDM,'B01100','1','2','出口退（免）税情况分析月报表（主表）,申报退税出口额应与《出口退（免）税情况分析月报表（累计情况）》对应栏一致'
;
        COMMIT;
      END IF;

      SELECT T.SB_TMSE_XJ
        INTO LN_AMT_TARGET
        FROM TJBB_DT_B01100 T
       WHERE T.SWJGDM=V_SWCODE AND T.SSNY=LC_THISMONTH AND T.BBLC='01';
      SELECT T.SB_TMSE_XJ
        INTO LN_AMT_REFER
        FROM TJBB_DT_B01109 T
       WHERE T.SWJGDM=V_SWCODE AND T.SSNY=LC_THISMONTH AND T.BBLC='01';
      IF ROUND(ABS(LN_AMT_TARGET - LN_AMT_REFER),0)>2 THEN
        INSERT INTO TJBB_SB_JYXX(ID,SWJGDM,SSNY,BBDLDM,BBDM,MSG_TYPE,MSG_LEVEL,MSG)
             SELECT SEQ_NEXTVAL('SEQ_TJBB_SB_JYXX'),V_SWCODE,LC_THISMONTH,V_BBDLDM,'B01100','1','2','出口退（免）税情况分析月报表（主表）,申报退（免）税额应与《出口退（免）税情况分析月报表（累计情况）》对应栏一致'
;
        COMMIT;
      END IF;

      SELECT T.SH_TMSE_XJ
        INTO LN_AMT_TARGET
        FROM TJBB_DT_B01100 T
       WHERE T.SWJGDM=V_SWCODE AND T.SSNY=LC_THISMONTH AND T.BBLC='01';
      SELECT T.SH_TMSE_XJ
        INTO LN_AMT_REFER
        FROM TJBB_DT_B01109 T
       WHERE T.SWJGDM=V_SWCODE AND T.SSNY=LC_THISMONTH AND T.BBLC='01';
      IF ROUND(ABS(LN_AMT_TARGET - LN_AMT_REFER),0)>2 THEN
        INSERT INTO TJBB_SB_JYXX(ID,SWJGDM,SSNY,BBDLDM,BBDM,MSG_TYPE,MSG_LEVEL,MSG)
             SELECT SEQ_NEXTVAL('SEQ_TJBB_SB_JYXX'),V_SWCODE,LC_THISMONTH,V_BBDLDM,'B01100','1','2','出口退（免）税情况分析月报表（主表）,审核通过应退（免）税额应与《出口退（免）税情况分析月报表（累计情况）》对应栏一致'
;
        COMMIT;
      END IF;

      SELECT T.SP_TK_XJ
        INTO LN_AMT_TARGET
        FROM TJBB_DT_B01100 T
       WHERE T.SWJGDM=V_SWCODE AND T.SSNY=LC_THISMONTH AND T.BBLC='01';
      SELECT T.SP_TMSE_XJ
        INTO LN_AMT_REFER
        FROM TJBB_DT_B01109 T
       WHERE T.SWJGDM=V_SWCODE AND T.SSNY=LC_THISMONTH AND T.BBLC='01';
      IF ROUND(ABS(LN_AMT_TARGET - LN_AMT_REFER),0)>2 THEN
        INSERT INTO TJBB_SB_JYXX(ID,SWJGDM,SSNY,BBDLDM,BBDM,MSG_TYPE,MSG_LEVEL,MSG)
             SELECT SEQ_NEXTVAL('SEQ_TJBB_SB_JYXX'),V_SWCODE,LC_THISMONTH,V_BBDLDM,'B01100','1','2','出口退（免）税情况分析月报表（主表）,审批应退（免）税额应与《出口退（免）税情况分析月报表（累计情况）》对应栏一致'
;
        COMMIT;
      END IF;

      SELECT T.BL_TK_XJ
        INTO LN_AMT_TARGET
        FROM TJBB_DT_B01100 T
       WHERE T.SWJGDM=V_SWCODE AND T.SSNY=LC_THISMONTH AND T.BBLC='01';
      SELECT T.TK_XJ
        INTO LN_AMT_REFER
        FROM TJBB_DT_B01109 T
       WHERE T.SWJGDM=V_SWCODE AND T.SSNY=LC_THISMONTH AND T.BBLC='01';
      IF ROUND(ABS(LN_AMT_TARGET - LN_AMT_REFER),0)>2 THEN
        INSERT INTO TJBB_SB_JYXX(ID,SWJGDM,SSNY,BBDLDM,BBDM,MSG_TYPE,MSG_LEVEL,MSG)
             SELECT SEQ_NEXTVAL('SEQ_TJBB_SB_JYXX'),V_SWCODE,LC_THISMONTH,V_BBDLDM,'B01100','1','2','出口退（免）税情况分析月报表（主表）,国库已办理退（调）库额应与《出口退（免）税情况分析月报表（累计情况）》对应栏一致'
;
        COMMIT;
      END IF;

      BEGIN
  DECLARE BJTS_SQLCODE_002 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_002 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_002 = MYSQL_ERRNO, BJTS_SQLERRM_002 = MESSAGE_TEXT;
          SET LN_AMT_REFER =0;

  END;
SELECT IFNULL(T.BL_TK_XJ, 0)
          INTO LN_AMT_REFER
          FROM TJBB_DT_B01100 T
         WHERE T.SWJGDM=V_SWCODE AND T.SSNY=LC_PREVMONTH AND T.BBLC='01';
      END;
      IF SUBSTR(LC_THISMONTH,5,2)<>'01' AND LN_AMT_TARGET<LN_AMT_REFER THEN
        INSERT INTO TJBB_SB_JYXX(ID,SWJGDM,SSNY,BBDLDM,BBDM,MSG_TYPE,MSG_LEVEL,MSG)
             SELECT SEQ_NEXTVAL('SEQ_TJBB_SB_JYXX'),V_SWCODE,LC_THISMONTH,V_BBDLDM,'B01100','2','2','出口退（免）税情况分析月报表（主表）,国库已办理退（调）库额小计，本月累计数不应小于上月累计数（年初除外）'
;
        COMMIT;
      END IF;

      SELECT COUNT(1)
        INTO LN_AMT_TARGET
        FROM TJBB_DT_B01100 T
       WHERE T.SWJGDM=V_SWCODE AND T.SSNY=LC_THISMONTH AND T.BBLC='01'
         AND ABS(T.SB_TMSE_XJ-T.SH_TMSE_XJ-T.ZH_TMSE_XJ-T.BY_TMSE_XJ-T.ZT_TMSE_XJ)>2;
      IF LN_AMT_TARGET=1 THEN
        INSERT INTO TJBB_SB_JYXX(ID,SWJGDM,SSNY,BBDLDM,BBDM,MSG_TYPE,MSG_LEVEL,MSG)
             SELECT SEQ_NEXTVAL('SEQ_TJBB_SB_JYXX'),V_SWCODE,LC_THISMONTH,V_BBDLDM,'B01100','2','2','出口退（免）税情况分析月报表（主表）,申报受理退（免）税额小计应于审核情况的退（免）税额小计之和一致'
;
        COMMIT;
      END IF;

      SELECT T.ZT_TMSE_XJ, T.ZT_TK
        INTO LN_AMT_TARGET, LN_AMT_REFER
        FROM TJBB_DT_B01100 T
       WHERE T.SWJGDM=V_SWCODE AND T.SSNY=LC_THISMONTH AND T.BBLC='01';
      IF LN_AMT_TARGET<-2 THEN
        INSERT INTO TJBB_SB_JYXX(ID,SWJGDM,SSNY,BBDLDM,BBDM,MSG_TYPE,MSG_LEVEL,MSG)
             SELECT SEQ_NEXTVAL('SEQ_TJBB_SB_JYXX'),V_SWCODE,LC_THISMONTH,V_BBDLDM,'B01100','2','2','出口退（免）税情况分析月报表（主表）,审核在途数小计小于0，请确认'
;
        COMMIT;
      END IF;
      IF LN_AMT_REFER<-2 THEN
        INSERT INTO TJBB_SB_JYXX(ID,SWJGDM,SSNY,BBDLDM,BBDM,MSG_TYPE,MSG_LEVEL,MSG)
             SELECT SEQ_NEXTVAL('SEQ_TJBB_SB_JYXX'),V_SWCODE,LC_THISMONTH,V_BBDLDM,'B01100','2','2','出口退（免）税情况分析月报表（主表）,退（调）库在途数小计小于0，请确认'
;
        COMMIT;
      END IF;

      SELECT T.JE
        INTO LN_AMT_TARGET
        FROM TJBB_DT_B01105 T
       WHERE T.SWJGDM=V_SWCODE AND T.SSNY=LC_THISMONTH AND T.BBLC='01';
      IF LN_AMT_TARGET>10000 THEN
        INSERT INTO TJBB_SB_JYXX(ID,SWJGDM,SSNY,BBDLDM,BBDM,MSG_TYPE,MSG_LEVEL,MSG)
             SELECT SEQ_NEXTVAL('SEQ_TJBB_SB_JYXX'),V_SWCODE,LC_THISMONTH,V_BBDLDM,'B01105','2','2','出口退税返还情况月报表，返还金额大于1亿，请确认'
;
        COMMIT;
      END IF;
    END;
  END IF;

  IF V_BBDLDM IN ('B01','B02') THEN
    BEGIN
  DECLARE BJTS_SQLCODE_001 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_001 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_001 = MYSQL_ERRNO, BJTS_SQLERRM_001 = MESSAGE_TEXT;
        INSERT INTO TJBB_SB_JYXX(ID,SWJGDM,SSNY,BBDLDM,BBDM,MSG_TYPE,MSG_LEVEL,MSG)
             SELECT SEQ_NEXTVAL('SEQ_TJBB_SB_JYXX'),V_SWCODE,LC_THISMONTH,V_BBDLDM,'B01100','1','2','总局出口退（免）税月报表 或 总局专项报表 未制表，无法比较勾稽关系！'
;
        COMMIT;

  END;
SELECT IFNULL(T.BL_TK_XJ, 0)
        INTO LN_AMT_TARGET
        FROM TJBB_DT_B01100 T
       WHERE T.SWJGDM=V_SWCODE AND T.SSNY=LC_THISMONTH AND T.BBLC='01';
      SELECT IFNULL(T.BL_TMSE_HJ, 0)
        INTO LN_AMT_REFER
        FROM TJBB_DT_B02101 T
       WHERE T.SWJGDM=V_SWCODE AND T.SSNY=LC_THISMONTH AND T.BBLC='0001';
      IF ROUND(ABS(LN_AMT_TARGET - LN_AMT_REFER),0)>2 THEN
        INSERT INTO TJBB_SB_JYXX(ID,SWJGDM,SSNY,BBDLDM,BBDM,MSG_TYPE,MSG_LEVEL,MSG)
             SELECT SEQ_NEXTVAL('SEQ_TJBB_SB_JYXX'),V_SWCODE,LC_THISMONTH,V_BBDLDM,'B01100','1','2','出口退（免）税情况分析月报表（主表）,国库已办理退（调）库额应与《无纸化统计表》对应栏一致'
;
        COMMIT;
      END IF;

      SELECT IFNULL(T.RDHS, 0)
        INTO LN_AMT_TARGET
        FROM TJBB_DT_B01100 T
       WHERE T.SWJGDM=V_SWCODE AND T.SSNY=LC_THISMONTH AND T.BBLC='07';
      SELECT COUNT(1)
        INTO LN_AMT_REFER
        FROM TJBB_DT_B02107 T
       WHERE (T.SWJGDM=V_SWCODE OR T.SWJGDM IN (SELECT VIR_SWJGDM AS SWJG_DM
       FROM DM_SWJG_VIRTUAL
      WHERE SUBSTR(V_SWCODE, 1, 1) = '2'
        AND SWJG_DM = V_SWCODE
        AND YXBZ = 'Y'
        AND VIR_FLAG = '0'
      UNION ALL
     SELECT SWJG_DM AS SWJG_DM
       FROM DM_SWJG
      WHERE (SUBSTR(V_SWCODE, 1, 1) <> '2' OR SUBSTR(V_SWCODE, 1, 1) IS NULL)
        AND SWJG_DM_SJ = V_SWCODE
        AND TSJG_BZ = '1')) AND T.SSNY=LC_THISMONTH;
      IF ROUND(ABS(LN_AMT_TARGET - LN_AMT_REFER),0)>0 THEN
        INSERT INTO TJBB_SB_JYXX(ID,SWJGDM,SSNY,BBDLDM,BBDM,MSG_TYPE,MSG_LEVEL,MSG)
             SELECT SEQ_NEXTVAL('SEQ_TJBB_SB_JYXX'),V_SWCODE,LC_THISMONTH,V_BBDLDM,'B01100','1','2','出口退（免）税情况分析月报表（主表）,外综服企业备案户数应与《外贸综合服务企业基本信息表》外综服企业户数一致'
