        FROM TJBB_DT_B01100 T
       WHERE T.SWJGDM=V_SWCODE AND T.SSNY=LC_THISMONTH AND T.BBLC='07';
      SELECT IFNULL(SUM(T.BL_TKE_YEAR), 0)
        INTO LN_AMT_REFER
        FROM TJBB_DT_B02108 T
       WHERE (T.SWJGDM=V_SWCODE OR T.SWJGDM IN (SELECT VIR_SWJGDM AS SWJG_DM
