        FROM TJBB_DT_B01100 T
       WHERE T.SWJGDM=V_SWCODE AND T.SSNY=LC_THISMONTH AND T.BBLC='02';
      SELECT NVL(T.TMSE_YEAR,0)
        INTO LN_AMT_REFER
        FROM TJBB_DT_B03103 T
       WHERE T.SWJGDM=V_SWCODE AND T.SSNY=LC_THISMONTH AND T.BBLC=SUBSTR(V_SWCODE, 4, 4)|| '0001';
      IF ROUND(ABS(LN_AMT_TARGET - LN_AMT_REFER),0)>2 THEN
