      IF ROUND(ABS(LN_AMT_TARGET - LN_AMT_REFER),0)>2 THEN
        INSERT INTO TJBB_SB_JYXX(ID,SWJGDM,SSNY,BBDLDM,BBDM,MSG_TYPE,MSG_LEVEL,MSG)
             SELECT SEQ_TJBB_SB_JYXX.NEXTVAL,V_SWCODE,LC_THISMONTH,V_BBDLDM,'B01100','1','2','出口退（免）税情况分析月报表（本月情况）,本月办理退库额应与《浙江省办理出口退（免）税情况统计表》对应栏一致'
               FROM DUAL;
        COMMIT;
      END IF;

      SELECT NVL(T.TK_XJ,0)
        INTO LN_AMT_TARGET
        FROM TJBB_DT_B01108 T
       WHERE T.SWJGDM=V_SWCODE AND T.SSNY=LC_THISMONTH AND T.BBLC='03';
      SELECT NVL(T.TKE_MON,0)
        INTO LN_AMT_REFER
        FROM TJBB_DT_B03103 T
       WHERE T.SWJGDM=V_SWCODE AND T.SSNY=LC_THISMONTH AND T.BBLC=SUBSTR(V_SWCODE, 4, 4)|| '0001';
      IF ROUND(ABS(LN_AMT_TARGET - LN_AMT_REFER),0)>2 THEN
        INSERT INTO TJBB_SB_JYXX(ID,SWJGDM,SSNY,BBDLDM,BBDM,MSG_TYPE,MSG_LEVEL,MSG)
             SELECT SEQ_TJBB_SB_JYXX.NEXTVAL,V_SWCODE,LC_THISMONTH,V_BBDLDM,'B01100','1','2','出口退（免）税情况分析月报表（本月情况）,本月办理调库额应与《浙江省办理出口退（免）税情况统计表》对应栏一致'
