-- ======================================================================
DELIMITER $$

DROP PROCEDURE IF EXISTS PRO_TJBB_DT_B01101_CSH_NEW$$

CREATE PROCEDURE PRO_TJBB_DT_B01101_CSH_NEW
/*************************************************
 * 暂缓退（免）税统计月报表
 * 202202，针对同时申报出口货物劳务以及服务贸易的企业，调整lctjjc
 ************************************************/
(
  IN V_SWCODE VARCHAR(4000),
  IN V_SSNY VARCHAR(4000),
  OUT V_ERROR DECIMAL(38,10),
  OUT V_MSG VARCHAR(4000)
)
routine_body: BEGIN
  DECLARE LD_SYSDATE       DATETIME;
  DECLARE LC_THISMONTH     VARCHAR(6);
  DECLARE LD_THISYEAR      DATETIME;
  DECLARE LD_NEXTMONTH     DATETIME;

  DECLARE LN_SBHS          BIGINT;
  DECLARE LN_SBHS11        BIGINT;
  DECLARE LN_SBHS12        BIGINT;
  DECLARE LN_SBHS14        BIGINT;
  DECLARE LN_SBHS_ZZS      BIGINT;
  DECLARE LN_SBHS_ZZS11    BIGINT;
  DECLARE LN_SBHS_ZZS12    BIGINT;
  DECLARE LN_SBHS_ZZS14    BIGINT;

  DECLARE LN_ZH_ZZS_HIS11  DECIMAL(18,6);
  DECLARE LN_ZH_ZZS_CUR11  DECIMAL(18,6);
  DECLARE LN_ZH_ZZS_HIS12  DECIMAL(18,6);
  DECLARE LN_ZH_ZZS_CUR12  DECIMAL(18,6);
  DECLARE LN_ZH_ZZS_HIS14  DECIMAL(18,6);
  DECLARE LN_ZH_ZZS_CUR14  DECIMAL(18,6);

  DECLARE LN_ZH_XFS_HIS11  DECIMAL(18,6);
  DECLARE LN_ZH_XFS_CUR11  DECIMAL(18,6);
  DECLARE LN_ZH_XFS_HIS12  DECIMAL(18,6);
  DECLARE LN_ZH_XFS_CUR12  DECIMAL(18,6);
  DECLARE LN_ZH_XFS_HIS14  DECIMAL(18,6);
  DECLARE LN_ZH_XFS_CUR14  DECIMAL(18,6);

  DECLARE LC_SQL           VARCHAR(4000);
  DECLARE LC_SQL_UPDATEHZ  VARCHAR(4000);

  SET V_ERROR =0;
  SET V_MSG = ' ';

  IF V_SSNY IS NOT NULL THEN
    SET LD_SYSDATE =STR_TO_DATE(ORA_CONCAT(V_SSNY, '01'), '%Y%m%d');
  ELSE
    SET LD_SYSDATE =CAST(DATE_FORMAT(CURRENT_TIMESTAMP, '%Y-%m-01') AS DATETIME);
  END IF;
  SET LC_THISMONTH =DATE_FORMAT(LD_SYSDATE, '%Y%m');
  SET LD_THISYEAR =MAKEDATE(YEAR(LD_SYSDATE), 1);
  SET LD_NEXTMONTH =CAST(DATE_FORMAT(DATE_ADD(LD_SYSDATE, INTERVAL 1 MONTH), '%Y-%m-01') AS DATETIME);

  -- 0、初始化
  BEGIN
  DECLARE BJTS_SQLCODE_012 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_012 TEXT DEFAULT '';
    -- 清除原有制表数据、准备重新制表

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_012 = MYSQL_ERRNO, BJTS_SQLERRM_012 = MESSAGE_TEXT;
      SET V_ERROR = BJTS_SQLCODE_012;
      SET V_MSG = BJTS_SQLERRM_012;
      LEAVE routine_body;

  END;
DELETE FROM TJBB_DT_B01101 WHERE SWJGDM=V_SWCODE AND SSNY=LC_THISMONTH;
    COMMIT;
  END;

  -- 1-1、外贸企业
  BEGIN
  DECLARE BJTS_SQLCODE_011 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_011 TEXT DEFAULT '';
    -- 暂缓

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_011 = MYSQL_ERRNO, BJTS_SQLERRM_011 = MESSAGE_TEXT;
      SET V_ERROR = BJTS_SQLCODE_011;
      SET V_MSG = BJTS_SQLERRM_011;

  END;
SELECT COUNT(DISTINCT DJXH),
           COUNT(DISTINCT(CASE WHEN T.SHZT=11 THEN DJXH ELSE NULL END)),
           COUNT(DISTINCT(CASE WHEN T.SHZT=12 THEN DJXH ELSE NULL END)),
           COUNT(DISTINCT(CASE WHEN T.SHZT=14 THEN DJXH ELSE NULL END)),
           COUNT(DISTINCT(CASE WHEN T.SZ='V' THEN DJXH ELSE NULL END)),
           COUNT(DISTINCT(CASE WHEN T.SZ='V' AND T.SHZT=11 THEN DJXH ELSE NULL END)),
           COUNT(DISTINCT(CASE WHEN T.SZ='V' AND T.SHZT=12 THEN DJXH ELSE NULL END)),
           COUNT(DISTINCT(CASE WHEN T.SZ='V' AND T.SHZT=14 THEN DJXH ELSE NULL END)),
           ROUND(IFNULL(SUM(CASE WHEN T.SZ='V' AND T.SHZT=11 AND T.CKRQ_1< LD_THISYEAR THEN T.TSE ELSE 0 END), 0)/10000,6), -- 发函未回
           ROUND(IFNULL(SUM(CASE WHEN T.SZ='V' AND T.SHZT=11 AND T.CKRQ_1>=LD_THISYEAR THEN T.TSE ELSE 0 END), 0)/10000,6), -- 发函未回
           ROUND(IFNULL(SUM(CASE WHEN T.SZ='V' AND T.SHZT=12 AND T.CKRQ_1< LD_THISYEAR THEN T.TSE ELSE 0 END), 0)/10000,6), -- 回函有疑点
           ROUND(IFNULL(SUM(CASE WHEN T.SZ='V' AND T.SHZT=12 AND T.CKRQ_1>=LD_THISYEAR THEN T.TSE ELSE 0 END), 0)/10000,6), -- 回函有疑点
           ROUND(IFNULL(SUM(CASE WHEN T.SZ='V' AND T.SHZT=14 AND T.CKRQ_1< LD_THISYEAR THEN T.TSE ELSE 0 END), 0)/10000,6), -- 有疑点核查中
           ROUND(IFNULL(SUM(CASE WHEN T.SZ='V' AND T.SHZT=14 AND T.CKRQ_1>=LD_THISYEAR THEN T.TSE ELSE 0 END), 0)/10000,6), -- 有疑点核查中
           ROUND(IFNULL(SUM(CASE WHEN T.SZ='C' AND T.SHZT=11 AND T.CKRQ_1< LD_THISYEAR THEN T.TSE ELSE 0 END), 0)/10000,6), -- 发函未回
           ROUND(IFNULL(SUM(CASE WHEN T.SZ='C' AND T.SHZT=11 AND T.CKRQ_1>=LD_THISYEAR THEN T.TSE ELSE 0 END), 0)/10000,6), -- 发函未回
           ROUND(IFNULL(SUM(CASE WHEN T.SZ='C' AND T.SHZT=12 AND T.CKRQ_1< LD_THISYEAR THEN T.TSE ELSE 0 END), 0)/10000,6), -- 回函有疑点
           ROUND(IFNULL(SUM(CASE WHEN T.SZ='C' AND T.SHZT=12 AND T.CKRQ_1>=LD_THISYEAR THEN T.TSE ELSE 0 END), 0)/10000,6), -- 回函有疑点
           ROUND(IFNULL(SUM(CASE WHEN T.SZ='C' AND T.SHZT=14 AND T.CKRQ_1< LD_THISYEAR THEN T.TSE ELSE 0 END), 0)/10000,6), -- 有疑点核查中
           ROUND(IFNULL(SUM(CASE WHEN T.SZ='C' AND T.SHZT=14 AND T.CKRQ_1>=LD_THISYEAR THEN T.TSE ELSE 0 END), 0)/10000,6)  -- 有疑点核查中
      INTO LN_SBHS, LN_SBHS11, LN_SBHS12, LN_SBHS14, LN_SBHS_ZZS, LN_SBHS_ZZS11, LN_SBHS_ZZS12, LN_SBHS_ZZS14,
           LN_ZH_ZZS_HIS11, LN_ZH_ZZS_CUR11, LN_ZH_ZZS_HIS12, LN_ZH_ZZS_CUR12, LN_ZH_ZZS_HIS14, LN_ZH_ZZS_CUR14,
           LN_ZH_XFS_HIS11, LN_ZH_XFS_CUR11, LN_ZH_XFS_HIS12, LN_ZH_XFS_CUR12, LN_ZH_XFS_HIS14, LN_ZH_XFS_CUR14
      FROM (SELECT A.DJXH,B.SBXH,B.CKRQ_1,B.SZ,
                   CASE WHEN TRIM(A.LCSLID_FS) IS NOT NULL AND B.ZBBLBZ='Y' THEN 14
                        WHEN TRIM(A.LCSLID_FS) IS NOT NULL AND B.BYTSBZ='Y' THEN 20
                        WHEN TRIM(A.LCSLID_FS) IS NOT NULL THEN 30
                        WHEN TRIM(A.LCSLID_FS) IS NULL AND A.LCSLID_SB<>A.LCSLID THEN 11
                        ELSE 40 END AS SHZT,
                   B.TSE * CASE WHEN B.SZ='V' THEN (CASE WHEN TRIM(A.LCSLID_FS) IS NULL THEN 1
                                                         WHEN A.ZY_ZZSTSE=0 THEN 1
                                                         WHEN A.SNBL_ZZSTSE=0 THEN 1
                                                         WHEN A.SNBL_ZZSTSE>0 AND (B.ZBBLBZ='Y' OR B.BYTSBZ='Y') THEN 0
                                                         ELSE LEAST(GREATEST(1 - A.SNBL_ZZSTSE / A.ZY_ZZSTSE,0),1)
                                                    END)
                           ELSE (CASE WHEN TRIM(A.LCSLID_FS) IS NULL THEN 1
                                      WHEN A.ZY_XFSTSE=0 THEN 1
                                      WHEN A.SNBL_XFSTSE=0 THEN 1
                                      WHEN A.SNBL_XFSTSE>0 AND (B.ZBBLBZ='Y' OR B.BYTSBZ='Y') THEN 0
                                      ELSE LEAST(GREATEST(1 - A.SNBL_XFSTSE / A.ZY_XFSTSE,0),1)
                                 END)
                           END AS TSE
              FROM CKTS_LC_SHXX A
             INNER JOIN CKTS_SB_MTS_JHMX B ON B.LCSLID=A.LCSLID AND B.BYBLBZ='N'
             WHERE A.TSSWJG_DM=V_SWCODE
               AND A.LCTJJC IN ('10','40','50')
               AND A.QDSJ<LD_NEXTMONTH
               AND A.LCJSRQ>=LD_THISYEAR) T
     WHERE T.SHZT LIKE '1%';

    INSERT INTO TJBB_DT_B01101 (SSNY, BBLC, SWJGDM,
           HJ_QYHS, HJ_TSE,
           FH_QYHS, FH_TSE_HJ, FH_TSE_HIS, FH_TSE_CUR,
           HH_QYHS, HH_TSE_HJ, HH_TSE_HIS, HH_TSE_CUR,
           DC_QYHS, DC_TSE_HJ, DC_TSE_HIS, DC_TSE_CUR,
           YD_QYHS, YD_TSE_HJ, YD_TSE_HIS, YD_TSE_CUR)
    SELECT LC_THISMONTH, '05', V_SWCODE,
           LN_SBHS_ZZS, LN_ZH_ZZS_HIS11 + LN_ZH_ZZS_CUR11 + LN_ZH_ZZS_HIS12 + LN_ZH_ZZS_CUR12 + LN_ZH_ZZS_HIS14 + LN_ZH_ZZS_CUR14,
           LN_SBHS_ZZS11, LN_ZH_ZZS_HIS11 + LN_ZH_ZZS_CUR11, LN_ZH_ZZS_HIS11, LN_ZH_ZZS_CUR11,
           LN_SBHS_ZZS12, LN_ZH_ZZS_HIS12 + LN_ZH_ZZS_CUR12, LN_ZH_ZZS_HIS12, LN_ZH_ZZS_CUR12,
           0, 0, 0, 0,
           LN_SBHS_ZZS14, LN_ZH_ZZS_HIS14 + LN_ZH_ZZS_CUR14, LN_ZH_ZZS_HIS14, LN_ZH_ZZS_CUR14

     UNION ALL
    SELECT LC_THISMONTH, '06', V_SWCODE,
           LN_SBHS - LN_SBHS_ZZS, LN_ZH_XFS_HIS11 + LN_ZH_XFS_CUR11 + LN_ZH_XFS_HIS12 + LN_ZH_XFS_CUR12 + LN_ZH_XFS_HIS14 + LN_ZH_XFS_CUR14,
           LN_SBHS11 - LN_SBHS_ZZS11, LN_ZH_XFS_HIS11 + LN_ZH_XFS_CUR11, LN_ZH_XFS_HIS11, LN_ZH_XFS_CUR11,
           LN_SBHS12 - LN_SBHS_ZZS12, LN_ZH_XFS_HIS12 + LN_ZH_XFS_CUR12, LN_ZH_XFS_HIS12, LN_ZH_XFS_CUR12,
           0, 0, 0, 0,
           LN_SBHS14 - LN_SBHS_ZZS14, LN_ZH_XFS_HIS14 + LN_ZH_XFS_CUR14, LN_ZH_XFS_HIS14, LN_ZH_XFS_CUR14
;
    COMMIT;
  END;

  -- 1-2、外综服企业
  BEGIN
  DECLARE BJTS_SQLCODE_010 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_010 TEXT DEFAULT '';
    -- 暂缓

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_010 = MYSQL_ERRNO, BJTS_SQLERRM_010 = MESSAGE_TEXT;
      SET V_ERROR = BJTS_SQLCODE_010;
      SET V_MSG = BJTS_SQLERRM_010;

  END;
SELECT COUNT(DISTINCT DJXH),
           COUNT(DISTINCT(CASE WHEN T.SHZT=11 THEN DJXH ELSE NULL END)),
           COUNT(DISTINCT(CASE WHEN T.SHZT=12 THEN DJXH ELSE NULL END)),
           COUNT(DISTINCT(CASE WHEN T.SHZT=14 THEN DJXH ELSE NULL END)),
           COUNT(DISTINCT(CASE WHEN T.SZ='V' THEN DJXH ELSE NULL END)),
           COUNT(DISTINCT(CASE WHEN T.SZ='V' AND T.SHZT=11 THEN DJXH ELSE NULL END)),
           COUNT(DISTINCT(CASE WHEN T.SZ='V' AND T.SHZT=12 THEN DJXH ELSE NULL END)),
           COUNT(DISTINCT(CASE WHEN T.SZ='V' AND T.SHZT=14 THEN DJXH ELSE NULL END)),
           ROUND(IFNULL(SUM(CASE WHEN T.SZ='V' AND T.SHZT=11 AND T.CKRQ_1< LD_THISYEAR THEN T.TSE ELSE 0 END), 0)/10000,6), -- 发函未回
           ROUND(IFNULL(SUM(CASE WHEN T.SZ='V' AND T.SHZT=11 AND T.CKRQ_1>=LD_THISYEAR THEN T.TSE ELSE 0 END), 0)/10000,6), -- 发函未回
           ROUND(IFNULL(SUM(CASE WHEN T.SZ='V' AND T.SHZT=12 AND T.CKRQ_1< LD_THISYEAR THEN T.TSE ELSE 0 END), 0)/10000,6), -- 回函有疑点
           ROUND(IFNULL(SUM(CASE WHEN T.SZ='V' AND T.SHZT=12 AND T.CKRQ_1>=LD_THISYEAR THEN T.TSE ELSE 0 END), 0)/10000,6), -- 回函有疑点
           ROUND(IFNULL(SUM(CASE WHEN T.SZ='V' AND T.SHZT=14 AND T.CKRQ_1< LD_THISYEAR THEN T.TSE ELSE 0 END), 0)/10000,6), -- 有疑点核查中
           ROUND(IFNULL(SUM(CASE WHEN T.SZ='V' AND T.SHZT=14 AND T.CKRQ_1>=LD_THISYEAR THEN T.TSE ELSE 0 END), 0)/10000,6), -- 有疑点核查中
           ROUND(IFNULL(SUM(CASE WHEN T.SZ='C' AND T.SHZT=11 AND T.CKRQ_1< LD_THISYEAR THEN T.TSE ELSE 0 END), 0)/10000,6), -- 发函未回
           ROUND(IFNULL(SUM(CASE WHEN T.SZ='C' AND T.SHZT=11 AND T.CKRQ_1>=LD_THISYEAR THEN T.TSE ELSE 0 END), 0)/10000,6), -- 发函未回
           ROUND(IFNULL(SUM(CASE WHEN T.SZ='C' AND T.SHZT=12 AND T.CKRQ_1< LD_THISYEAR THEN T.TSE ELSE 0 END), 0)/10000,6), -- 回函有疑点
           ROUND(IFNULL(SUM(CASE WHEN T.SZ='C' AND T.SHZT=12 AND T.CKRQ_1>=LD_THISYEAR THEN T.TSE ELSE 0 END), 0)/10000,6), -- 回函有疑点
           ROUND(IFNULL(SUM(CASE WHEN T.SZ='C' AND T.SHZT=14 AND T.CKRQ_1< LD_THISYEAR THEN T.TSE ELSE 0 END), 0)/10000,6), -- 有疑点核查中
           ROUND(IFNULL(SUM(CASE WHEN T.SZ='C' AND T.SHZT=14 AND T.CKRQ_1>=LD_THISYEAR THEN T.TSE ELSE 0 END), 0)/10000,6)  -- 有疑点核查中
      INTO LN_SBHS, LN_SBHS11, LN_SBHS12, LN_SBHS14, LN_SBHS_ZZS, LN_SBHS_ZZS11, LN_SBHS_ZZS12, LN_SBHS_ZZS14,
           LN_ZH_ZZS_HIS11, LN_ZH_ZZS_CUR11, LN_ZH_ZZS_HIS12, LN_ZH_ZZS_CUR12, LN_ZH_ZZS_HIS14, LN_ZH_ZZS_CUR14,
           LN_ZH_XFS_HIS11, LN_ZH_XFS_CUR11, LN_ZH_XFS_HIS12, LN_ZH_XFS_CUR12, LN_ZH_XFS_HIS14, LN_ZH_XFS_CUR14
      FROM (SELECT A.DJXH,B.SBXH,B.CKRQ_1,B.SZ,
                   CASE WHEN TRIM(A.LCSLID_FS) IS NOT NULL AND B.ZBBLBZ='Y' THEN 14
                        WHEN TRIM(A.LCSLID_FS) IS NOT NULL AND B.BYTSBZ='Y' THEN 20
                        WHEN TRIM(A.LCSLID_FS) IS NOT NULL THEN 30
                        WHEN TRIM(A.LCSLID_FS) IS NULL AND A.LCSLID_SB<>A.LCSLID THEN 11
                        ELSE 40 END AS SHZT,
                   B.TSE * CASE WHEN B.SZ='V' THEN (CASE WHEN TRIM(A.LCSLID_FS) IS NULL THEN 1
                                                         WHEN A.ZY_ZZSTSE=0 THEN 1
                                                         WHEN A.SNBL_ZZSTSE=0 THEN 1
                                                         WHEN A.SNBL_ZZSTSE>0 AND (B.ZBBLBZ='Y' OR B.BYTSBZ='Y') THEN 0
                                                         ELSE LEAST(GREATEST(1 - A.SNBL_ZZSTSE / A.ZY_ZZSTSE,0),1)
                                                    END)
                           ELSE (CASE WHEN TRIM(A.LCSLID_FS) IS NULL THEN 1
                                      WHEN A.ZY_XFSTSE=0 THEN 1
                                      WHEN A.SNBL_XFSTSE=0 THEN 1
                                      WHEN A.SNBL_XFSTSE>0 AND (B.ZBBLBZ='Y' OR B.BYTSBZ='Y') THEN 0
                                      ELSE LEAST(GREATEST(1 - A.SNBL_XFSTSE / A.ZY_XFSTSE,0),1)
                                 END)
                           END AS TSE
              FROM CKTS_LC_SHXX A
             INNER JOIN CKTS_SB_MTS_JHMX B ON B.LCSLID=A.LCSLID AND B.BYBLBZ='N'
             WHERE A.TSSWJG_DM=V_SWCODE
               AND A.LCTJJC IN ('70','71')
               AND A.QDSJ<LD_NEXTMONTH
               AND A.LCJSRQ>=LD_THISYEAR
             UNION ALL
            SELECT A.DJXH,B.SBXH,B.CKRQ_1,'V' AS SZ,
                   CASE WHEN TRIM(A.LCSLID_FS) IS NOT NULL AND B.ZBBLBZ='Y' THEN 14
                        WHEN TRIM(A.LCSLID_FS) IS NOT NULL AND B.BYTSBZ='Y' THEN 20
                        WHEN TRIM(A.LCSLID_FS) IS NOT NULL THEN 30
                        WHEN TRIM(A.LCSLID_FS) IS NULL AND A.LCSLID_SB<>A.LCSLID THEN 11
                        ELSE 40 END AS SHZT,
                   B.TSE * CASE WHEN TRIM(A.LCSLID_FS) IS NULL THEN 1
                                WHEN A.ZY_MDTSE=0 THEN 1
                                WHEN A.SNBL_MDTSE=0 THEN 1
                                WHEN A.SNBL_MDTSE>0 AND (B.ZBBLBZ='Y' OR B.BYTSBZ='Y') THEN 0
                                ELSE LEAST(GREATEST(1 - A.SNBL_MDTSE / A.ZY_MDTSE,0),1)
                           END AS TSE
              FROM CKTS_LC_SHXX A
             INNER JOIN CKTS_SB_WZF_CKMX B ON B.LCSLID=A.LCSLID AND B.BYBLBZ='N'
             WHERE A.TSSWJG_DM=V_SWCODE
               AND A.LCTJJC = '72'
               AND A.QDSJ<LD_NEXTMONTH
               AND A.LCJSRQ>=LD_THISYEAR) T
     WHERE T.SHZT LIKE '1%';

    INSERT INTO TJBB_DT_B01101 (SSNY, BBLC, SWJGDM,
           HJ_QYHS, HJ_TSE,
           FH_QYHS, FH_TSE_HJ, FH_TSE_HIS, FH_TSE_CUR,
           HH_QYHS, HH_TSE_HJ, HH_TSE_HIS, HH_TSE_CUR,
           DC_QYHS, DC_TSE_HJ, DC_TSE_HIS, DC_TSE_CUR,
           YD_QYHS, YD_TSE_HJ, YD_TSE_HIS, YD_TSE_CUR)
    SELECT LC_THISMONTH, '08', V_SWCODE,
           LN_SBHS_ZZS, LN_ZH_ZZS_HIS11 + LN_ZH_ZZS_CUR11 + LN_ZH_ZZS_HIS12 + LN_ZH_ZZS_CUR12 + LN_ZH_ZZS_HIS14 + LN_ZH_ZZS_CUR14,
           LN_SBHS_ZZS11, LN_ZH_ZZS_HIS11 + LN_ZH_ZZS_CUR11, LN_ZH_ZZS_HIS11, LN_ZH_ZZS_CUR11,
           LN_SBHS_ZZS12, LN_ZH_ZZS_HIS12 + LN_ZH_ZZS_CUR12, LN_ZH_ZZS_HIS12, LN_ZH_ZZS_CUR12,
           0, 0, 0, 0,
           LN_SBHS_ZZS14, LN_ZH_ZZS_HIS14 + LN_ZH_ZZS_CUR14, LN_ZH_ZZS_HIS14, LN_ZH_ZZS_CUR14

     UNION ALL
    SELECT LC_THISMONTH, '09', V_SWCODE,
           LN_SBHS - LN_SBHS_ZZS, LN_ZH_XFS_HIS11 + LN_ZH_XFS_CUR11 + LN_ZH_XFS_HIS12 + LN_ZH_XFS_CUR12 + LN_ZH_XFS_HIS14 + LN_ZH_XFS_CUR14,
           LN_SBHS11 - LN_SBHS_ZZS11, LN_ZH_XFS_HIS11 + LN_ZH_XFS_CUR11, LN_ZH_XFS_HIS11, LN_ZH_XFS_CUR11,
           LN_SBHS12 - LN_SBHS_ZZS12, LN_ZH_XFS_HIS12 + LN_ZH_XFS_CUR12, LN_ZH_XFS_HIS12, LN_ZH_XFS_CUR12,
           0, 0, 0, 0,
           LN_SBHS14 - LN_SBHS_ZZS14, LN_ZH_XFS_HIS14 + LN_ZH_XFS_CUR14, LN_ZH_XFS_HIS14, LN_ZH_XFS_CUR14
;

    -- 1-2-1 符合13号公告规定业务
    SELECT COUNT(DISTINCT DJXH),
           COUNT(DISTINCT(CASE WHEN T.SHZT=11 THEN DJXH ELSE NULL END)),
           COUNT(DISTINCT(CASE WHEN T.SHZT=12 THEN DJXH ELSE NULL END)),
           COUNT(DISTINCT(CASE WHEN T.SHZT=14 THEN DJXH ELSE NULL END)),
           ROUND(IFNULL(SUM(CASE WHEN T.SHZT=11 AND T.CKRQ_1< LD_THISYEAR THEN T.TSE ELSE 0 END), 0)/10000,6), -- 发函未回
           ROUND(IFNULL(SUM(CASE WHEN T.SHZT=11 AND T.CKRQ_1>=LD_THISYEAR THEN T.TSE ELSE 0 END), 0)/10000,6), -- 发函未回
           ROUND(IFNULL(SUM(CASE WHEN T.SHZT=12 AND T.CKRQ_1< LD_THISYEAR THEN T.TSE ELSE 0 END), 0)/10000,6), -- 回函有疑点
           ROUND(IFNULL(SUM(CASE WHEN T.SHZT=12 AND T.CKRQ_1>=LD_THISYEAR THEN T.TSE ELSE 0 END), 0)/10000,6), -- 回函有疑点
           ROUND(IFNULL(SUM(CASE WHEN T.SHZT=14 AND T.CKRQ_1< LD_THISYEAR THEN T.TSE ELSE 0 END), 0)/10000,6), -- 有疑点核查中
           ROUND(IFNULL(SUM(CASE WHEN T.SHZT=14 AND T.CKRQ_1>=LD_THISYEAR THEN T.TSE ELSE 0 END), 0)/10000,6) -- 有疑点核查中
      INTO LN_SBHS_ZZS, LN_SBHS_ZZS11, LN_SBHS_ZZS12, LN_SBHS_ZZS14,
           LN_ZH_ZZS_HIS11, LN_ZH_ZZS_CUR11, LN_ZH_ZZS_HIS12, LN_ZH_ZZS_CUR12, LN_ZH_ZZS_HIS14, LN_ZH_ZZS_CUR14
      FROM (SELECT A.DJXH,B.SBXH,B.CKRQ_1,B.SZ,
                   CASE WHEN TRIM(A.LCSLID_FS) IS NOT NULL AND B.ZBBLBZ='Y' THEN 14
                        WHEN TRIM(A.LCSLID_FS) IS NOT NULL AND B.BYTSBZ='Y' THEN 20
                        WHEN TRIM(A.LCSLID_FS) IS NOT NULL THEN 30
                        WHEN TRIM(A.LCSLID_FS) IS NULL AND A.LCSLID_SB<>A.LCSLID THEN 11
                        ELSE 40 END AS SHZT,
                   B.TSE * CASE WHEN TRIM(A.LCSLID_FS) IS NULL THEN 1
                                WHEN A.ZY_MDTSE=0 THEN 1
                                  WHEN A.SNBL_MDTSE=0 THEN 1
                                  WHEN A.SNBL_MDTSE>0 AND (B.ZBBLBZ='Y' OR B.BYTSBZ='Y') THEN 0
                                  ELSE LEAST(GREATEST(1 - A.SNBL_MDTSE / A.ZY_MDTSE,0),1)
                             END AS TSE
              FROM CKTS_LC_SHXX A
             INNER JOIN CKTS_SB_MTS_JHMX B ON B.LCSLID=A.LCSLID AND B.BYBLBZ='N'
             WHERE A.TSSWJG_DM=V_SWCODE
               AND A.LCTJJC = '71'
               AND A.QDSJ<LD_NEXTMONTH
               AND A.LCJSRQ>=LD_THISYEAR) T
     WHERE T.SHZT LIKE '1%';

    INSERT INTO TJBB_DT_B01101 (SSNY, BBLC, SWJGDM,
           HJ_QYHS, HJ_TSE,
           FH_QYHS, FH_TSE_HJ, FH_TSE_HIS, FH_TSE_CUR,
           HH_QYHS, HH_TSE_HJ, HH_TSE_HIS, HH_TSE_CUR,
           DC_QYHS, DC_TSE_HJ, DC_TSE_HIS, DC_TSE_CUR,
           YD_QYHS, YD_TSE_HJ, YD_TSE_HIS, YD_TSE_CUR)
    SELECT LC_THISMONTH, '10', V_SWCODE,
           LN_SBHS_ZZS, LN_ZH_ZZS_HIS11 + LN_ZH_ZZS_CUR11 + LN_ZH_ZZS_HIS12 + LN_ZH_ZZS_CUR12 + LN_ZH_ZZS_HIS14 + LN_ZH_ZZS_CUR14,
           LN_SBHS_ZZS11, LN_ZH_ZZS_HIS11 + LN_ZH_ZZS_CUR11, LN_ZH_ZZS_HIS11, LN_ZH_ZZS_CUR11,
           LN_SBHS_ZZS12, LN_ZH_ZZS_HIS12 + LN_ZH_ZZS_CUR12, LN_ZH_ZZS_HIS12, LN_ZH_ZZS_CUR12,
           0, 0, 0, 0,
           LN_SBHS_ZZS14, LN_ZH_ZZS_HIS14 + LN_ZH_ZZS_CUR14, LN_ZH_ZZS_HIS14, LN_ZH_ZZS_CUR14
;
    COMMIT;
  END;

  -- 1-3、自营出口的生产企业
  BEGIN
  DECLARE BJTS_SQLCODE_009 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_009 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_009 = MYSQL_ERRNO, BJTS_SQLERRM_009 = MESSAGE_TEXT;
      SET V_ERROR = BJTS_SQLCODE_009;
      SET V_MSG = BJTS_SQLERRM_009;

  END;
SELECT COUNT(DISTINCT DJXH),
           COUNT(DISTINCT(CASE WHEN T.SHZT=11 THEN DJXH ELSE NULL END)),
           COUNT(DISTINCT(CASE WHEN T.SHZT=12 THEN DJXH ELSE NULL END)),
           COUNT(DISTINCT(CASE WHEN T.SHZT=14 THEN DJXH ELSE NULL END)),
           COUNT(DISTINCT(CASE WHEN T.TSE>0 THEN DJXH ELSE NULL END)),
           COUNT(DISTINCT(CASE WHEN T.TSE>0 AND T.SHZT=11 THEN DJXH ELSE NULL END)),
           COUNT(DISTINCT(CASE WHEN T.TSE>0 AND T.SHZT=12 THEN DJXH ELSE NULL END)),
           COUNT(DISTINCT(CASE WHEN T.TSE>0 AND T.SHZT=14 THEN DJXH ELSE NULL END)),
           ROUND(IFNULL(SUM(CASE WHEN T.SHZT=11 AND T.CKRQ_1< LD_THISYEAR THEN T.TSE ELSE 0 END), 0)/10000,6), -- 发函未回
           ROUND(IFNULL(SUM(CASE WHEN T.SHZT=11 AND T.CKRQ_1>=LD_THISYEAR THEN T.TSE ELSE 0 END), 0)/10000,6), -- 发函未回
           ROUND(IFNULL(SUM(CASE WHEN T.SHZT=12 AND T.CKRQ_1< LD_THISYEAR THEN T.TSE ELSE 0 END), 0)/10000,6), -- 回函有疑点
           ROUND(IFNULL(SUM(CASE WHEN T.SHZT=12 AND T.CKRQ_1>=LD_THISYEAR THEN T.TSE ELSE 0 END), 0)/10000,6), -- 回函有疑点
           ROUND(IFNULL(SUM(CASE WHEN T.SHZT=14 AND T.CKRQ_1< LD_THISYEAR THEN T.TSE ELSE 0 END), 0)/10000,6), -- 有疑点核查中
           ROUND(IFNULL(SUM(CASE WHEN T.SHZT=14 AND T.CKRQ_1>=LD_THISYEAR THEN T.TSE ELSE 0 END), 0)/10000,6), -- 有疑点核查中
           ROUND(IFNULL(SUM(CASE WHEN T.SHZT=11 AND T.CKRQ_1< LD_THISYEAR THEN T.MDE ELSE 0 END), 0)/10000,6), -- 发函未回
           ROUND(IFNULL(SUM(CASE WHEN T.SHZT=11 AND T.CKRQ_1>=LD_THISYEAR THEN T.MDE ELSE 0 END), 0)/10000,6), -- 发函未回
           ROUND(IFNULL(SUM(CASE WHEN T.SHZT=12 AND T.CKRQ_1< LD_THISYEAR THEN T.MDE ELSE 0 END), 0)/10000,6), -- 回函有疑点
           ROUND(IFNULL(SUM(CASE WHEN T.SHZT=12 AND T.CKRQ_1>=LD_THISYEAR THEN T.MDE ELSE 0 END), 0)/10000,6), -- 回函有疑点
           ROUND(IFNULL(SUM(CASE WHEN T.SHZT=14 AND T.CKRQ_1< LD_THISYEAR THEN T.MDE ELSE 0 END), 0)/10000,6), -- 有疑点核查中
           ROUND(IFNULL(SUM(CASE WHEN T.SHZT=14 AND T.CKRQ_1>=LD_THISYEAR THEN T.MDE ELSE 0 END), 0)/10000,6)  -- 有疑点核查中
      INTO LN_SBHS, LN_SBHS11, LN_SBHS12, LN_SBHS14, LN_SBHS_ZZS, LN_SBHS_ZZS11, LN_SBHS_ZZS12, LN_SBHS_ZZS14,
           LN_ZH_ZZS_HIS11, LN_ZH_ZZS_CUR11, LN_ZH_ZZS_HIS12, LN_ZH_ZZS_CUR12, LN_ZH_ZZS_HIS14, LN_ZH_ZZS_CUR14,
           LN_ZH_XFS_HIS11, LN_ZH_XFS_CUR11, LN_ZH_XFS_HIS12, LN_ZH_XFS_CUR12, LN_ZH_XFS_HIS14, LN_ZH_XFS_CUR14
      FROM (SELECT A.DJXH,B.LCSLID,B.SBXH,B.CKRQ_1,
                   CASE WHEN TRIM(A.LCSLID_FS) IS NOT NULL AND B.ZBBLBZ='Y' THEN 14
                        WHEN TRIM(A.LCSLID_FS) IS NOT NULL AND B.BYTSBZ='Y' THEN 20
                        WHEN TRIM(A.LCSLID_FS) IS NOT NULL THEN 30
                        WHEN TRIM(A.LCSLID_FS) IS NULL AND A.LCSLID_SB<>A.LCSLID THEN 14 -- 生产企业全部归类为：有疑点核查中
                        ELSE 40 END AS SHZT,
                   B.MYLAJ * CASE WHEN TRIM(A.LCSLID_FS) IS NULL THEN 1
                                  WHEN A.ZY_MDTSE=0 THEN 1
                                  WHEN A.SNBL_MDTSE=0 THEN 1
                                  WHEN A.SNBL_MDTSE>0 AND (B.ZBBLBZ='Y' OR B.BYTSBZ='Y') THEN 0
                                  ELSE LEAST(GREATEST(1 - A.SNBL_MDTSE / A.ZY_MDTSE,0),1)
                             END AS MYLAJ,
                   B.MDTSE * CASE WHEN TRIM(A.LCSLID_FS) IS NULL THEN (CASE WHEN A.SB_MDTSE=0 THEN 0 ELSE A.SB_ZZSTSE/A.SB_MDTSE END)
                                                           ELSE (CASE WHEN A.ZY_MDTSE=0 THEN 0 ELSE A.ZY_ZZSTSE/A.ZY_MDTSE END)
                             END -- 根据是否复审用申报数或复审数计算退税部分
                           * CASE WHEN TRIM(A.LCSLID_FS) IS NULL THEN 1
                                  WHEN A.ZY_ZZSTSE=0 THEN 1
                                  WHEN A.SNBL_ZZSTSE=0 THEN 1
                                  WHEN A.SNBL_ZZSTSE>0 AND (B.ZBBLBZ='Y' OR B.BYTSBZ='Y') THEN 0
                                  ELSE LEAST(GREATEST(1 - A.SNBL_ZZSTSE / A.ZY_ZZSTSE,0),1)
                             END AS TSE,
                   B.MDTSE * CASE WHEN TRIM(A.LCSLID_FS) IS NULL THEN (CASE WHEN A.SB_MDTSE=0 THEN 1 ELSE A.SB_MDSE/A.SB_MDTSE END)
                                                           ELSE (CASE WHEN A.ZY_MDTSE=0 THEN 1 ELSE A.ZY_MDSE/A.ZY_MDTSE END)
                             END
                           * CASE WHEN TRIM(A.LCSLID_FS) IS NULL THEN 1
                                  WHEN A.ZY_MDSE=0 THEN 1
                                  WHEN A.SNBL_MDSE=0 THEN 1
                                  WHEN A.SNBL_MDSE>0 AND (B.ZBBLBZ='Y' OR B.BYTSBZ='Y') THEN 0
                                  ELSE LEAST(GREATEST(1 - A.SNBL_MDSE / A.ZY_MDSE,0),1)
                             END AS MDE
              FROM CKTS_LC_SHXX A
             INNER JOIN CKTS_SB_MDT_CKMX B ON B.LCSLID=A.LCSLID AND B.BYBLBZ='N'
             WHERE A.TSSWJG_DM=V_SWCODE
               AND A.LCTJJC IN ('21','41','51','61')
               AND A.QDSJ<LD_NEXTMONTH
               AND A.LCJSRQ>=LD_THISYEAR) T
     WHERE T.SHZT LIKE '1%';

    INSERT INTO TJBB_DT_B01101 (SSNY, BBLC, SWJGDM,
           HJ_QYHS, HJ_TSE,
           FH_QYHS, FH_TSE_HJ, FH_TSE_HIS, FH_TSE_CUR,
           HH_QYHS, HH_TSE_HJ, HH_TSE_HIS, HH_TSE_CUR,
           DC_QYHS, DC_TSE_HJ, DC_TSE_HIS, DC_TSE_CUR,
           YD_QYHS, YD_TSE_HJ, YD_TSE_HIS, YD_TSE_CUR)
    SELECT LC_THISMONTH, '15', V_SWCODE,
           LN_SBHS_ZZS, LN_ZH_ZZS_HIS11 + LN_ZH_ZZS_CUR11 + LN_ZH_ZZS_HIS12 + LN_ZH_ZZS_CUR12 + LN_ZH_ZZS_HIS14 + LN_ZH_ZZS_CUR14,
           LN_SBHS_ZZS11, LN_ZH_ZZS_HIS11 + LN_ZH_ZZS_CUR11, LN_ZH_ZZS_HIS11, LN_ZH_ZZS_CUR11,
           LN_SBHS_ZZS12, LN_ZH_ZZS_HIS12 + LN_ZH_ZZS_CUR12, LN_ZH_ZZS_HIS12, LN_ZH_ZZS_CUR12,
           0, 0, 0, 0,
           LN_SBHS_ZZS14, LN_ZH_ZZS_HIS14 + LN_ZH_ZZS_CUR14, LN_ZH_ZZS_HIS14, LN_ZH_ZZS_CUR14

     UNION ALL
    SELECT LC_THISMONTH, '16', V_SWCODE,
           LN_SBHS - LN_SBHS_ZZS, LN_ZH_XFS_HIS11 + LN_ZH_XFS_CUR11 + LN_ZH_XFS_HIS12 + LN_ZH_XFS_CUR12 + LN_ZH_XFS_HIS14 + LN_ZH_XFS_CUR14,
           LN_SBHS11 - LN_SBHS_ZZS11, LN_ZH_XFS_HIS11 + LN_ZH_XFS_CUR11, LN_ZH_XFS_HIS11, LN_ZH_XFS_CUR11,
           LN_SBHS12 - LN_SBHS_ZZS12, LN_ZH_XFS_HIS12 + LN_ZH_XFS_CUR12, LN_ZH_XFS_HIS12, LN_ZH_XFS_CUR12,
           0, 0, 0, 0,
           LN_SBHS14 - LN_SBHS_ZZS14, LN_ZH_XFS_HIS14 + LN_ZH_XFS_CUR14, LN_ZH_XFS_HIS14, LN_ZH_XFS_CUR14
;
    COMMIT;
  END;

  -- 1-4、委托出口的生产企业
  BEGIN
  DECLARE BJTS_SQLCODE_008 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_008 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_008 = MYSQL_ERRNO, BJTS_SQLERRM_008 = MESSAGE_TEXT;
      SET V_ERROR = BJTS_SQLCODE_008;
      SET V_MSG = BJTS_SQLERRM_008;

  END;
SELECT COUNT(DISTINCT DJXH),
           COUNT(DISTINCT(CASE WHEN T.SHZT=11 THEN DJXH ELSE NULL END)),
           COUNT(DISTINCT(CASE WHEN T.SHZT=12 THEN DJXH ELSE NULL END)),
           COUNT(DISTINCT(CASE WHEN T.SHZT=14 THEN DJXH ELSE NULL END)),
           COUNT(DISTINCT(CASE WHEN T.TSE>0 THEN DJXH ELSE NULL END)),
           COUNT(DISTINCT(CASE WHEN T.TSE>0 AND T.SHZT=11 THEN DJXH ELSE NULL END)),
           COUNT(DISTINCT(CASE WHEN T.TSE>0 AND T.SHZT=12 THEN DJXH ELSE NULL END)),
           COUNT(DISTINCT(CASE WHEN T.TSE>0 AND T.SHZT=14 THEN DJXH ELSE NULL END)),
           ROUND(IFNULL(SUM(CASE WHEN T.SHZT=11 AND T.CKRQ_1< LD_THISYEAR THEN T.TSE ELSE 0 END), 0)/10000,6), -- 发函未回
           ROUND(IFNULL(SUM(CASE WHEN T.SHZT=11 AND T.CKRQ_1>=LD_THISYEAR THEN T.TSE ELSE 0 END), 0)/10000,6), -- 发函未回
           ROUND(IFNULL(SUM(CASE WHEN T.SHZT=12 AND T.CKRQ_1< LD_THISYEAR THEN T.TSE ELSE 0 END), 0)/10000,6), -- 回函有疑点
           ROUND(IFNULL(SUM(CASE WHEN T.SHZT=12 AND T.CKRQ_1>=LD_THISYEAR THEN T.TSE ELSE 0 END), 0)/10000,6), -- 回函有疑点
           ROUND(IFNULL(SUM(CASE WHEN T.SHZT=14 AND T.CKRQ_1< LD_THISYEAR THEN T.TSE ELSE 0 END), 0)/10000,6), -- 有疑点核查中
           ROUND(IFNULL(SUM(CASE WHEN T.SHZT=14 AND T.CKRQ_1>=LD_THISYEAR THEN T.TSE ELSE 0 END), 0)/10000,6), -- 有疑点核查中
           ROUND(IFNULL(SUM(CASE WHEN T.SHZT=11 AND T.CKRQ_1< LD_THISYEAR THEN T.MDE ELSE 0 END), 0)/10000,6), -- 发函未回
           ROUND(IFNULL(SUM(CASE WHEN T.SHZT=11 AND T.CKRQ_1>=LD_THISYEAR THEN T.MDE ELSE 0 END), 0)/10000,6), -- 发函未回
           ROUND(IFNULL(SUM(CASE WHEN T.SHZT=12 AND T.CKRQ_1< LD_THISYEAR THEN T.MDE ELSE 0 END), 0)/10000,6), -- 回函有疑点
           ROUND(IFNULL(SUM(CASE WHEN T.SHZT=12 AND T.CKRQ_1>=LD_THISYEAR THEN T.MDE ELSE 0 END), 0)/10000,6), -- 回函有疑点
           ROUND(IFNULL(SUM(CASE WHEN T.SHZT=14 AND T.CKRQ_1< LD_THISYEAR THEN T.MDE ELSE 0 END), 0)/10000,6), -- 有疑点核查中
           ROUND(IFNULL(SUM(CASE WHEN T.SHZT=14 AND T.CKRQ_1>=LD_THISYEAR THEN T.MDE ELSE 0 END), 0)/10000,6)  -- 有疑点核查中
      INTO LN_SBHS, LN_SBHS11, LN_SBHS12, LN_SBHS14, LN_SBHS_ZZS, LN_SBHS_ZZS11, LN_SBHS_ZZS12, LN_SBHS_ZZS14,
           LN_ZH_ZZS_HIS11, LN_ZH_ZZS_CUR11, LN_ZH_ZZS_HIS12, LN_ZH_ZZS_CUR12, LN_ZH_ZZS_HIS14, LN_ZH_ZZS_CUR14,
           LN_ZH_XFS_HIS11, LN_ZH_XFS_CUR11, LN_ZH_XFS_HIS12, LN_ZH_XFS_CUR12, LN_ZH_XFS_HIS14, LN_ZH_XFS_CUR14
      FROM (SELECT A.DJXH,B.LCSLID,B.SBXH,B.CKRQ_1,
                   CASE WHEN TRIM(A.LCSLID_FS) IS NOT NULL AND B.ZBBLBZ='Y' THEN 14
                        WHEN TRIM(A.LCSLID_FS) IS NOT NULL AND B.BYTSBZ='Y' THEN 20
                        WHEN TRIM(A.LCSLID_FS) IS NOT NULL THEN 30
                        WHEN TRIM(A.LCSLID_FS) IS NULL AND A.LCSLID_SB<>A.LCSLID THEN 14 -- 生产企业全部归类为：有疑点核查中
                        ELSE 40 END AS SHZT,
                   B.MYLAJ * CASE WHEN TRIM(A.LCSLID_FS) IS NULL THEN 1
                                  WHEN A.ZY_MDTSE=0 THEN 1
                                  WHEN A.SNBL_MDTSE=0 THEN 1
                                  WHEN A.SNBL_MDTSE>0 AND (B.ZBBLBZ='Y' OR B.BYTSBZ='Y') THEN 0
                                  ELSE LEAST(GREATEST(1 - A.SNBL_MDTSE / A.ZY_MDTSE,0),1)
                             END AS MYLAJ,
                   B.MDTSE * CASE WHEN TRIM(A.LCSLID_FS) IS NULL THEN (CASE WHEN A.SB_MDTSE=0 THEN 0 ELSE A.SB_ZZSTSE/A.SB_MDTSE END)
                                                           ELSE (CASE WHEN A.ZY_MDTSE=0 THEN 0 ELSE A.ZY_ZZSTSE/A.ZY_MDTSE END)
                             END -- 根据是否复审用申报数或复审数计算退税部分
                           * CASE WHEN TRIM(A.LCSLID_FS) IS NULL THEN 1
                                  WHEN A.ZY_ZZSTSE=0 THEN 1
                                  WHEN A.SNBL_ZZSTSE=0 THEN 1
                                  WHEN A.SNBL_ZZSTSE>0 AND (B.ZBBLBZ='Y' OR B.BYTSBZ='Y') THEN 0
                                  ELSE LEAST(GREATEST(1 - A.SNBL_ZZSTSE / A.ZY_ZZSTSE,0),1)
                             END AS TSE,
                   B.MDTSE * CASE WHEN TRIM(A.LCSLID_FS) IS NULL THEN (CASE WHEN A.SB_MDTSE=0 THEN 1 ELSE A.SB_MDSE/A.SB_MDTSE END)
                                                           ELSE (CASE WHEN A.ZY_MDTSE=0 THEN 1 ELSE A.ZY_MDSE/A.ZY_MDTSE END)
                             END
                           * CASE WHEN TRIM(A.LCSLID_FS) IS NULL THEN 1
                                  WHEN A.ZY_MDSE=0 THEN 1
                                  WHEN A.SNBL_MDSE=0 THEN 1
                                  WHEN A.SNBL_MDSE>0 AND (B.ZBBLBZ='Y' OR B.BYTSBZ='Y') THEN 0
                                  ELSE LEAST(GREATEST(1 - A.SNBL_MDSE / A.ZY_MDSE,0),1)
                             END AS MDE
              FROM CKTS_LC_SHXX A
             INNER JOIN CKTS_SB_MDT_CKMX B ON B.LCSLID=A.LCSLID AND B.BYBLBZ='N'
             WHERE A.TSSWJG_DM=V_SWCODE
               AND A.LCTJJC IN ('22','42','52','62')
