DELIMITER $$

DROP PROCEDURE IF EXISTS PRO_TJBB_DT_B02104_CSH_NEW$$

CREATE PROCEDURE PRO_TJBB_DT_B02104_CSH_NEW
/*************************************************
 * 市场采购贸易方式出口货物免税情况统计表
 ************************************************/
(
  IN V_SWCODE VARCHAR(4000),
  IN V_SSNY VARCHAR(4000),
  OUT V_ERROR DECIMAL(38,10),
  OUT V_MSG VARCHAR(4000)
)
routine_body: BEGIN
  DECLARE LC_THISMONTH       VARCHAR(6);
  DECLARE LD_SYSDATE       DATETIME;

  SET V_ERROR =0;
  SET V_MSG = ' ';

  IF V_SSNY IS NOT NULL THEN
    SET LD_SYSDATE =STR_TO_DATE(ORA_CONCAT(V_SSNY, '01'), '%Y%m%d');
  ELSE
    SET LD_SYSDATE =CURRENT_TIMESTAMP;
  END IF;

  SET LC_THISMONTH =DATE_FORMAT(LD_SYSDATE, '%Y%m');

  -- 0、清除原有制表数据，准备重新制表
  BEGIN
  DECLARE BJTS_SQLCODE_002 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_002 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_002 = MYSQL_ERRNO, BJTS_SQLERRM_002 = MESSAGE_TEXT;
      SET V_ERROR = BJTS_SQLCODE_002;
      SET V_MSG = BJTS_SQLERRM_002;

  END;
DELETE FROM TJBB_DT_B02104 WHERE SWJGDM=V_SWCODE AND SSNY=LC_THISMONTH;
    COMMIT;
  END;
  IF V_ERROR <> 0 THEN
    LEAVE routine_body;
  END IF;

  -- 1、插入两行空行
  BEGIN
  DECLARE BJTS_SQLCODE_001 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_001 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_001 = MYSQL_ERRNO, BJTS_SQLERRM_001 = MESSAGE_TEXT;
      SET V_ERROR = BJTS_SQLCODE_001;
      SET V_MSG = BJTS_SQLERRM_001;

  END;
INSERT INTO TJBB_DT_B02104 (SSNY,BBLC,SWJGDM,BAHS,BAHS_HZ,SBHS,SBHS_HZ,SBTSCKE,SBTSCKE_HZ,ZYSP)
    SELECT LC_THISMONTH, '01', V_SWCODE, 0, 0, 0, 0, 0, 0, ''

     UNION ALL
    SELECT LC_THISMONTH, '02', V_SWCODE, 0, 0, 0, 0, 0, 0, ''

     UNION ALL
    SELECT LC_THISMONTH, '03', V_SWCODE, 0, 0, 0, 0, 0, 0, ''

     UNION ALL
    SELECT LC_THISMONTH, '04', V_SWCODE, 0, 0, 0, 0, 0, 0, ''

      ;
    COMMIT;
  END;

  LEAVE routine_body;
END$$

DELIMITER ;

-- END SOURCE: PRO_TJBB_DT_B02104_CSH_NEW.sql

-- ======================================================================
-- [039/096] BEGIN SOURCE: PRO_TJBB_DT_B02105_CSH_NEW.sql
-- ======================================================================
DELIMITER $$

DROP PROCEDURE IF EXISTS PRO_TJBB_DT_B02105_CSH_NEW$$

CREATE PROCEDURE PRO_TJBB_DT_B02105_CSH_NEW
/*************************************************
 * 特殊政策退（免）税季度统计表
 ************************************************/
(
  IN V_SWCODE VARCHAR(4000),
  IN V_SSNY VARCHAR(4000),
  OUT V_ERROR DECIMAL(38,10),
  OUT V_MSG VARCHAR(4000)
)
routine_body: BEGIN
  DECLARE LD_SYSDATE       DATETIME;
  DECLARE LC_THISMONTH     VARCHAR(6);
  DECLARE LD_THISYEAR      DATETIME;
  DECLARE LD_NEXTMONTH     DATETIME;

  DECLARE LN_SBHS          BIGINT;
  DECLARE LN_SB_CKE_HIS    DECIMAL(18,6);
  DECLARE LN_SB_CKE_CUR    DECIMAL(18,6);

  DECLARE LN_SB_ZZS_HIS    DECIMAL(18,6);
  DECLARE LN_SB_ZZS_CUR    DECIMAL(18,6);
  DECLARE LN_SH_ZZS_HIS    DECIMAL(18,6);
  DECLARE LN_SH_ZZS_CUR    DECIMAL(18,6);
  DECLARE LN_BY_ZZS_HIS    DECIMAL(18,6);
  DECLARE LN_BY_ZZS_CUR    DECIMAL(18,6);
  DECLARE LN_ZT_ZZS_HIS    DECIMAL(18,6);
  DECLARE LN_ZT_ZZS_CUR    DECIMAL(18,6);

  DECLARE LN_SB_XFS_HIS    DECIMAL(18,6);
  DECLARE LN_SB_XFS_CUR    DECIMAL(18,6);
  DECLARE LN_SH_XFS_HIS    DECIMAL(18,6);
  DECLARE LN_SH_XFS_CUR    DECIMAL(18,6);
  DECLARE LN_BY_XFS_HIS    DECIMAL(18,6);
  DECLARE LN_BY_XFS_CUR    DECIMAL(18,6);
  DECLARE LN_ZT_XFS_HIS    DECIMAL(18,6);
  DECLARE LN_ZT_XFS_CUR    DECIMAL(18,6);
  DECLARE LC_SQL_INSERT    VARCHAR(4000);
  DECLARE LC_SQL_UPDATEHZ  VARCHAR(4000);

  SET V_ERROR =0;
  SET V_MSG = ' ';

  IF V_SSNY IS NOT NULL THEN
    SET LD_SYSDATE =STR_TO_DATE(ORA_CONCAT(V_SSNY, '01'), '%Y%m%d');
  ELSE
    SET LD_SYSDATE =CAST(DATE_FORMAT(CURRENT_TIMESTAMP, '%Y-%m-01') AS DATETIME);
  END IF;
  SET LC_THISMONTH =DATE_FORMAT(LD_SYSDATE, '%Y%m');
  SET LD_THISYEAR =MAKEDATE(YEAR(LD_SYSDATE), 1);
  SET LD_NEXTMONTH =CAST(DATE_FORMAT(DATE_ADD(LD_SYSDATE, INTERVAL 1 MONTH), '%Y-%m-01') AS DATETIME);

  -- 0、清除原有制表数据，准备重新制表
  BEGIN
  DECLARE BJTS_SQLCODE_005 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_005 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_005 = MYSQL_ERRNO, BJTS_SQLERRM_005 = MESSAGE_TEXT;
      SET V_ERROR = BJTS_SQLCODE_005;
      SET V_MSG = BJTS_SQLERRM_005;
      LEAVE routine_body;

  END;
DELETE FROM TJBB_DT_B02105 WHERE SWJGDM=V_SWCODE AND SSNY=LC_THISMONTH;
    COMMIT;
  END;

  BEGIN
  DECLARE BJTS_SQLCODE_004 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_004 TEXT DEFAULT '';
    -- 1.1 外轮供应、外航供应、远洋运输供应公司

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_004 = MYSQL_ERRNO, BJTS_SQLERRM_004 = MESSAGE_TEXT;
      SET V_ERROR = BJTS_SQLCODE_004;
      SET V_MSG = BJTS_SQLERRM_004;

  END;
BEGIN
      -- 申报户数、申报出口额
      SELECT COUNT(DISTINCT T.DJXH),
             ROUND(IFNULL(SUM(CASE WHEN T.CKRQ_1< LD_THISYEAR THEN T.MYLAJ ELSE 0 END), 0)/10000,6),
             ROUND(IFNULL(SUM(CASE WHEN T.CKRQ_1>=LD_THISYEAR THEN T.MYLAJ ELSE 0 END), 0)/10000,6),
             ROUND(IFNULL(SUM(CASE WHEN T.CKRQ_1< LD_THISYEAR THEN T.TSE ELSE 0 END), 0)/10000,6),
             ROUND(IFNULL(SUM(CASE WHEN T.CKRQ_1>=LD_THISYEAR THEN T.TSE ELSE 0 END), 0)/10000,6),
             ROUND(IFNULL(SUM(CASE WHEN T.CKRQ_1< LD_THISYEAR AND TRIM(T.LCSLID_FS) IS NULL THEN T.TSE ELSE 0 END), 0)/10000,6), -- 在途
             ROUND(IFNULL(SUM(CASE WHEN T.CKRQ_1>=LD_THISYEAR AND TRIM(T.LCSLID_FS) IS NULL THEN T.TSE ELSE 0 END), 0)/10000,6), -- 在途
             ROUND(IFNULL(SUM(CASE WHEN T.CKRQ_1< LD_THISYEAR AND TRIM(T.LCSLID_FS) IS NOT NULL AND T.MTSBZ='Y' THEN T.TSE ELSE 0 END), 0)/10000,6), -- 准予
             ROUND(IFNULL(SUM(CASE WHEN T.CKRQ_1>=LD_THISYEAR AND TRIM(T.LCSLID_FS) IS NOT NULL AND T.MTSBZ='Y' THEN T.TSE ELSE 0 END), 0)/10000,6), -- 准予
             ROUND(IFNULL(SUM(CASE WHEN T.CKRQ_1< LD_THISYEAR AND TRIM(T.LCSLID_FS) IS NOT NULL AND T.BYTSBZ='Y' THEN T.TSE ELSE 0 END), 0)/10000,6), -- 不予
             ROUND(IFNULL(SUM(CASE WHEN T.CKRQ_1>=LD_THISYEAR AND TRIM(T.LCSLID_FS) IS NOT NULL AND T.BYTSBZ='Y' THEN T.TSE ELSE 0 END), 0)/10000,6) -- 不予
        INTO LN_SBHS, LN_SB_CKE_HIS, LN_SB_CKE_CUR,
             LN_SB_ZZS_HIS, LN_SB_ZZS_CUR, LN_ZT_ZZS_HIS, LN_ZT_ZZS_CUR, LN_SH_ZZS_HIS, LN_SH_ZZS_CUR, LN_BY_ZZS_HIS, LN_BY_ZZS_CUR
        FROM (SELECT B.DJXH,B.LCSLID,B.SBXH,B.CKRQ_1,B.MTSBZ,B.BYTSBZ,C.LCSLID_FS,
                     B.MYLAJ * CASE WHEN TRIM(C.LCSLID_FS) IS NULL THEN 1
                                    WHEN A.SNBL_MDTSE=0 THEN 1
                                    WHEN A.SNBL_MDTSE>0 AND B.BYTSBZ='Y' THEN 0
                                    ELSE 1 - A.SNBL_MDTSE / A.ZY_MDTSE
                               END AS MYLAJ,
                     B.TSE   * CASE WHEN TRIM(C.LCSLID_FS) IS NULL THEN 1
                                    WHEN A.SNBL_MDTSE=0 THEN 1
                                    WHEN A.SNBL_MDTSE>0 AND B.BYTSBZ='Y' THEN 0
                                    ELSE 1 - A.SNBL_MDTSE / A.ZY_MDTSE
                               END AS TSE
                FROM CKTS_LC_SHXX A
               INNER JOIN CKTS_SB_MTS_CKMX B ON B.LCSLID=A.LCSLID AND B.CHBZ='N' AND B.CKTMSYWLXDMJH LIKE '%WL%'
                LEFT JOIN (SELECT DISTINCT LCSLID_FS FROM CKTS_LC_YWHZXX S) C ON C.LCSLID_FS=A.LCSLID_FS
               WHERE A.TSSWJG_DM=V_SWCODE
                 AND A.QDSJ<LD_NEXTMONTH
                 AND A.LCJSRQ>=LD_THISYEAR) T;

      INSERT INTO TJBB_DT_B02105 (SSNY, BBLC, SWJGDM, SBHS,
                SBLJ_TSCKE_HIS, SBLJ_TSCKE_YEAR, SBLJ_TMSE_HIS,  SBLJ_TMSE_YEAR,
                SHLJ_TMSE_HIS,  SHLJ_TMSE_YEAR, SHBY_TMSE_HIS,  SHBY_TMSE_YEAR, SHZT_TMSE_HIS,  SHZT_TMSE_YEAR,
                SPTK_TKE_HIS,   SPTK_TKE_YEAR, YSGK_TKE, GKBL_TKE_HIS,   GKBL_TKE_YEAR)
         SELECT LC_THISMONTH, '01', V_SWCODE, LN_SBHS,
                LN_SB_CKE_HIS, LN_SB_CKE_CUR, LN_SB_ZZS_HIS, LN_SB_ZZS_CUR,
                LN_SH_ZZS_HIS, LN_SH_ZZS_CUR, LN_BY_ZZS_HIS, LN_BY_ZZS_CUR, LN_ZT_ZZS_HIS, LN_ZT_ZZS_CUR,
                LN_SH_ZZS_HIS, LN_SH_ZZS_CUR, LN_SH_ZZS_HIS + LN_SH_ZZS_CUR, LN_SH_ZZS_HIS, LN_SH_ZZS_CUR
;
      COMMIT;
    END;

    -- 1.2 出境口岸免税店
    BEGIN
      -- 申报户数、申报出口额
      SELECT COUNT(DISTINCT T.DJXH),
             ROUND(IFNULL(SUM(CASE WHEN T.CKRQ_1< LD_THISYEAR THEN T.MYLAJ ELSE 0 END), 0)/10000,6),
             ROUND(IFNULL(SUM(CASE WHEN T.CKRQ_1>=LD_THISYEAR THEN T.MYLAJ ELSE 0 END), 0)/10000,6),
             ROUND(IFNULL(SUM(CASE WHEN T.CKRQ_1< LD_THISYEAR THEN T.TSE ELSE 0 END), 0)/10000,6),
             ROUND(IFNULL(SUM(CASE WHEN T.CKRQ_1>=LD_THISYEAR THEN T.TSE ELSE 0 END), 0)/10000,6),
             ROUND(IFNULL(SUM(CASE WHEN T.CKRQ_1< LD_THISYEAR AND TRIM(T.LCSLID_FS) IS NULL THEN T.TSE ELSE 0 END), 0)/10000,6), -- 在途
             ROUND(IFNULL(SUM(CASE WHEN T.CKRQ_1>=LD_THISYEAR AND TRIM(T.LCSLID_FS) IS NULL THEN T.TSE ELSE 0 END), 0)/10000,6), -- 在途
             ROUND(IFNULL(SUM(CASE WHEN T.CKRQ_1< LD_THISYEAR AND TRIM(T.LCSLID_FS) IS NOT NULL AND T.MTSBZ='Y' THEN T.TSE ELSE 0 END), 0)/10000,6), -- 准予
             ROUND(IFNULL(SUM(CASE WHEN T.CKRQ_1>=LD_THISYEAR AND TRIM(T.LCSLID_FS) IS NOT NULL AND T.MTSBZ='Y' THEN T.TSE ELSE 0 END), 0)/10000,6), -- 准予
             ROUND(IFNULL(SUM(CASE WHEN T.CKRQ_1< LD_THISYEAR AND TRIM(T.LCSLID_FS) IS NOT NULL AND T.BYTSBZ='Y' THEN T.TSE ELSE 0 END), 0)/10000,6), -- 不予
             ROUND(IFNULL(SUM(CASE WHEN T.CKRQ_1>=LD_THISYEAR AND TRIM(T.LCSLID_FS) IS NOT NULL AND T.BYTSBZ='Y' THEN T.TSE ELSE 0 END), 0)/10000,6) -- 不予
        INTO LN_SBHS, LN_SB_CKE_HIS, LN_SB_CKE_CUR,
             LN_SB_ZZS_HIS, LN_SB_ZZS_CUR, LN_ZT_ZZS_HIS, LN_ZT_ZZS_CUR, LN_SH_ZZS_HIS, LN_SH_ZZS_CUR, LN_BY_ZZS_HIS, LN_BY_ZZS_CUR
        FROM (SELECT B.DJXH,B.LCSLID,B.SBXH,B.CKRQ_1,B.MTSBZ,B.BYTSBZ,C.LCSLID_FS,
                     B.MYLAJ * CASE WHEN TRIM(C.LCSLID_FS) IS NULL THEN 1
                                    WHEN A.SNBL_MDTSE=0 THEN 1
                                    WHEN A.SNBL_MDTSE>0 AND B.BYTSBZ='Y' THEN 0
                                    ELSE 1 - A.SNBL_MDTSE / A.ZY_MDTSE
                               END AS MYLAJ,
                     B.TSE   * CASE WHEN TRIM(C.LCSLID_FS) IS NULL THEN 1
                                    WHEN A.SNBL_MDTSE=0 THEN 1
                                    WHEN A.SNBL_MDTSE>0 AND B.BYTSBZ='Y' THEN 0
                                    ELSE 1 - A.SNBL_MDTSE / A.ZY_MDTSE
                               END AS TSE
                FROM CKTS_LC_SHXX A
               INNER JOIN CKTS_SB_MTS_CKMX B ON B.LCSLID=A.LCSLID AND B.CHBZ='N' AND B.CKTMSYWLXDMJH LIKE '%MSD%'
                LEFT JOIN (SELECT DISTINCT LCSLID_FS FROM CKTS_LC_YWHZXX S) C ON C.LCSLID_FS=A.LCSLID_FS
               WHERE A.TSSWJG_DM=V_SWCODE
                 AND A.QDSJ<LD_NEXTMONTH
                 AND A.LCJSRQ>=LD_THISYEAR) T;

      INSERT INTO TJBB_DT_B02105 (SSNY, BBLC, SWJGDM, SBHS,
                SBLJ_TSCKE_HIS, SBLJ_TSCKE_YEAR, SBLJ_TMSE_HIS,  SBLJ_TMSE_YEAR,
                SHLJ_TMSE_HIS,  SHLJ_TMSE_YEAR, SHBY_TMSE_HIS,  SHBY_TMSE_YEAR, SHZT_TMSE_HIS,  SHZT_TMSE_YEAR,
                SPTK_TKE_HIS,   SPTK_TKE_YEAR, YSGK_TKE, GKBL_TKE_HIS,   GKBL_TKE_YEAR)
         SELECT LC_THISMONTH, '02', V_SWCODE, LN_SBHS,
                LN_SB_CKE_HIS, LN_SB_CKE_CUR, LN_SB_ZZS_HIS, LN_SB_ZZS_CUR,
                LN_SH_ZZS_HIS, LN_SH_ZZS_CUR, LN_BY_ZZS_HIS, LN_BY_ZZS_CUR, LN_ZT_ZZS_HIS, LN_ZT_ZZS_CUR,
                LN_SH_ZZS_HIS, LN_SH_ZZS_CUR, LN_SH_ZZS_HIS + LN_SH_ZZS_CUR, LN_SH_ZZS_HIS, LN_SH_ZZS_CUR
;
      COMMIT;
    END;

    -- 1.4 中标机电产品
     BEGIN
      -- 申报户数、申报出口额
      SELECT COUNT(DISTINCT T.DJXH),
             ROUND(IFNULL(SUM(CASE WHEN T.CKRQ_1< LD_THISYEAR THEN T.MYLAJ ELSE 0 END), 0)/10000,6),
             ROUND(IFNULL(SUM(CASE WHEN T.CKRQ_1>=LD_THISYEAR THEN T.MYLAJ ELSE 0 END), 0)/10000,6),
             ROUND(IFNULL(SUM(CASE WHEN T.CKRQ_1< LD_THISYEAR THEN T.TSE ELSE 0 END), 0)/10000,6),
             ROUND(IFNULL(SUM(CASE WHEN T.CKRQ_1>=LD_THISYEAR THEN T.TSE ELSE 0 END), 0)/10000,6),
             ROUND(IFNULL(SUM(CASE WHEN T.CKRQ_1< LD_THISYEAR AND TRIM(T.LCSLID_FS) IS NULL THEN T.TSE ELSE 0 END), 0)/10000,6), -- 在途
             ROUND(IFNULL(SUM(CASE WHEN T.CKRQ_1>=LD_THISYEAR AND TRIM(T.LCSLID_FS) IS NULL THEN T.TSE ELSE 0 END), 0)/10000,6), -- 在途
             ROUND(IFNULL(SUM(CASE WHEN T.CKRQ_1< LD_THISYEAR AND TRIM(T.LCSLID_FS) IS NOT NULL AND T.MDTSNY IS NOT NULL THEN T.TSE ELSE 0 END), 0)/10000,6), -- 准予
             ROUND(IFNULL(SUM(CASE WHEN T.CKRQ_1>=LD_THISYEAR AND TRIM(T.LCSLID_FS) IS NOT NULL AND T.MDTSNY IS NOT NULL THEN T.TSE ELSE 0 END), 0)/10000,6), -- 准予
             ROUND(IFNULL(SUM(CASE WHEN T.CKRQ_1< LD_THISYEAR AND TRIM(T.LCSLID_FS) IS NOT NULL AND T.BYTSBZ='Y' THEN T.TSE ELSE 0 END), 0)/10000,6), -- 不予
             ROUND(IFNULL(SUM(CASE WHEN T.CKRQ_1>=LD_THISYEAR AND TRIM(T.LCSLID_FS) IS NOT NULL AND T.BYTSBZ='Y' THEN T.TSE ELSE 0 END), 0)/10000,6), -- 不予
             ROUND(IFNULL(SUM(CASE WHEN T.CKRQ_1< LD_THISYEAR THEN T.MDE ELSE 0 END), 0)/10000,6), -- 申报免抵退税额
             ROUND(IFNULL(SUM(CASE WHEN T.CKRQ_1>=LD_THISYEAR THEN T.MDE ELSE 0 END), 0)/10000,6), -- 申报
             ROUND(IFNULL(SUM(CASE WHEN T.CKRQ_1< LD_THISYEAR AND TRIM(T.LCSLID_FS) IS NULL THEN T.MDE ELSE 0 END), 0)/10000,6), -- 在途
             ROUND(IFNULL(SUM(CASE WHEN T.CKRQ_1>=LD_THISYEAR AND TRIM(T.LCSLID_FS) IS NULL THEN T.MDE ELSE 0 END), 0)/10000,6), -- 在途
             ROUND(IFNULL(SUM(CASE WHEN T.CKRQ_1< LD_THISYEAR AND TRIM(T.LCSLID_FS) IS NOT NULL AND T.MDTSNY IS NOT NULL THEN T.MDE ELSE 0 END), 0)/10000,6), -- 准予
             ROUND(IFNULL(SUM(CASE WHEN T.CKRQ_1>=LD_THISYEAR AND TRIM(T.LCSLID_FS) IS NOT NULL AND T.MDTSNY IS NOT NULL THEN T.MDE ELSE 0 END), 0)/10000,6), -- 准予
             ROUND(IFNULL(SUM(CASE WHEN T.CKRQ_1< LD_THISYEAR AND TRIM(T.LCSLID_FS) IS NOT NULL AND T.BYTSBZ='Y' THEN T.MDE ELSE 0 END), 0)/10000,6), -- 不予
             ROUND(IFNULL(SUM(CASE WHEN T.CKRQ_1>=LD_THISYEAR AND TRIM(T.LCSLID_FS) IS NOT NULL AND T.BYTSBZ='Y' THEN T.MDE ELSE 0 END), 0)/10000,6) -- 不予
        INTO LN_SBHS, LN_SB_CKE_HIS, LN_SB_CKE_CUR,
             LN_SB_ZZS_HIS, LN_SB_ZZS_CUR, LN_ZT_ZZS_HIS, LN_ZT_ZZS_CUR, LN_SH_ZZS_HIS, LN_SH_ZZS_CUR, LN_BY_ZZS_HIS, LN_BY_ZZS_CUR,
             LN_SB_XFS_HIS, LN_SB_XFS_CUR, LN_ZT_XFS_HIS, LN_ZT_XFS_CUR, LN_SH_XFS_HIS, LN_SH_XFS_CUR, LN_BY_XFS_HIS, LN_BY_XFS_CUR
        FROM (SELECT B.DJXH,B.LCSLID,B.SBXH,B.CKRQ_1,B.MDTSNY,B.BYTSBZ,C.LCSLID_FS,
                     B.MYLAJ * CASE WHEN TRIM(C.LCSLID_FS) IS NULL THEN 1
                                    WHEN A.SNBL_MDTSE=0 THEN 1
                                    WHEN A.SNBL_MDTSE>0 AND B.BYTSBZ='Y' THEN 0
                                    ELSE 1 - A.SNBL_MDTSE / A.ZY_MDTSE
                               END AS MYLAJ,
                     B.MDTSE * CASE WHEN TRIM(C.LCSLID_FS) IS NULL THEN (CASE WHEN A.SB_MDTSE=0 THEN 1 ELSE A.SB_ZZSTSE/A.SB_MDTSE END)
                                                             ELSE (CASE WHEN A.ZY_MDTSE=0 THEN 1 ELSE A.ZY_ZZSTSE/A.ZY_MDTSE END)
                               END -- 根据是否复审用申报数或复审数计算退税部分
                             * CASE WHEN TRIM(C.LCSLID_FS) IS NULL THEN 1
                                    WHEN A.SNBL_ZZSTSE=0 THEN 1
                                    WHEN A.SNBL_ZZSTSE>0 AND B.BYTSBZ='Y' THEN 0
                                    ELSE 1 - A.SNBL_ZZSTSE / A.ZY_ZZSTSE
                               END AS TSE,
                     B.MDTSE * CASE WHEN TRIM(C.LCSLID_FS) IS NULL THEN (CASE WHEN A.SB_MDTSE=0 THEN 0 ELSE A.SB_MDSE/A.SB_MDTSE END)
                                                             ELSE (CASE WHEN A.ZY_MDTSE=0 THEN 0 ELSE A.ZY_MDSE/A.ZY_MDTSE END)
                               END
                             * CASE WHEN TRIM(C.LCSLID_FS) IS NULL THEN 1
                                    WHEN A.SNBL_MDSE=0 THEN 1
                                    WHEN A.SNBL_MDSE>0 AND B.BYTSBZ='Y' THEN 0
                                    ELSE 1 - A.SNBL_MDSE / A.ZY_MDSE
                               END AS MDE
                FROM CKTS_LC_SHXX A
               INNER JOIN CKTS_SB_MDT_CKMX B ON B.LCSLID=A.LCSLID AND B.CHBZ='N' AND B.CKTMSYWLXDMJH LIKE '%ZB%'
                LEFT JOIN (SELECT DISTINCT LCSLID_FS FROM CKTS_LC_YWHZXX S) C ON C.LCSLID_FS=A.LCSLID_FS
               WHERE A.TSSWJG_DM=V_SWCODE
                 AND A.QDSJ<LD_NEXTMONTH
                 AND A.LCJSRQ>=LD_THISYEAR) T;

      INSERT INTO TJBB_DT_B02105 (SSNY, BBLC, SWJGDM, SBHS,
                SBLJ_TSCKE_HIS, SBLJ_TSCKE_YEAR, SBLJ_TMSE_HIS,  SBLJ_TMSE_YEAR,
                SHLJ_TMSE_HIS,  SHLJ_TMSE_YEAR, SHBY_TMSE_HIS,  SHBY_TMSE_YEAR, SHZT_TMSE_HIS,  SHZT_TMSE_YEAR,
                SPTK_TKE_HIS,   SPTK_TKE_YEAR, YSGK_TKE, GKBL_TKE_HIS,   GKBL_TKE_YEAR)
         SELECT LC_THISMONTH, '04', V_SWCODE, LN_SBHS,
                LN_SB_CKE_HIS, LN_SB_CKE_CUR, LN_SB_ZZS_HIS, LN_SB_ZZS_CUR,
                LN_SH_ZZS_HIS, LN_SH_ZZS_CUR, LN_BY_ZZS_HIS, LN_BY_ZZS_CUR, LN_ZT_ZZS_HIS, LN_ZT_ZZS_CUR,
                LN_SH_ZZS_HIS, LN_SH_ZZS_CUR, LN_SH_ZZS_HIS + LN_SH_ZZS_CUR, LN_SH_ZZS_HIS, LN_SH_ZZS_CUR

          UNION ALL
         SELECT LC_THISMONTH, '05', V_SWCODE, 0,
                0, 0, LN_SB_XFS_HIS, LN_SB_XFS_CUR,
                LN_SH_XFS_HIS, LN_SH_XFS_CUR, LN_BY_XFS_HIS, LN_BY_XFS_CUR, LN_ZT_XFS_HIS, LN_ZT_XFS_CUR,
                LN_SH_XFS_HIS, LN_SH_XFS_CUR, LN_SH_XFS_HIS + LN_SH_XFS_CUR, LN_SH_XFS_HIS, LN_SH_XFS_CUR
;
      COMMIT;
    END;

    -- 1.6 外商投资企业采购国产设备
     BEGIN
      -- 申报户数、申报出口额
      SELECT COUNT(DISTINCT T.DJXH), 0, 0,
             ROUND(IFNULL(SUM(CASE WHEN T.CKRQ_1< LD_THISYEAR THEN T.TSE ELSE 0 END), 0)/10000,6),
             ROUND(IFNULL(SUM(CASE WHEN T.CKRQ_1>=LD_THISYEAR THEN T.TSE ELSE 0 END), 0)/10000,6),
             ROUND(IFNULL(SUM(CASE WHEN T.CKRQ_1< LD_THISYEAR AND TRIM(T.LCSLID_FS) IS NULL THEN T.TSE ELSE 0 END), 0)/10000,6), -- 在途
             ROUND(IFNULL(SUM(CASE WHEN T.CKRQ_1>=LD_THISYEAR AND TRIM(T.LCSLID_FS) IS NULL THEN T.TSE ELSE 0 END), 0)/10000,6), -- 在途
             ROUND(IFNULL(SUM(CASE WHEN T.CKRQ_1< LD_THISYEAR AND TRIM(T.LCSLID_FS) IS NOT NULL AND T.BYTSBZ='N' THEN T.TSE ELSE 0 END), 0)/10000,6), -- 准予
             ROUND(IFNULL(SUM(CASE WHEN T.CKRQ_1>=LD_THISYEAR AND TRIM(T.LCSLID_FS) IS NOT NULL AND T.BYTSBZ='N' THEN T.TSE ELSE 0 END), 0)/10000,6), -- 准予
             ROUND(IFNULL(SUM(CASE WHEN T.CKRQ_1< LD_THISYEAR AND TRIM(T.LCSLID_FS) IS NOT NULL AND T.BYTSBZ='Y' THEN T.TSE ELSE 0 END), 0)/10000,6), -- 不予
             ROUND(IFNULL(SUM(CASE WHEN T.CKRQ_1>=LD_THISYEAR AND TRIM(T.LCSLID_FS) IS NOT NULL AND T.BYTSBZ='Y' THEN T.TSE ELSE 0 END), 0)/10000,6) -- 不予
        INTO LN_SBHS, LN_SB_CKE_HIS, LN_SB_CKE_CUR,
             LN_SB_ZZS_HIS, LN_SB_ZZS_CUR, LN_ZT_ZZS_HIS, LN_ZT_ZZS_CUR, LN_SH_ZZS_HIS, LN_SH_ZZS_CUR, LN_BY_ZZS_HIS, LN_BY_ZZS_CUR
        FROM (SELECT B.DJXH,B.LCSLID,B.SBXH,B.KPRQ AS CKRQ_1,B.BYTSBZ,C.LCSLID_FS,
                     B.TSE   * CASE WHEN TRIM(C.LCSLID_FS) IS NULL THEN 1
                                    WHEN A.SNBL_MDTSE=0 THEN 1
                                    WHEN A.SNBL_MDTSE>0 AND B.BYTSBZ='Y' THEN 0
                                    ELSE 1 - A.SNBL_MDTSE / A.ZY_MDTSE
                               END AS TSE
                FROM CKTS_LC_SHXX A
               INNER JOIN CKTS_SB_GJ_SBMX B ON B.LCSLID=A.LCSLID AND B.CHBZ='N' AND B.CKTMSYWLXDMJH IN ('WZYFJG','GCSB')
                LEFT JOIN (SELECT DISTINCT LCSLID_FS FROM CKTS_LC_YWHZXX S) C ON C.LCSLID_FS=A.LCSLID_FS
               INNER JOIN GLXT_BB_SHXT_DJXX D ON D.DJXH_JS=A.DJXH AND D.QYLX='2'
               WHERE A.TSSWJG_DM=V_SWCODE
                 AND A.QDSJ<LD_NEXTMONTH
                 AND A.LCJSRQ>=LD_THISYEAR) T;

      INSERT INTO TJBB_DT_B02105 (SSNY, BBLC, SWJGDM, SBHS,
