             LN_SP_TSE_MON, LN_SP_TSE_YEAR, LN_SP_TSE35_MON, LN_SP_TSE35_YEAR,
             LN_YS_TKE_YEAR - FN_YEAR, LN_YS_TKE35_YEAR,
