      SET V_MSG = BJTS_SQLERRM_002;
      LEAVE routine_body;

  END;
INSERT INTO TJBB_DT_B03101 (SSNY,BBLC,SWJGDM,
           JAN,FEB,MAR,APR,MAY,JUN,JUL,AUG,SEP,OCT,NOV,DEC,
           JAN_HZ,FEB_HZ,MAR_HZ,APR_HZ,MAY_HZ,JUN_HZ,JUL_HZ,AUG_HZ,SEP_HZ,OCT_HZ,NOV_HZ,DEC_HZ)
    WITH TSFN AS (SELECT DATE_FORMAT(T.RKRQ, '%Y%m') AS FNMONTH, IFNULL(ROUND(SUM(T.SJJE)/10000,0), 0) AS FNSE
                    FROM FG_CKTSFN_HXZG T
                   WHERE T.SKSSSWJG_DM=V_SWCODE
                     AND T.RKRQ>=LD_THISYEAR AND T.RKRQ<LD_NEXTMONTH
                     AND T.YWHZBUUID IS NULL
                   GROUP BY DATE_FORMAT(T.RKRQ, '%Y%m')),
         TSTK AS (SELECT DATE_FORMAT(S.XHRQ_TK, '%Y%m') AS TKMONTH, IFNULL(ROUND(SUM(S.GKBL_ZZSTSE+S.GKBL_XFSTSE)/10000,0), 0) AS TKSE
