           SUM(CASE WHEN TSTK.TKMONTH=ORA_CONCAT(LC_THISYEAR, '05') THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH=ORA_CONCAT(LC_THISYEAR, '06') THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
