           SUM(CASE WHEN TSTK.TKMONTH=ORA_CONCAT(LC_THISYEAR, '09') THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH=ORA_CONCAT(LC_THISYEAR, '10') THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH=ORA_CONCAT(LC_THISYEAR, '11') THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH=ORA_CONCAT(LC_THISYEAR, '12') THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END)
      FROM TSTK
      LEFT JOIN TSFN ON TSFN.FNMONTH = TSTK.TKMONTH;
