     SELECT SWJG_DM AS SWJG_DM
       FROM DM_SWJG
      WHERE (SUBSTR(V_SWCODE, 1, 1) <> '2' OR SUBSTR(V_SWCODE, 1, 1) IS NULL)
        AND SWJG_DM_SJ = V_SWCODE
        AND TSJG_BZ = '1'))))
                     AND T.RKRQ>=LD_THISYEAR AND T.RKRQ<LD_NEXTMONTH
                     AND T.YWHZBUUID IS NULL
                   GROUP BY DATE_FORMAT(T.RKRQ, '%Y%m')),
         TSTK AS (SELECT DATE_FORMAT(S.XHRQ_TK, '%Y%m') AS TKMONTH, IFNULL(ROUND(SUM(S.GKBL_ZZSTSE+S.GKBL_XFSTSE)/10000,0), 0) AS TKSE
                    FROM CKTS_LC_SEHZXX S
                   WHERE ((V_SWCODE='13300000000'  AND (S.CKTMSJHSSSWJGDM IN (SELECT SWJG_DM FROM DM_SWJG WHERE TSJG_BZ='1'))) OR
                          (V_SWCODE<>'13300000000' AND (S.CKTMSJHSSSWJGDM IN (SELECT VIR_SWJGDM AS SWJG_DM
       FROM DM_SWJG_VIRTUAL
      WHERE SUBSTR(V_SWCODE, 1, 1) = '2'
        AND SWJG_DM = V_SWCODE
        AND YXBZ = 'Y'
        AND VIR_FLAG = '0'
      UNION ALL
     SELECT SWJG_DM AS SWJG_DM
       FROM DM_SWJG
      WHERE (SUBSTR(V_SWCODE, 1, 1) <> '2' OR SUBSTR(V_SWCODE, 1, 1) IS NULL)
        AND SWJG_DM_SJ = V_SWCODE
        AND TSJG_BZ = '1'))))
                     AND S.XHRQ_TK>=LD_THISYEAR AND S.XHRQ_TK<LD_NEXTMONTH
                   GROUP BY DATE_FORMAT(S.XHRQ_TK, '%Y%m'))
    SELECT LC_THISMONTH, '01', V_SWCODE,
           SUM(CASE WHEN TSTK.TKMONTH=ORA_CONCAT(LC_THISYEAR, '01') THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH=ORA_CONCAT(LC_THISYEAR, '02') THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH=ORA_CONCAT(LC_THISYEAR, '03') THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH=ORA_CONCAT(LC_THISYEAR, '04') THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH=ORA_CONCAT(LC_THISYEAR, '05') THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH=ORA_CONCAT(LC_THISYEAR, '06') THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH=ORA_CONCAT(LC_THISYEAR, '07') THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH=ORA_CONCAT(LC_THISYEAR, '08') THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH=ORA_CONCAT(LC_THISYEAR, '09') THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH=ORA_CONCAT(LC_THISYEAR, '10') THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH=ORA_CONCAT(LC_THISYEAR, '11') THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH=ORA_CONCAT(LC_THISYEAR, '12') THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH=ORA_CONCAT(LC_THISYEAR, '01') THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH=ORA_CONCAT(LC_THISYEAR, '02') THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH=ORA_CONCAT(LC_THISYEAR, '03') THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH=ORA_CONCAT(LC_THISYEAR, '04') THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH=ORA_CONCAT(LC_THISYEAR, '05') THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH=ORA_CONCAT(LC_THISYEAR, '06') THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH=ORA_CONCAT(LC_THISYEAR, '07') THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH=ORA_CONCAT(LC_THISYEAR, '08') THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH=ORA_CONCAT(LC_THISYEAR, '09') THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH=ORA_CONCAT(LC_THISYEAR, '10') THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH=ORA_CONCAT(LC_THISYEAR, '11') THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH=ORA_CONCAT(LC_THISYEAR, '12') THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END)
      FROM TSTK
      LEFT JOIN TSFN ON TSFN.FNMONTH = TSTK.TKMONTH;
    COMMIT;

    -- 1.2 上年数
    INSERT INTO TJBB_DT_B03101 (SSNY,BBLC,SWJGDM,
           JAN,FEB,MAR,APR,MAY,JUN,JUL,AUG,SEP,OCT,NOV,DEC,
           JAN_HZ,FEB_HZ,MAR_HZ,APR_HZ,MAY_HZ,JUN_HZ,JUL_HZ,AUG_HZ,SEP_HZ,OCT_HZ,NOV_HZ,DEC_HZ)
    WITH TSFN AS (SELECT DATE_FORMAT(T.RKRQ, '%Y%m') AS FNMONTH, IFNULL(ROUND(SUM(T.SJJE)/10000,0), 0) AS FNSE
                    FROM FG_CKTSFN_HXZG T
                   WHERE ((V_SWCODE='13300000000'  AND (T.SKSSSWJG_DM IN (SELECT SWJG_DM FROM DM_SWJG WHERE TSJG_BZ='1'))) OR
                          (V_SWCODE<>'13300000000' AND (T.SKSSSWJG_DM IN (SELECT VIR_SWJGDM AS SWJG_DM
       FROM DM_SWJG_VIRTUAL
      WHERE SUBSTR(V_SWCODE, 1, 1) = '2'
        AND SWJG_DM = V_SWCODE
        AND YXBZ = 'Y'
        AND VIR_FLAG = '0'
      UNION ALL
     SELECT SWJG_DM AS SWJG_DM
       FROM DM_SWJG
      WHERE (SUBSTR(V_SWCODE, 1, 1) <> '2' OR SUBSTR(V_SWCODE, 1, 1) IS NULL)
        AND SWJG_DM_SJ = V_SWCODE
        AND TSJG_BZ = '1'))))
                     AND T.RKRQ>=LD_LASTYEAR AND T.RKRQ<LD_THISYEAR
                     AND T.YWHZBUUID IS NULL
                   GROUP BY DATE_FORMAT(T.RKRQ, '%Y%m')),
         TSTK AS (SELECT DATE_FORMAT(S.XHRQ_TK, '%Y%m') AS TKMONTH, IFNULL(ROUND(SUM(S.GKBL_ZZSTSE+S.GKBL_XFSTSE)/10000,0), 0) AS TKSE
                    FROM CKTS_LC_SEHZXX S
                   WHERE ((V_SWCODE='13300000000'  AND (S.CKTMSJHSSSWJGDM IN (SELECT SWJG_DM FROM DM_SWJG WHERE TSJG_BZ='1'))) OR
                          (V_SWCODE<>'13300000000' AND (S.CKTMSJHSSSWJGDM IN (SELECT VIR_SWJGDM AS SWJG_DM
       FROM DM_SWJG_VIRTUAL
      WHERE SUBSTR(V_SWCODE, 1, 1) = '2'
        AND SWJG_DM = V_SWCODE
        AND YXBZ = 'Y'
        AND VIR_FLAG = '0'
      UNION ALL
     SELECT SWJG_DM AS SWJG_DM
       FROM DM_SWJG
      WHERE (SUBSTR(V_SWCODE, 1, 1) <> '2' OR SUBSTR(V_SWCODE, 1, 1) IS NULL)
        AND SWJG_DM_SJ = V_SWCODE
        AND TSJG_BZ = '1'))))
                     AND S.XHRQ_TK>=LD_LASTYEAR AND S.XHRQ_TK<LD_THISYEAR
                   GROUP BY DATE_FORMAT(S.XHRQ_TK, '%Y%m'))
    SELECT LC_THISMONTH, '02', V_SWCODE,
           SUM(CASE WHEN TSTK.TKMONTH=ORA_CONCAT(LC_LASTYEAR, '01') THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH=ORA_CONCAT(LC_LASTYEAR, '02') THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH=ORA_CONCAT(LC_LASTYEAR, '03') THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH=ORA_CONCAT(LC_LASTYEAR, '04') THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH=ORA_CONCAT(LC_LASTYEAR, '05') THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH=ORA_CONCAT(LC_LASTYEAR, '06') THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH=ORA_CONCAT(LC_LASTYEAR, '07') THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH=ORA_CONCAT(LC_LASTYEAR, '08') THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH=ORA_CONCAT(LC_LASTYEAR, '09') THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH=ORA_CONCAT(LC_LASTYEAR, '10') THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH=ORA_CONCAT(LC_LASTYEAR, '11') THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH=ORA_CONCAT(LC_LASTYEAR, '12') THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH=ORA_CONCAT(LC_LASTYEAR, '01') THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH=ORA_CONCAT(LC_LASTYEAR, '02') THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH=ORA_CONCAT(LC_LASTYEAR, '03') THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH=ORA_CONCAT(LC_LASTYEAR, '04') THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH=ORA_CONCAT(LC_LASTYEAR, '05') THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH=ORA_CONCAT(LC_LASTYEAR, '06') THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH=ORA_CONCAT(LC_LASTYEAR, '07') THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH=ORA_CONCAT(LC_LASTYEAR, '08') THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH=ORA_CONCAT(LC_LASTYEAR, '09') THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH=ORA_CONCAT(LC_LASTYEAR, '10') THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH=ORA_CONCAT(LC_LASTYEAR, '11') THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH=ORA_CONCAT(LC_LASTYEAR, '12') THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END)
      FROM TSTK
      LEFT JOIN TSFN ON TSFN.FNMONTH = TSTK.TKMONTH;
    COMMIT;
  END;

  -- 2、同比
  BEGIN
  DECLARE BJTS_SQLCODE_001 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_001 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_001 = MYSQL_ERRNO, BJTS_SQLERRM_001 = MESSAGE_TEXT;
      SET V_ERROR = BJTS_SQLCODE_001;
      SET V_MSG = BJTS_SQLERRM_001;

  END;
INSERT INTO TJBB_DT_B03101 (SSNY,BBLC,SWJGDM,
           JAN,FEB,MAR,APR,MAY,JUN,JUL,AUG,SEP,OCT,NOV,DEC,
           JAN_HZ,FEB_HZ,MAR_HZ,APR_HZ,MAY_HZ,JUN_HZ,JUL_HZ,AUG_HZ,SEP_HZ,OCT_HZ,NOV_HZ,DEC_HZ)
    SELECT LC_THISMONTH, '03', V_SWCODE,
           CASE WHEN IFNULL(B.JAN, 0)=0 THEN NULL ELSE ROUND(100 * A.JAN/B.JAN -100,1) END,
           CASE WHEN IFNULL(B.FEB, 0)=0 THEN NULL ELSE ROUND(100 * A.FEB/B.FEB -100,1) END,
           CASE WHEN IFNULL(B.MAR, 0)=0 THEN NULL ELSE ROUND(100 * A.MAR/B.MAR -100,1) END,
           CASE WHEN IFNULL(B.APR, 0)=0 THEN NULL ELSE ROUND(100 * A.APR/B.APR -100,1) END,
           CASE WHEN IFNULL(B.MAY, 0)=0 THEN NULL ELSE ROUND(100 * A.MAY/B.MAY -100,1) END,
           CASE WHEN IFNULL(B.JUN, 0)=0 THEN NULL ELSE ROUND(100 * A.JUN/B.JUN -100,1) END,
           CASE WHEN IFNULL(B.JUL, 0)=0 THEN NULL ELSE ROUND(100 * A.JUL/B.JUL -100,1) END,
           CASE WHEN IFNULL(B.AUG, 0)=0 THEN NULL ELSE ROUND(100 * A.AUG/B.AUG -100,1) END,
           CASE WHEN IFNULL(B.SEP, 0)=0 THEN NULL ELSE ROUND(100 * A.SEP/B.SEP -100,1) END,
           CASE WHEN IFNULL(B.OCT, 0)=0 THEN NULL ELSE ROUND(100 * A.OCT/B.OCT -100,1) END,
           CASE WHEN IFNULL(B.NOV, 0)=0 THEN NULL ELSE ROUND(100 * A.NOV/B.NOV -100,1) END,
           CASE WHEN IFNULL(B.DEC, 0)=0 THEN NULL ELSE ROUND(100 * A.DEC/B.DEC -100,1) END,
           CASE WHEN IFNULL(B.JAN_HZ, 0)=0 THEN NULL ELSE ROUND(100 * A.JAN_HZ/B.JAN_HZ -100,1) END,
           CASE WHEN IFNULL(B.FEB_HZ, 0)=0 THEN NULL ELSE ROUND(100 * A.FEB_HZ/B.FEB_HZ -100,1) END,
           CASE WHEN IFNULL(B.MAR_HZ, 0)=0 THEN NULL ELSE ROUND(100 * A.MAR_HZ/B.MAR_HZ -100,1) END,
           CASE WHEN IFNULL(B.APR_HZ, 0)=0 THEN NULL ELSE ROUND(100 * A.APR_HZ/B.APR_HZ -100,1) END,
           CASE WHEN IFNULL(B.MAY_HZ, 0)=0 THEN NULL ELSE ROUND(100 * A.MAY_HZ/B.MAY_HZ -100,1) END,
           CASE WHEN IFNULL(B.JUN_HZ, 0)=0 THEN NULL ELSE ROUND(100 * A.JUN_HZ/B.JUN_HZ -100,1) END,
           CASE WHEN IFNULL(B.JUL_HZ, 0)=0 THEN NULL ELSE ROUND(100 * A.JUL_HZ/B.JUL_HZ -100,1) END,
           CASE WHEN IFNULL(B.AUG_HZ, 0)=0 THEN NULL ELSE ROUND(100 * A.AUG_HZ/B.AUG_HZ -100,1) END,
           CASE WHEN IFNULL(B.SEP_HZ, 0)=0 THEN NULL ELSE ROUND(100 * A.SEP_HZ/B.SEP_HZ -100,1) END,
           CASE WHEN IFNULL(B.OCT_HZ, 0)=0 THEN NULL ELSE ROUND(100 * A.OCT_HZ/B.OCT_HZ -100,1) END,
           CASE WHEN IFNULL(B.NOV_HZ, 0)=0 THEN NULL ELSE ROUND(100 * A.NOV_HZ/B.NOV_HZ -100,1) END,
           CASE WHEN IFNULL(B.DEC_HZ, 0)=0 THEN NULL ELSE ROUND(100 * A.DEC_HZ/B.DEC_HZ -100,1) END
      FROM TJBB_DT_B03101 A,
           TJBB_DT_B03101 B
