-- ======================================================================
-- [054/096] BEGIN SOURCE: PRO_TJBB_DT_B03102_CSH_NEW.sql
-- ======================================================================
DELIMITER $$

DROP PROCEDURE IF EXISTS PRO_TJBB_DT_B03102_CSH_NEW$$

CREATE PROCEDURE PRO_TJBB_DT_B03102_CSH_NEW
/*************************************************
 * 浙江省办理出口退税累计趋势图（全部重新统计）
 ************************************************/
(
  IN V_SWCODE VARCHAR(4000),
  IN V_SSNY VARCHAR(4000),
  OUT V_ERROR DECIMAL(38,10),
  OUT V_MSG VARCHAR(4000)
)
routine_body: BEGIN
  DECLARE LD_SYSDATE       DATETIME;
  DECLARE LC_THISMONTH     VARCHAR(6);
  DECLARE LD_THISYEAR      DATETIME;
  DECLARE LD_NEXTMONTH     DATETIME;
  DECLARE LD_LASTYEAR      DATETIME;

  DECLARE LC_THISYEAR      VARCHAR(4);-- 当年
  DECLARE LC_LASTYEAR      VARCHAR(4);-- 上年

  SET V_ERROR =0;
  SET V_MSG = ' ';

  IF V_SSNY IS NOT NULL THEN
    SET LD_SYSDATE =STR_TO_DATE(ORA_CONCAT(V_SSNY, '01'), '%Y%m%d');
  ELSE
    SET LD_SYSDATE =CAST(DATE_FORMAT(CURRENT_TIMESTAMP, '%Y-%m-01') AS DATETIME);
  END IF;
  SET LC_THISMONTH =DATE_FORMAT(LD_SYSDATE, '%Y%m');
  SET LD_THISYEAR =MAKEDATE(YEAR(LD_SYSDATE), 1);
  SET LD_NEXTMONTH =CAST(DATE_FORMAT(DATE_ADD(LD_SYSDATE, INTERVAL 1 MONTH), '%Y-%m-01') AS DATETIME);
  SET LD_LASTYEAR =MAKEDATE(YEAR(DATE_ADD(LD_SYSDATE, INTERVAL -12 MONTH)), 1);

  SET LC_THISYEAR =DATE_FORMAT(LD_SYSDATE, '%Y');
  SET LC_LASTYEAR =DATE_FORMAT(DATE_ADD(LD_SYSDATE, INTERVAL -12 MONTH), '%Y');

  -- 0、清除原有制表数据，准备重新制表
  BEGIN
  DECLARE BJTS_SQLCODE_003 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_003 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_003 = MYSQL_ERRNO, BJTS_SQLERRM_003 = MESSAGE_TEXT;
      SET V_ERROR = BJTS_SQLCODE_003;
      SET V_MSG = BJTS_SQLERRM_003;
      LEAVE routine_body;

  END;
DELETE FROM TJBB_DT_B03102 WHERE SWJGDM=V_SWCODE AND SSNY=LC_THISMONTH;
    COMMIT;
  END;

  -- 1、制表
  BEGIN
  DECLARE BJTS_SQLCODE_002 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_002 TEXT DEFAULT '';
    -- 1.1 本年数
    -- 1.1.1 生产企业

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_002 = MYSQL_ERRNO, BJTS_SQLERRM_002 = MESSAGE_TEXT;
      SET V_ERROR = BJTS_SQLCODE_002;
      SET V_MSG = BJTS_SQLERRM_002;
      LEAVE routine_body;

  END;
INSERT INTO TJBB_DT_B03102 (SSNY,BBLC,SWJGDM,
           JAN,FEB,MAR,APR,MAY,JUN,JUL,AUG,SEP,OCT,NOV,DEC,
           JAN_HZ,FEB_HZ,MAR_HZ,APR_HZ,MAY_HZ,JUN_HZ,JUL_HZ,AUG_HZ,SEP_HZ,OCT_HZ,NOV_HZ,DEC_HZ)
    WITH TSFN AS (SELECT DATE_FORMAT(T.RKRQ, '%Y%m') AS FNMONTH, IFNULL(ROUND(SUM(T.SJJE)/10000,0), 0) AS FNSE
                    FROM FG_CKTSFN_HXZG T
                    LEFT JOIN GLXT_BB_SHXT_DJXX R ON R.DJXH_JS=T.DJXH
                   WHERE T.SKSSSWJG_DM=V_SWCODE
                     AND T.RKRQ>=LD_THISYEAR AND T.RKRQ<LD_NEXTMONTH
                     AND T.YWHZBUUID IS NULL
                     AND R.JSMODE='1'
                   GROUP BY DATE_FORMAT(T.RKRQ, '%Y%m')),
         TSTK AS (SELECT DATE_FORMAT(S.XHRQ_TK, '%Y%m') AS TKMONTH, IFNULL(ROUND(SUM(S.GKBL_ZZSTSE+S.GKBL_XFSTSE)/10000,0), 0) AS TKSE
                    FROM CKTS_LC_SEHZXX S
                    LEFT JOIN GLXT_BB_SHXT_DJXX R ON R.DJXH_JS=S.DJXH
                   WHERE S.CKTMSJHSSSWJGDM=V_SWCODE
                     AND S.XHRQ_TK>=LD_THISYEAR AND S.XHRQ_TK<LD_NEXTMONTH
                     AND R.JSMODE='1'
                   GROUP BY DATE_FORMAT(S.XHRQ_TK, '%Y%m'))
    SELECT LC_THISMONTH,'01',V_SWCODE,
           SUM(CASE WHEN TSTK.TKMONTH<=ORA_CONCAT(LC_THISYEAR, '01') AND ORA_CONCAT(LC_THISYEAR, '01')<=V_SSNY THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH<=ORA_CONCAT(LC_THISYEAR, '02') AND ORA_CONCAT(LC_THISYEAR, '02')<=V_SSNY THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH<=ORA_CONCAT(LC_THISYEAR, '03') AND ORA_CONCAT(LC_THISYEAR, '03')<=V_SSNY THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH<=ORA_CONCAT(LC_THISYEAR, '04') AND ORA_CONCAT(LC_THISYEAR, '04')<=V_SSNY THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH<=ORA_CONCAT(LC_THISYEAR, '05') AND ORA_CONCAT(LC_THISYEAR, '05')<=V_SSNY THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH<=ORA_CONCAT(LC_THISYEAR, '06') AND ORA_CONCAT(LC_THISYEAR, '06')<=V_SSNY THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH<=ORA_CONCAT(LC_THISYEAR, '07') AND ORA_CONCAT(LC_THISYEAR, '07')<=V_SSNY THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH<=ORA_CONCAT(LC_THISYEAR, '08') AND ORA_CONCAT(LC_THISYEAR, '08')<=V_SSNY THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
