     WHERE A.SWJGDM=V_SWCODE
       AND A.SSNY=LC_THISMONTH
       AND A.BBLC='02'
       AND B.SWJGDM=V_SWCODE
       AND B.SSNY=LC_THISMONTH
       AND B.BBLC='05';
    COMMIT;

    -- 3、合计统计
    INSERT INTO TJBB_DT_B03102 (SSNY,BBLC,SWJGDM,
           JAN,FEB,MAR,APR,MAY,JUN,JUL,AUG,SEP,OCT,NOV,DEC,
           JAN_HZ,FEB_HZ,MAR_HZ,APR_HZ,MAY_HZ,JUN_HZ,JUL_HZ,AUG_HZ,SEP_HZ,OCT_HZ,NOV_HZ,DEC_HZ)
    SELECT LC_THISMONTH, '09', V_SWCODE,
           CASE WHEN IFNULL(B.JAN, 0)=0 THEN NULL ELSE ROUND(100 * A.JAN/B.JAN -100,1) END,
           CASE WHEN IFNULL(B.FEB, 0)=0 THEN NULL ELSE ROUND(100 * A.FEB/B.FEB -100,1) END,
