                   WHERE ((V_SWCODE='13300000000'  AND (T.SKSSSWJG_DM IN (SELECT SWJG_DM FROM DM_SWJG WHERE TSJG_BZ='1'))) OR
                          (V_SWCODE<>'13300000000' AND (T.SKSSSWJG_DM IN (SELECT VIR_SWJGDM AS SWJG_DM
       FROM DM_SWJG_VIRTUAL
      WHERE SUBSTR(V_SWCODE, 1, 1) = '2'
        AND SWJG_DM = V_SWCODE
        AND YXBZ = 'Y'
        AND VIR_FLAG = '0'
      UNION ALL
     SELECT SWJG_DM AS SWJG_DM
       FROM DM_SWJG
      WHERE (SUBSTR(V_SWCODE, 1, 1) <> '2' OR SUBSTR(V_SWCODE, 1, 1) IS NULL)
        AND SWJG_DM_SJ = V_SWCODE
        AND TSJG_BZ = '1'))))
                     AND T.RKRQ>=LD_THISYEAR AND T.RKRQ<LD_NEXTMONTH
                     AND T.YWHZBUUID IS NULL
                     AND (R.JSMODE IS NULL OR R.JSMODE<>'1')
                   GROUP BY DATE_FORMAT(T.RKRQ, '%Y%m')),
         TSTK AS (SELECT DATE_FORMAT(S.XHRQ_TK, '%Y%m') AS TKMONTH, IFNULL(ROUND(SUM(S.GKBL_ZZSTSE+S.GKBL_XFSTSE)/10000,0), 0) AS TKSE
                    FROM CKTS_LC_SEHZXX S
                    LEFT JOIN GLXT_BB_SHXT_DJXX R ON R.DJXH_JS=S.DJXH
                   WHERE ((V_SWCODE='13300000000'  AND (S.CKTMSJHSSSWJGDM IN (SELECT SWJG_DM FROM DM_SWJG WHERE TSJG_BZ='1'))) OR
                          (V_SWCODE<>'13300000000' AND (S.CKTMSJHSSSWJGDM IN (SELECT VIR_SWJGDM AS SWJG_DM
       FROM DM_SWJG_VIRTUAL
      WHERE SUBSTR(V_SWCODE, 1, 1) = '2'
        AND SWJG_DM = V_SWCODE
        AND YXBZ = 'Y'
        AND VIR_FLAG = '0'
      UNION ALL
     SELECT SWJG_DM AS SWJG_DM
       FROM DM_SWJG
      WHERE (SUBSTR(V_SWCODE, 1, 1) <> '2' OR SUBSTR(V_SWCODE, 1, 1) IS NULL)
        AND SWJG_DM_SJ = V_SWCODE
        AND TSJG_BZ = '1'))))
