           SUM(CASE WHEN TSTK.TKMONTH<=ORA_CONCAT(LC_THISYEAR, '08') AND ORA_CONCAT(LC_THISYEAR, '08')<=V_SSNY THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
