           SUM(CASE WHEN TSTK.TKMONTH<=ORA_CONCAT(LC_THISYEAR, '06') AND ORA_CONCAT(LC_THISYEAR, '06')<=V_SSNY THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
