           SUM(CASE WHEN TSTK.TKMONTH<=ORA_CONCAT(LC_LASTYEAR, '12') THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH<=ORA_CONCAT(LC_LASTYEAR, '01') THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH<=ORA_CONCAT(LC_LASTYEAR, '02') THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH<=ORA_CONCAT(LC_LASTYEAR, '03') THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH<=ORA_CONCAT(LC_LASTYEAR, '04') THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH<=ORA_CONCAT(LC_LASTYEAR, '05') THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH<=ORA_CONCAT(LC_LASTYEAR, '06') THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH<=ORA_CONCAT(LC_LASTYEAR, '07') THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH<=ORA_CONCAT(LC_LASTYEAR, '08') THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH<=ORA_CONCAT(LC_LASTYEAR, '09') THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH<=ORA_CONCAT(LC_LASTYEAR, '10') THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH<=ORA_CONCAT(LC_LASTYEAR, '11') THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH<=ORA_CONCAT(LC_LASTYEAR, '12') THEN IFNULL(TSTK.TKSE, 0) - IFNULL(TSFN.FNSE, 0) ELSE 0 END)
      FROM TSTK
      LEFT JOIN TSFN ON TSFN.FNMONTH = TSTK.TKMONTH;
