           CASE WHEN IFNULL(B.DEC, 0)=0 THEN NULL ELSE ROUND(100 * A.DEC/B.DEC -100,1) END,
           CASE WHEN IFNULL(B.JAN_HZ, 0)=0 THEN NULL ELSE ROUND(100 * A.JAN_HZ/B.JAN_HZ -100,1) END,
           CASE WHEN IFNULL(B.FEB_HZ, 0)=0 THEN NULL ELSE ROUND(100 * A.FEB_HZ/B.FEB_HZ -100,1) END,
           CASE WHEN IFNULL(B.MAR_HZ, 0)=0 THEN NULL ELSE ROUND(100 * A.MAR_HZ/B.MAR_HZ -100,1) END,
           CASE WHEN IFNULL(B.APR_HZ, 0)=0 THEN NULL ELSE ROUND(100 * A.APR_HZ/B.APR_HZ -100,1) END,
           CASE WHEN IFNULL(B.MAY_HZ, 0)=0 THEN NULL ELSE ROUND(100 * A.MAY_HZ/B.MAY_HZ -100,1) END,
           CASE WHEN IFNULL(B.JUN_HZ, 0)=0 THEN NULL ELSE ROUND(100 * A.JUN_HZ/B.JUN_HZ -100,1) END,
           CASE WHEN IFNULL(B.JUL_HZ, 0)=0 THEN NULL ELSE ROUND(100 * A.JUL_HZ/B.JUL_HZ -100,1) END,
           CASE WHEN IFNULL(B.AUG_HZ, 0)=0 THEN NULL ELSE ROUND(100 * A.AUG_HZ/B.AUG_HZ -100,1) END,
           CASE WHEN IFNULL(B.SEP_HZ, 0)=0 THEN NULL ELSE ROUND(100 * A.SEP_HZ/B.SEP_HZ -100,1) END,
           CASE WHEN IFNULL(B.OCT_HZ, 0)=0 THEN NULL ELSE ROUND(100 * A.OCT_HZ/B.OCT_HZ -100,1) END,
           CASE WHEN IFNULL(B.NOV_HZ, 0)=0 THEN NULL ELSE ROUND(100 * A.NOV_HZ/B.NOV_HZ -100,1) END,
           CASE WHEN IFNULL(B.DEC_HZ, 0)=0 THEN NULL ELSE ROUND(100 * A.DEC_HZ/B.DEC_HZ -100,1) END
      FROM TJBB_DT_B03102 A,
           TJBB_DT_B03102 B
     WHERE A.SWJGDM=V_SWCODE
       AND A.SSNY=LC_THISMONTH
       AND A.BBLC='02'
       AND B.SWJGDM=V_SWCODE
       AND B.SSNY=LC_THISMONTH
       AND B.BBLC='05';
    COMMIT;

    -- 3、合计统计
    INSERT INTO TJBB_DT_B03102 (SSNY,BBLC,SWJGDM,
           JAN,FEB,MAR,APR,MAY,JUN,JUL,AUG,SEP,OCT,NOV,DEC,
           JAN_HZ,FEB_HZ,MAR_HZ,APR_HZ,MAY_HZ,JUN_HZ,JUL_HZ,AUG_HZ,SEP_HZ,OCT_HZ,NOV_HZ,DEC_HZ)
    SELECT LC_THISMONTH, '09', V_SWCODE,
           CASE WHEN IFNULL(B.JAN, 0)=0 THEN NULL ELSE ROUND(100 * A.JAN/B.JAN -100,1) END,
           CASE WHEN IFNULL(B.FEB, 0)=0 THEN NULL ELSE ROUND(100 * A.FEB/B.FEB -100,1) END,
           CASE WHEN IFNULL(B.MAR, 0)=0 THEN NULL ELSE ROUND(100 * A.MAR/B.MAR -100,1) END,
           CASE WHEN IFNULL(B.APR, 0)=0 THEN NULL ELSE ROUND(100 * A.APR/B.APR -100,1) END,
           CASE WHEN IFNULL(B.MAY, 0)=0 THEN NULL ELSE ROUND(100 * A.MAY/B.MAY -100,1) END,
           CASE WHEN IFNULL(B.JUN, 0)=0 THEN NULL ELSE ROUND(100 * A.JUN/B.JUN -100,1) END,
           CASE WHEN IFNULL(B.JUL, 0)=0 THEN NULL ELSE ROUND(100 * A.JUL/B.JUL -100,1) END,
           CASE WHEN IFNULL(B.AUG, 0)=0 THEN NULL ELSE ROUND(100 * A.AUG/B.AUG -100,1) END,
           CASE WHEN IFNULL(B.SEP, 0)=0 THEN NULL ELSE ROUND(100 * A.SEP/B.SEP -100,1) END,
           CASE WHEN IFNULL(B.OCT, 0)=0 THEN NULL ELSE ROUND(100 * A.OCT/B.OCT -100,1) END,
           CASE WHEN IFNULL(B.NOV, 0)=0 THEN NULL ELSE ROUND(100 * A.NOV/B.NOV -100,1) END,
           CASE WHEN IFNULL(B.DEC, 0)=0 THEN NULL ELSE ROUND(100 * A.DEC/B.DEC -100,1) END,
           CASE WHEN IFNULL(B.JAN_HZ, 0)=0 THEN NULL ELSE ROUND(100 * A.JAN_HZ/B.JAN_HZ -100,1) END,
           CASE WHEN IFNULL(B.FEB_HZ, 0)=0 THEN NULL ELSE ROUND(100 * A.FEB_HZ/B.FEB_HZ -100,1) END,
           CASE WHEN IFNULL(B.MAR_HZ, 0)=0 THEN NULL ELSE ROUND(100 * A.MAR_HZ/B.MAR_HZ -100,1) END,
           CASE WHEN IFNULL(B.APR_HZ, 0)=0 THEN NULL ELSE ROUND(100 * A.APR_HZ/B.APR_HZ -100,1) END,
           CASE WHEN IFNULL(B.MAY_HZ, 0)=0 THEN NULL ELSE ROUND(100 * A.MAY_HZ/B.MAY_HZ -100,1) END,
           CASE WHEN IFNULL(B.JUN_HZ, 0)=0 THEN NULL ELSE ROUND(100 * A.JUN_HZ/B.JUN_HZ -100,1) END,
