  END;

  -- 1、中间表数据计算
  BEGIN
  DECLARE BJTS_SQLCODE_006 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_006 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_006 = MYSQL_ERRNO, BJTS_SQLERRM_006 = MESSAGE_TEXT;
      SET V_ERROR = BJTS_SQLCODE_006;
      SET V_MSG = BJTS_SQLERRM_006;

  END;
INSERT INTO TJBB_DT_B03109_MID (SWJGDM,SSNY,GBDM,CKE_LJ,TSE_LJ,CKPM)
    SELECT V_SWCODE, LC_THISMONTH, XMFL, ROUND(SUM(USD_AMT)/10000,0), ROUND(SUM(TS_AMT)/10000,0), ROW_NUMBER() OVER (ORDER BY SUM(USD_AMT) DESC)
      FROM TJBB_FHXX_HGCODE
     WHERE SWCODE=V_SWCODE AND SSNY BETWEEN LC_THISYEAR AND LC_THISMONTH
     GROUP BY XMFL;
