        AND SWJG_DM_SJ = V_SWCODE
        AND TSJG_BZ = '1'))))
               AND SSNY BETWEEN LC_THISYEAR AND LC_THISMONTH AND XMFL<>'142'
             GROUP BY XMFL)
     UNION ALL
    SELECT V_SWCODE, LC_THISMONTH, 'GJ', XMFL, USD_AMT, TSE_AMT, 999
      FROM (SELECT '142' AS XMFL, ROUND(SUM(C.USD_AMT)/10000,0) AS USD_AMT, ROUND(SUM(C.TS_AMT)/10000,0) AS TSE_AMT
              FROM TJBB_FHXX_GBCODE C
             WHERE ((V_SWCODE='13300000000'  AND (C.SWCODE IN (SELECT SWJG_DM FROM DM_SWJG WHERE TSJG_BZ='1'))) OR
                    (V_SWCODE<>'13300000000' AND (C.SWCODE IN (SELECT VIR_SWJGDM AS SWJG_DM
       FROM DM_SWJG_VIRTUAL
      WHERE SUBSTR(V_SWCODE, 1, 1) = '2'
        AND SWJG_DM = V_SWCODE
        AND YXBZ = 'Y'
        AND VIR_FLAG = '0'
      UNION ALL
     SELECT SWJG_DM AS SWJG_DM
       FROM DM_SWJG
      WHERE (SUBSTR(V_SWCODE, 1, 1) <> '2' OR SUBSTR(V_SWCODE, 1, 1) IS NULL)
        AND SWJG_DM_SJ = V_SWCODE
        AND TSJG_BZ = '1'))))
               AND SSNY BETWEEN LC_THISYEAR AND LC_THISMONTH AND XMFL='142');
    COMMIT;

    INSERT INTO TJBB_DT_B03110_MID (SWJGDM,SSNY,DMTYPE,GBDM,CKE_LJ,TSE_LJ,CKPM)
    SELECT V_SWCODE, LC_LASTMONTH, 'DQ', DQ_CODE, USD_AMT, TSE_AMT, ROW_NUMBER() OVER (ORDER BY USD_AMT DESC)
      FROM (SELECT A.DQ_CODE, ROUND(SUM(C.USD_AMT)/10000,0) AS USD_AMT, ROUND(SUM(C.TS_AMT)/10000,0) AS TSE_AMT
              FROM DM_DQCODE A
             INNER JOIN DM_DQGROUP B ON A.DQ_CODE=B.DQ_CODE
              LEFT JOIN TJBB_FHXX_GBCODE C ON B.GB_CODE=C.XMFL AND
                        ((V_SWCODE='13300000000'  AND (C.SWCODE IN (SELECT SWJG_DM FROM DM_SWJG WHERE TSJG_BZ='1'))) OR
                         (V_SWCODE<>'13300000000' AND (C.SWCODE IN (SELECT VIR_SWJGDM AS SWJG_DM
       FROM DM_SWJG_VIRTUAL
      WHERE SUBSTR(V_SWCODE, 1, 1) = '2'
        AND SWJG_DM = V_SWCODE
        AND YXBZ = 'Y'
        AND VIR_FLAG = '0'
      UNION ALL
     SELECT SWJG_DM AS SWJG_DM
       FROM DM_SWJG
      WHERE (SUBSTR(V_SWCODE, 1, 1) <> '2' OR SUBSTR(V_SWCODE, 1, 1) IS NULL)
        AND SWJG_DM_SJ = V_SWCODE
        AND TSJG_BZ = '1')))) AND C.SSNY BETWEEN LC_LASTYEAR AND LC_LASTMONTH
             WHERE A.DQ_TYPE='DQ'
             GROUP BY A.DQ_CODE)
     UNION ALL
    SELECT V_SWCODE, LC_LASTMONTH, 'ZZ', DQ_CODE, USD_AMT, TSE_AMT, ROW_NUMBER() OVER (ORDER BY USD_AMT DESC)
      FROM (SELECT A.DQ_CODE, ROUND(SUM(C.USD_AMT)/10000,0) AS USD_AMT, ROUND(SUM(C.TS_AMT)/10000,0) AS TSE_AMT
              FROM DM_DQCODE A
             INNER JOIN DM_DQGROUP B ON A.DQ_CODE=B.DQ_CODE
              LEFT JOIN TJBB_FHXX_GBCODE C ON B.GB_CODE=C.XMFL AND
                        ((V_SWCODE='13300000000'  AND (C.SWCODE IN (SELECT SWJG_DM FROM DM_SWJG WHERE TSJG_BZ='1'))) OR
                         (V_SWCODE<>'13300000000' AND (C.SWCODE IN (SELECT VIR_SWJGDM AS SWJG_DM
       FROM DM_SWJG_VIRTUAL
      WHERE SUBSTR(V_SWCODE, 1, 1) = '2'
        AND SWJG_DM = V_SWCODE
        AND YXBZ = 'Y'
        AND VIR_FLAG = '0'
      UNION ALL
     SELECT SWJG_DM AS SWJG_DM
       FROM DM_SWJG
      WHERE (SUBSTR(V_SWCODE, 1, 1) <> '2' OR SUBSTR(V_SWCODE, 1, 1) IS NULL)
        AND SWJG_DM_SJ = V_SWCODE
        AND TSJG_BZ = '1')))) AND C.SSNY BETWEEN LC_LASTYEAR AND LC_LASTMONTH
             WHERE A.DQ_TYPE='ZZ'
             GROUP BY A.DQ_CODE)
     UNION ALL
    SELECT V_SWCODE, LC_LASTMONTH, 'GJ', XMFL, USD_AMT, TSE_AMT, ROW_NUMBER() OVER (ORDER BY USD_AMT DESC)
      FROM (SELECT XMFL, ROUND(SUM(C.USD_AMT)/10000,0) AS USD_AMT, ROUND(SUM(C.TS_AMT)/10000,0) AS TSE_AMT
              FROM TJBB_FHXX_GBCODE C
             WHERE ((V_SWCODE='13300000000'  AND (C.SWCODE IN (SELECT SWJG_DM FROM DM_SWJG WHERE TSJG_BZ='1'))) OR
                    (V_SWCODE<>'13300000000' AND (C.SWCODE IN (SELECT VIR_SWJGDM AS SWJG_DM
       FROM DM_SWJG_VIRTUAL
      WHERE SUBSTR(V_SWCODE, 1, 1) = '2'
        AND SWJG_DM = V_SWCODE
        AND YXBZ = 'Y'
        AND VIR_FLAG = '0'
      UNION ALL
     SELECT SWJG_DM AS SWJG_DM
       FROM DM_SWJG
      WHERE (SUBSTR(V_SWCODE, 1, 1) <> '2' OR SUBSTR(V_SWCODE, 1, 1) IS NULL)
        AND SWJG_DM_SJ = V_SWCODE
        AND TSJG_BZ = '1')))) AND SSNY BETWEEN LC_LASTYEAR AND LC_LASTMONTH AND XMFL<>'142'
             GROUP BY XMFL)
     UNION ALL
    SELECT V_SWCODE, LC_LASTMONTH, 'GJ', XMFL, USD_AMT, TSE_AMT, 999
      FROM (SELECT '142' AS XMFL, ROUND(SUM(C.USD_AMT)/10000,0) AS USD_AMT, ROUND(SUM(C.TS_AMT)/10000,0) AS TSE_AMT
              FROM TJBB_FHXX_GBCODE C
             WHERE ((V_SWCODE='13300000000'  AND (C.SWCODE IN (SELECT SWJG_DM FROM DM_SWJG WHERE TSJG_BZ='1'))) OR
                    (V_SWCODE<>'13300000000' AND (C.SWCODE IN (SELECT VIR_SWJGDM AS SWJG_DM
       FROM DM_SWJG_VIRTUAL
      WHERE SUBSTR(V_SWCODE, 1, 1) = '2'
        AND SWJG_DM = V_SWCODE
        AND YXBZ = 'Y'
        AND VIR_FLAG = '0'
      UNION ALL
     SELECT SWJG_DM AS SWJG_DM
       FROM DM_SWJG
      WHERE (SUBSTR(V_SWCODE, 1, 1) <> '2' OR SUBSTR(V_SWCODE, 1, 1) IS NULL)
        AND SWJG_DM_SJ = V_SWCODE
        AND TSJG_BZ = '1')))) AND SSNY BETWEEN LC_LASTYEAR AND LC_LASTMONTH AND XMFL='142');
    COMMIT;
  END;
  IF V_ERROR <> 0 THEN
    LEAVE routine_body;
  END IF;

  -- 2、计算并插入本年明细及上年同期
  BEGIN
  DECLARE BJTS_SQLCODE_005 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_005 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_005 = MYSQL_ERRNO, BJTS_SQLERRM_005 = MESSAGE_TEXT;
      SET V_ERROR = BJTS_SQLCODE_005;
      SET V_MSG = BJTS_SQLERRM_005;

  END;
INSERT INTO TJBB_DT_B03110 (SSNY,BBLC,SWJGDM,ITEM,CKE_USD,TMSE,CKE_USD_LAST,TMSE_LAST)
    SELECT LC_THISMONTH, '1000', V_SWCODE, '国别地区', NULL, NULL, NULL, NULL

     UNION ALL
    SELECT B.SSNY, ORA_CONCAT(CASE WHEN B.CKPM<10 THEN '100' ELSE '10' END, B.CKPM), B.SWJGDM, A.DQ_NAME, B.CKE_LJ, B.TSE_LJ, C.CKE_LJ, C.TSE_LJ
      FROM DM_DQCODE A
     INNER JOIN TJBB_DT_B03110_MID B ON A.DQ_CODE=B.GBDM AND B.SWJGDM=V_SWCODE AND B.SSNY=LC_THISMONTH AND B.DMTYPE='DQ'
      LEFT JOIN TJBB_DT_B03110_MID C ON A.DQ_CODE=C.GBDM AND C.SWJGDM=V_SWCODE AND C.SSNY=LC_LASTMONTH AND C.DMTYPE='DQ'
     WHERE A.DQ_TYPE='DQ'
     UNION ALL
    SELECT LC_THISMONTH, '2000', V_SWCODE, '区域（经济）组织', NULL, NULL, NULL, NULL

     UNION ALL
    SELECT B.SSNY, ORA_CONCAT(CASE WHEN B.CKPM<10 THEN '200' ELSE '20' END, B.CKPM), B.SWJGDM, A.DQ_NAME, B.CKE_LJ, B.TSE_LJ, C.CKE_LJ, C.TSE_LJ
      FROM DM_DQCODE A
     INNER JOIN TJBB_DT_B03110_MID B ON A.DQ_CODE=B.GBDM AND B.SWJGDM=V_SWCODE AND B.SSNY=LC_THISMONTH AND B.DMTYPE='ZZ'
      LEFT JOIN TJBB_DT_B03110_MID C ON A.DQ_CODE=C.GBDM AND C.SWJGDM=V_SWCODE AND C.SSNY=LC_LASTMONTH AND C.DMTYPE='ZZ'
     WHERE A.DQ_TYPE='ZZ'
     UNION ALL
    SELECT B.SSNY, ORA_CONCAT(CASE WHEN B.CKPM<10 THEN '300' WHEN B.CKPM<100 THEN '30' ELSE '3' END, B.CKPM), B.SWJGDM, A.GB_NAME, B.CKE_LJ, B.TSE_LJ, C.CKE_LJ, C.TSE_LJ
      FROM DM_GBCODE A
     INNER JOIN TJBB_DT_B03110_MID B ON A.GB_CODE=B.GBDM AND B.SWJGDM=V_SWCODE AND B.SSNY=LC_THISMONTH AND B.DMTYPE='GJ'
      LEFT JOIN TJBB_DT_B03110_MID C ON A.GB_CODE=C.GBDM AND C.SWJGDM=V_SWCODE AND C.SSNY=LC_LASTMONTH AND C.DMTYPE='GJ';
    COMMIT;
  END;
  IF V_ERROR <> 0 THEN
    LEAVE routine_body;
  END IF;

  -- 3、计算并插入合计数及其他数
  BEGIN
  DECLARE BJTS_SQLCODE_004 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_004 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_004 = MYSQL_ERRNO, BJTS_SQLERRM_004 = MESSAGE_TEXT;
      DO 0;

  END;
SELECT ROUND(SUM(C.USD_AMT)/10000,0), ROUND(SUM(C.TS_AMT)/10000,0)
      INTO LN_CKE_HJ, LN_TSE_HJ
      FROM TJBB_FHXX_GBCODE C
     WHERE ((V_SWCODE='13300000000'  AND (C.SWCODE IN (SELECT SWJG_DM FROM DM_SWJG WHERE TSJG_BZ='1'))) OR
            (V_SWCODE<>'13300000000' AND (C.SWCODE IN (SELECT VIR_SWJGDM AS SWJG_DM
       FROM DM_SWJG_VIRTUAL
      WHERE SUBSTR(V_SWCODE, 1, 1) = '2'
        AND SWJG_DM = V_SWCODE
        AND YXBZ = 'Y'
        AND VIR_FLAG = '0'
      UNION ALL
     SELECT SWJG_DM AS SWJG_DM
       FROM DM_SWJG
      WHERE (SUBSTR(V_SWCODE, 1, 1) <> '2' OR SUBSTR(V_SWCODE, 1, 1) IS NULL)
        AND SWJG_DM_SJ = V_SWCODE
        AND TSJG_BZ = '1'))))
        AND C.SSNY BETWEEN LC_THISYEAR AND LC_THISMONTH;

    SELECT ROUND(SUM(C.USD_AMT)/10000,0), ROUND(SUM(C.TS_AMT)/10000,0)
      INTO LN_CKE_HJ_LAST, LN_TSE_HJ_LAST
      FROM TJBB_FHXX_GBCODE C
     WHERE ((V_SWCODE='13300000000'  AND (C.SWCODE IN (SELECT SWJG_DM FROM DM_SWJG WHERE TSJG_BZ='1'))) OR
            (V_SWCODE<>'13300000000' AND (C.SWCODE IN (SELECT VIR_SWJGDM AS SWJG_DM
       FROM DM_SWJG_VIRTUAL
      WHERE SUBSTR(V_SWCODE, 1, 1) = '2'
        AND SWJG_DM = V_SWCODE
        AND YXBZ = 'Y'
        AND VIR_FLAG = '0'
      UNION ALL
     SELECT SWJG_DM AS SWJG_DM
       FROM DM_SWJG
      WHERE (SUBSTR(V_SWCODE, 1, 1) <> '2' OR SUBSTR(V_SWCODE, 1, 1) IS NULL)
        AND SWJG_DM_SJ = V_SWCODE
        AND TSJG_BZ = '1'))))
       AND C.SSNY BETWEEN  LC_LASTYEAR AND LC_LASTMONTH;

    SELECT LN_CKE_HJ - SUM(CKE_USD),LN_TSE_HJ - SUM(TMSE),LN_CKE_HJ_LAST - SUM(CKE_USD_LAST),LN_TSE_HJ_LAST - SUM(TMSE_LAST)
      INTO LN_CKE_OTHER, LN_TSE_OTHER, LN_CKE_OTHER_LAST, LN_TSE_OTHER_LAST
      FROM TJBB_DT_B03110
     WHERE SSNY=LC_THISMONTH AND BBLC LIKE '3%' AND SWJGDM=V_SWCODE;

    INSERT INTO TJBB_DT_B03110 (SSNY,BBLC,SWJGDM,ITEM,CKE_USD,TMSE,CKE_USD_LAST,TMSE_LAST)
    SELECT LC_THISMONTH, '3000', V_SWCODE, '所有国家合计', LN_CKE_HJ, LN_TSE_HJ, LN_CKE_HJ_LAST, LN_TSE_HJ_LAST
;
    INSERT INTO TJBB_DT_B03110 (SSNY,BBLC,SWJGDM,ITEM,CKE_USD,TMSE,CKE_USD_LAST,TMSE_LAST)
    SELECT LC_THISMONTH, '4000', V_SWCODE, '其他', LN_CKE_OTHER, LN_TSE_OTHER, LN_CKE_OTHER_LAST, LN_TSE_OTHER_LAST
;
    COMMIT;
  END;

  -- 5、同比计算
  BEGIN
  DECLARE BJTS_SQLCODE_003 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_003 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_003 = MYSQL_ERRNO, BJTS_SQLERRM_003 = MESSAGE_TEXT;
      SET V_ERROR = BJTS_SQLCODE_003;
      SET V_MSG = BJTS_SQLERRM_003;

  END;
UPDATE TJBB_DT_B03110
       SET CKE_TB  = CASE WHEN IFNULL(CKE_USD_LAST, 0)=0 THEN NULL ELSE ROUND(100 * CKE_USD / CKE_USD_LAST -100,1) END,
    TMSE_TB = CASE WHEN IFNULL(TMSE_LAST, 0)=0    THEN NULL ELSE ROUND(100 * TMSE    / TMSE_LAST    -100,1) END
     WHERE SWJGDM=V_SWCODE
       AND SSNY=LC_THISMONTH;
    COMMIT;
  END;
  IF V_ERROR <> 0 THEN
    LEAVE routine_body;
  END IF;

  -- 6、占比计算
  BEGIN
  DECLARE BJTS_SQLCODE_002 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_002 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_002 = MYSQL_ERRNO, BJTS_SQLERRM_002 = MESSAGE_TEXT;
      SET V_ERROR = BJTS_SQLCODE_002;
      SET V_MSG = BJTS_SQLERRM_002;

  END;
UPDATE TJBB_DT_B03110 AS T
       SET CKE_ZB  = CASE WHEN IFNULL(LN_CKE_HJ, 0)=0 THEN NULL ELSE ROUND(100 * CKE_USD / LN_CKE_HJ,1) END,
    TMSE_ZB = CASE WHEN IFNULL(LN_TSE_HJ, 0)=0 THEN NULL ELSE ROUND(100 * TMSE / LN_TSE_HJ,1) END
     WHERE SWJGDM=V_SWCODE
       AND SSNY=LC_THISMONTH;
    COMMIT;
  END;
  IF V_ERROR <> 0 THEN
    LEAVE routine_body;
  END IF;

  -- 7、汇总栏初始化
  BEGIN
  DECLARE BJTS_SQLCODE_001 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_001 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_001 = MYSQL_ERRNO, BJTS_SQLERRM_001 = MESSAGE_TEXT;
      SET V_ERROR = BJTS_SQLCODE_001;
      SET V_MSG = BJTS_SQLERRM_001;

  END;
SET LC_SQL_UPDATEHZ = 'UPDATE TJBB_DT_B03110 SET ';

    BEGIN
  DECLARE BJTS_CURSOR_DONE_001 BOOLEAN DEFAULT FALSE;
  DECLARE BJTS_LSF_XX_FNAME_001 LONGTEXT;
  DECLARE BJTS_CURSOR_001 CURSOR FOR
SELECT FNAME FROM TJBB_HEADER_COLS WHERE BBDM='B03110' AND FTYPE='NUMBER' ORDER BY SHOWORDER;
  OPEN BJTS_CURSOR_001;
  BJTS_CURSOR_LOOP_001: LOOP
    SET BJTS_CURSOR_DONE_001 = FALSE;
    BEGIN
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET BJTS_CURSOR_DONE_001 = TRUE;
      FETCH BJTS_CURSOR_001 INTO BJTS_LSF_XX_FNAME_001;
    END;
    IF BJTS_CURSOR_DONE_001 THEN
      LEAVE BJTS_CURSOR_LOOP_001;
    END IF;
      SET LC_SQL_UPDATEHZ = ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(LC_SQL_UPDATEHZ, BJTS_LSF_XX_FNAME_001), '_HZ='), BJTS_LSF_XX_FNAME_001), ', ');

  END LOOP BJTS_CURSOR_LOOP_001;
  CLOSE BJTS_CURSOR_001;
END;

    SET LC_SQL_UPDATEHZ = ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(ORA_CONCAT(SUBSTR(LC_SQL_UPDATEHZ, 1, LENGTH(LC_SQL_UPDATEHZ)-2), ' WHERE SWJGDM='''), V_SWCODE), ''' AND SSNY='''), LC_THISMONTH), '''');

    SET @BJTS_DYNAMIC_SQL_001 = LC_SQL_UPDATEHZ;
PREPARE BJTS_DYNAMIC_STMT_001 FROM @BJTS_DYNAMIC_SQL_001;
EXECUTE BJTS_DYNAMIC_STMT_001;
DEALLOCATE PREPARE BJTS_DYNAMIC_STMT_001;
    COMMIT;
  END;

  LEAVE routine_body;
END$$

