INSERT INTO TJBB_DT_B03112 (SSNY,BBLC,SWJGDM,SPDLDM,SPDL,SPMC,CKE_YEAR,TSE_YEAR,CKE_YEAR_LAST,TSE_YEAR_LAST)
      WITH THISYEAR AS (SELECT XMFL, SUM(USD_AMT_USA) AS USD_AMT, SUM(TS_AMT_USA) AS TS_AMT
                          FROM TJBB_FHXX_CMCODE
                         WHERE ((V_SWCODE='13300000000'  AND (SWCODE IN (SELECT SWJG_DM FROM DM_SWJG WHERE TSJG_BZ='1'))) OR
                                (V_SWCODE<>'13300000000' AND (SWCODE IN (SELECT VIR_SWJGDM AS SWJG_DM
       FROM DM_SWJG_VIRTUAL
      WHERE SUBSTR(V_SWCODE, 1, 1) = '2'
        AND SWJG_DM = V_SWCODE
        AND YXBZ = 'Y'
        AND VIR_FLAG = '0'
      UNION ALL
     SELECT SWJG_DM AS SWJG_DM
       FROM DM_SWJG
      WHERE (SUBSTR(V_SWCODE, 1, 1) <> '2' OR SUBSTR(V_SWCODE, 1, 1) IS NULL)
        AND SWJG_DM_SJ = V_SWCODE
        AND TSJG_BZ = '1'))))
                           AND SSNY BETWEEN LC_THISYEAR AND LC_THISMONTH
                         GROUP BY XMFL),
           LASTYEAR AS (SELECT XMFL, SUM(USD_AMT_USA) AS USD_AMT, SUM(TS_AMT_USA) AS TS_AMT
                          FROM TJBB_FHXX_CMCODE
                         WHERE ((V_SWCODE='13300000000'  AND (SWCODE IN (SELECT SWJG_DM FROM DM_SWJG WHERE TSJG_BZ='1'))) OR
                                (V_SWCODE<>'13300000000' AND (SWCODE IN (SELECT VIR_SWJGDM AS SWJG_DM
       FROM DM_SWJG_VIRTUAL
      WHERE SUBSTR(V_SWCODE, 1, 1) = '2'
        AND SWJG_DM = V_SWCODE
        AND YXBZ = 'Y'
        AND VIR_FLAG = '0'
      UNION ALL
     SELECT SWJG_DM AS SWJG_DM
       FROM DM_SWJG
      WHERE (SUBSTR(V_SWCODE, 1, 1) <> '2' OR SUBSTR(V_SWCODE, 1, 1) IS NULL)
        AND SWJG_DM_SJ = V_SWCODE
        AND TSJG_BZ = '1'))))
                           AND SSNY BETWEEN LC_LASTYEAR AND LC_LASTMONTH
                         GROUP BY XMFL)
    SELECT LC_THISMONTH, 1+ ROW_NUMBER() OVER (ORDER BY SUM(IFNULL(C.USD_AMT, 0)) DESC,SUM(IFNULL(D.USD_AMT, 0)) DESC) AS BBLC, V_SWCODE,
           A.SPML, A.MLDM, A.MLMC,
           ROUND(SUM(C.USD_AMT)/10000,0), ROUND(SUM(C.TS_AMT)/10000,0), ROUND(SUM(D.USD_AMT)/10000,0), ROUND(SUM(D.TS_AMT)/10000,0)
      FROM DM_SPML A
     INNER JOIN DM_SPFL B ON A.SPML=B.SPML
      LEFT JOIN THISYEAR C ON C.XMFL = B.SPDL
      LEFT JOIN LASTYEAR D ON D.XMFL = B.SPDL
      GROUP BY A.SPML, A.MLDM, A.MLMC;
    COMMIT;

    UPDATE TJBB_DT_B03112
       SET BBLC = ORA_CONCAT('0', BBLC)
     WHERE LENGTH(BBLC)<2;
    COMMIT;
  END;
  IF V_ERROR <> 0 THEN
    LEAVE routine_body;
  END IF;

  -- 2、计算并插入合计数
  BEGIN
  DECLARE BJTS_SQLCODE_004 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_004 TEXT DEFAULT '';

