DELIMITER $$

DROP PROCEDURE IF EXISTS PRO_TJBB_DT_B03116_CSH_NEW$$

CREATE PROCEDURE PRO_TJBB_DT_B03116_CSH_NEW
/*************************************************
 * 跨境电子商务零售出口退税情况统计表9810
 * 202504，根据省局关注点全新设计，分出口电子信息、申报（其中预退税）、办理（其中预退税）
 * 20250519，根据5月初报表运行情况创建表索引并优化语句
 ************************************************/
(
  IN V_SWCODE VARCHAR(4000),
  IN V_SSNY VARCHAR(4000),
  OUT V_ERROR DECIMAL(38,10),
  OUT V_MSG VARCHAR(4000)
)
routine_body: BEGIN
  DECLARE LD_SYSDATE       DATETIME;
  DECLARE LC_THISMONTH     VARCHAR(6);
  DECLARE LD_THISYEAR      DATETIME;
  DECLARE LD_NEXTMONTH     DATETIME;
  DECLARE LC_SQL           VARCHAR(4000);
  DECLARE LC_SQL_UPDATEHZ  VARCHAR(4000);
  DECLARE LN_CK_HS         BIGINT;
  DECLARE LN_CK_MY         DECIMAL(18,6);
  DECLARE LN_CK_RMB        DECIMAL(18,6);
  DECLARE LN_SB_HS         BIGINT;
  DECLARE LN_SB_MY         DECIMAL(18,6);
  DECLARE LN_SB_JSJE       DECIMAL(18,6);
  DECLARE LN_SB_TMSE       DECIMAL(18,6);
  DECLARE LN_SB_HS_YT      BIGINT;
  DECLARE LN_SB_MY_YT      DECIMAL(18,6);
  DECLARE LN_SB_JSJE_YT    DECIMAL(18,6);
  DECLARE LN_SB_TMSE_YT    DECIMAL(18,6);
  DECLARE LN_BL_HS         BIGINT;
  DECLARE LN_BL_MY         DECIMAL(18,6);
  DECLARE LN_BL_JSJE       DECIMAL(18,6);
  DECLARE LN_BL_TMSE       DECIMAL(18,6);
  DECLARE LN_BL_HS_YT      BIGINT;
  DECLARE LN_BL_MY_YT      DECIMAL(18,6);
  DECLARE LN_BL_JSJE_YT    DECIMAL(18,6);
  DECLARE LN_BL_TMSE_YT    DECIMAL(18,6);

  SET V_ERROR =0;
  SET V_MSG = ' ';

  IF V_SSNY IS NOT NULL THEN
    SET LD_SYSDATE =STR_TO_DATE(ORA_CONCAT(V_SSNY, '01'), '%Y%m%d');
  ELSE
    SET LD_SYSDATE =CAST(DATE_FORMAT(CURRENT_TIMESTAMP, '%Y-%m-01') AS DATETIME);
  END IF;
  SET LC_THISMONTH =DATE_FORMAT(LD_SYSDATE, '%Y%m');
  SET LD_THISYEAR =MAKEDATE(YEAR(LD_SYSDATE), 1);
  SET LD_NEXTMONTH =CAST(DATE_FORMAT(DATE_ADD(LD_SYSDATE, INTERVAL 1 MONTH), '%Y-%m-01') AS DATETIME);

  -- 0、清除原有制表数据，准备重新制表
  BEGIN
  DECLARE BJTS_SQLCODE_003 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_003 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_003 = MYSQL_ERRNO, BJTS_SQLERRM_003 = MESSAGE_TEXT;
      SET V_ERROR = BJTS_SQLCODE_003;
      SET V_MSG = BJTS_SQLERRM_003;
      LEAVE routine_body;

  END;
DELETE FROM TJBB_DT_B03116 WHERE SWJGDM=V_SWCODE AND SSNY=LC_THISMONTH;
    COMMIT;
  END;

  -- 1、当月外贸企业
  BEGIN
    SELECT COUNT(DISTINCT BGD.DJXH), IFNULL(ROUND(SUM(BGD.MYLAJ)/10000,6), 0), IFNULL(ROUND(SUM(BGD.RMBLAJ)/10000,6), 0)
      INTO LN_CK_HS, LN_CK_MY, LN_CK_RMB
      FROM CKTS_WBSJ_HG_BGD BGD
     INNER JOIN GLXT_BB_SHXT_DJXX DJ
        ON DJ.DJXH_JS=BGD.DJXH
       AND DJ.JSMODE<>'1'
     WHERE BGD.TSSWJG_DM_1=V_SWCODE
       AND BGD.JGFS_DM = '9810'
       AND BGD.CKRQ_1>=LD_SYSDATE AND BGD.CKRQ_1<LD_NEXTMONTH;

    SELECT COUNT(DISTINCT MTS.DJXH), IFNULL(ROUND(SUM(MTS.MYLAJ)/10000,6), 0), IFNULL(ROUND(SUM(MTS.JSJE)/10000,6), 0), IFNULL(ROUND(SUM(MTS.TSE)/10000,6), 0),
           COUNT(DISTINCT CASE WHEN REGEXP_LIKE(MTS.CKTMSYWLXDMJH ,'^HWC-YT') THEN MTS.DJXH ELSE NULL END),
           IFNULL(ROUND(SUM(CASE WHEN REGEXP_LIKE(MTS.CKTMSYWLXDMJH ,'^HWC-YT') THEN MTS.MYLAJ ELSE 0 END)/10000,6), 0),
           IFNULL(ROUND(SUM(CASE WHEN REGEXP_LIKE(MTS.CKTMSYWLXDMJH ,'^HWC-YT') THEN MTS.JSJE ELSE 0 END)/10000,6), 0),
           IFNULL(ROUND(SUM(CASE WHEN REGEXP_LIKE(MTS.CKTMSYWLXDMJH ,'^HWC-YT') THEN MTS.TSE ELSE 0 END)/10000,6), 0)
      INTO LN_SB_HS, LN_SB_MY, LN_SB_JSJE, LN_SB_TMSE,
           LN_SB_HS_YT, LN_SB_MY_YT, LN_SB_JSJE_YT, LN_SB_TMSE_YT
      FROM CKTS_SB_MTS_CKMX MTS
     WHERE MTS.TSSWJG_DM=V_SWCODE
       AND MTS.TDCODE = '9810'
       AND MTS.SBRQ>=LD_SYSDATE AND MTS.SBRQ<LD_NEXTMONTH;

    SELECT COUNT(DISTINCT MTS.DJXH), IFNULL(ROUND(SUM(MTS.MYLAJ)/10000,6), 0), IFNULL(ROUND(SUM(MTS.JSJE)/10000,6), 0), IFNULL(ROUND(SUM(MTS.TSE)/10000,6), 0),
           COUNT(DISTINCT CASE WHEN REGEXP_LIKE(MTS.CKTMSYWLXDMJH ,'^HWC-YT') THEN MTS.DJXH ELSE NULL END),
           IFNULL(ROUND(SUM(CASE WHEN REGEXP_LIKE(MTS.CKTMSYWLXDMJH ,'^HWC-YT') THEN MTS.MYLAJ ELSE 0 END)/10000,6), 0),
           IFNULL(ROUND(SUM(CASE WHEN REGEXP_LIKE(MTS.CKTMSYWLXDMJH ,'^HWC-YT') THEN MTS.JSJE ELSE 0 END)/10000,6), 0),
           IFNULL(ROUND(SUM(CASE WHEN REGEXP_LIKE(MTS.CKTMSYWLXDMJH ,'^HWC-YT') THEN MTS.TSE ELSE 0 END)/10000,6), 0)
      INTO LN_BL_HS, LN_BL_MY, LN_BL_JSJE, LN_BL_TMSE,
           LN_BL_HS_YT, LN_BL_MY_YT, LN_BL_JSJE_YT, LN_BL_TMSE_YT
      FROM CKTS_SB_MTS_CKMX MTS
     WHERE MTS.TSSWJG_DM=V_SWCODE
       AND MTS.TDCODE = '9810'
       AND MTS.FSRQ>=LD_SYSDATE AND MTS.FSRQ<LD_NEXTMONTH
       AND IFNULL(MTS.BYBLBZ, 'N')='N' AND IFNULL(MTS.BYTSBZ, 'N')='N' AND MTS.SJLY='2';

    INSERT INTO TJBB_DT_B03116 (SSNY, BBLC, SWJGDM, CK_HS, CK_MYLAJ, CK_RMBLAJ,
                SB_HS, SB_MYXSE, SB_JSJE, SB_TMSE, SB_YTS_HS, SB_YTS_MYXSE, SB_YTS_JSJE, SB_YTS_TMSE,
                BL_HS, BL_MYXSE, BL_JSJE, BL_TMSE, BL_YTS_HS, BL_YTS_MYXSE, BL_YTS_JSJE, BL_YTS_TMSE)
         SELECT LC_THISMONTH, '01', V_SWCODE, LN_CK_HS, LN_CK_MY, LN_CK_RMB,
                LN_SB_HS, LN_SB_MY, LN_SB_JSJE, LN_SB_TMSE, LN_SB_HS_YT, LN_SB_MY_YT, LN_SB_JSJE_YT, LN_SB_TMSE_YT,
                LN_BL_HS, LN_BL_MY, LN_BL_JSJE, LN_BL_TMSE, LN_BL_HS_YT, LN_BL_MY_YT, LN_BL_JSJE_YT, LN_BL_TMSE_YT
;
    COMMIT;
  END;

  -- 2、当月生产企业
  BEGIN
    SELECT COUNT(DISTINCT BGD.DJXH), IFNULL(ROUND(SUM(BGD.MYLAJ)/10000,6), 0), IFNULL(ROUND(SUM(BGD.RMBLAJ)/10000,6), 0)
      INTO LN_CK_HS, LN_CK_MY, LN_CK_RMB
      FROM CKTS_WBSJ_HG_BGD BGD
     INNER JOIN GLXT_BB_SHXT_DJXX DJ
        ON DJ.DJXH_JS=BGD.DJXH
       AND DJ.JSMODE='1'
     WHERE BGD.TSSWJG_DM_1=V_SWCODE
       AND BGD.JGFS_DM = '9810'
       AND BGD.CKRQ_1>=LD_SYSDATE AND BGD.CKRQ_1<LD_NEXTMONTH;

    SELECT COUNT(DISTINCT MDT.DJXH), IFNULL(ROUND(SUM(MDT.MYLAJ)/10000,6), 0), IFNULL(ROUND(SUM(MDT.RMBLAJ)/10000,6), 0), IFNULL(ROUND(SUM(MDT.MDTSE)/10000,6), 0),
           COUNT(DISTINCT CASE WHEN REGEXP_LIKE(MDT.CKTMSYWLXDMJH ,'^HWC-YT') THEN MDT.DJXH ELSE NULL END),
           IFNULL(ROUND(SUM(CASE WHEN REGEXP_LIKE(MDT.CKTMSYWLXDMJH ,'^HWC-YT') THEN MDT.MYLAJ ELSE 0 END)/10000,6), 0),
           IFNULL(ROUND(SUM(CASE WHEN REGEXP_LIKE(MDT.CKTMSYWLXDMJH ,'^HWC-YT') THEN MDT.RMBLAJ ELSE 0 END)/10000,6), 0),
           IFNULL(ROUND(SUM(CASE WHEN REGEXP_LIKE(MDT.CKTMSYWLXDMJH ,'^HWC-YT') THEN MDT.MDTSE ELSE 0 END)/10000,6), 0)
      INTO LN_SB_HS, LN_SB_MY, LN_SB_JSJE, LN_SB_TMSE,
           LN_SB_HS_YT, LN_SB_MY_YT, LN_SB_JSJE_YT, LN_SB_TMSE_YT
      FROM CKTS_SB_MDT_CKMX MDT
     WHERE MDT.TSSWJG_DM=V_SWCODE
       AND MDT.TDCODE = '9810'
       AND MDT.SBRQ>=LD_SYSDATE AND MDT.SBRQ<LD_NEXTMONTH;

    SELECT COUNT(DISTINCT MDT.DJXH), IFNULL(ROUND(SUM(MDT.MYLAJ)/10000,6), 0), IFNULL(ROUND(SUM(MDT.RMBLAJ)/10000,6), 0), IFNULL(ROUND(SUM(MDT.MDTSE)/10000,6), 0),
           COUNT(DISTINCT CASE WHEN REGEXP_LIKE(MDT.CKTMSYWLXDMJH ,'^HWC-YT') THEN MDT.DJXH ELSE NULL END),
           IFNULL(ROUND(SUM(CASE WHEN REGEXP_LIKE(MDT.CKTMSYWLXDMJH ,'^HWC-YT') THEN MDT.MYLAJ ELSE 0 END)/10000,6), 0),
           IFNULL(ROUND(SUM(CASE WHEN REGEXP_LIKE(MDT.CKTMSYWLXDMJH ,'^HWC-YT') THEN MDT.RMBLAJ ELSE 0 END)/10000,6), 0),
           IFNULL(ROUND(SUM(CASE WHEN REGEXP_LIKE(MDT.CKTMSYWLXDMJH ,'^HWC-YT') THEN MDT.MDTSE ELSE 0 END)/10000,6), 0)
      INTO LN_BL_HS, LN_BL_MY, LN_BL_JSJE, LN_BL_TMSE,
