-- ======================================================================
DELIMITER $$

DROP PROCEDURE IF EXISTS PRO_TJBB_DT_B03117_CSH_NEW$$

CREATE PROCEDURE PRO_TJBB_DT_B03117_CSH_NEW
/*************************************************
 * 启运港政策出口退税情况表
 * 202504，根据省局关注点全新设计，分出口电子信息（其中剔除市场采购）、申报、办理
 ************************************************/
(
  IN V_SWCODE VARCHAR(4000),
  IN V_SSNY VARCHAR(4000),
  OUT V_ERROR DECIMAL(38,10),
  OUT V_MSG VARCHAR(4000)
)
routine_body: BEGIN
  DECLARE LD_SYSDATE       DATETIME;
  DECLARE LC_THISMONTH     VARCHAR(6);
  DECLARE LD_THISYEAR      DATETIME;
  DECLARE LD_NEXTMONTH     DATETIME;
  DECLARE LC_SQL           VARCHAR(4000);
  DECLARE LC_SQL_UPDATEHZ  VARCHAR(4000);
  DECLARE LN_CK_HS         BIGINT;
  DECLARE LN_CK_MY         DECIMAL(18,6);
  DECLARE LN_CK_RMB        DECIMAL(18,6);
  DECLARE LN_CK_HS_F1039   BIGINT;
  DECLARE LN_CK_MY_F1039   DECIMAL(18,6);
  DECLARE LN_CK_RMB_F1039  DECIMAL(18,6);
  DECLARE LN_SB_HS         BIGINT;
  DECLARE LN_SB_MY         DECIMAL(18,6);
  DECLARE LN_SB_JSJE       DECIMAL(18,6);
  DECLARE LN_SB_TMSE       DECIMAL(18,6);
  DECLARE LN_BL_HS         BIGINT;
  DECLARE LN_BL_MY         DECIMAL(18,6);
  DECLARE LN_BL_JSJE       DECIMAL(18,6);
  DECLARE LN_BL_TMSE       DECIMAL(18,6);

  SET V_ERROR =0;
  SET V_MSG = ' ';

  IF V_SSNY IS NOT NULL THEN
    SET LD_SYSDATE =STR_TO_DATE(ORA_CONCAT(V_SSNY, '01'), '%Y%m%d');
  ELSE
    SET LD_SYSDATE =CAST(DATE_FORMAT(CURRENT_TIMESTAMP, '%Y-%m-01') AS DATETIME);
  END IF;
  SET LC_THISMONTH =DATE_FORMAT(LD_SYSDATE, '%Y%m');
  SET LD_THISYEAR =MAKEDATE(YEAR(LD_SYSDATE), 1);
  SET LD_NEXTMONTH =CAST(DATE_FORMAT(DATE_ADD(LD_SYSDATE, INTERVAL 1 MONTH), '%Y-%m-01') AS DATETIME);

  -- 0、清除原有制表数据，准备重新制表
  BEGIN
  DECLARE BJTS_SQLCODE_003 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_003 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_003 = MYSQL_ERRNO, BJTS_SQLERRM_003 = MESSAGE_TEXT;
      SET V_ERROR = BJTS_SQLCODE_003;
      SET V_MSG = BJTS_SQLERRM_003;
      LEAVE routine_body;

  END;
DELETE FROM TJBB_DT_B03117 WHERE SWJGDM=V_SWCODE AND SSNY=LC_THISMONTH;
    COMMIT;
  END;

  -- 1、当月总数
  BEGIN
    SELECT COUNT(DISTINCT BGD.DJXH), IFNULL(ROUND(SUM(BGD.MYLAJ)/10000,6), 0), IFNULL(ROUND(SUM(BGD.RMBLAJ)/10000,6), 0),
           COUNT(DISTINCT CASE WHEN BGD.JGFS_DM='1039' THEN NULL ELSE BGD.DJXH END),
           IFNULL(ROUND(SUM(CASE WHEN BGD.JGFS_DM='1039' THEN 0 ELSE BGD.MYLAJ END)/10000,6), 0),
           IFNULL(ROUND(SUM(CASE WHEN BGD.JGFS_DM='1039' THEN 0 ELSE BGD.RMBLAJ END)/10000,6), 0)
      INTO LN_CK_HS, LN_CK_MY, LN_CK_RMB, LN_CK_HS_F1039, LN_CK_MY_F1039, LN_CK_RMB_F1039
      FROM CKTS_WBSJ_HG_BGD BGD
     WHERE BGD.TSSWJG_DM_1=V_SWCODE
       AND BGD.QYGBZ = 'Y'
       AND BGD.CKRQ_1>=LD_SYSDATE AND BGD.CKRQ_1<LD_NEXTMONTH;

    SELECT COUNT(DISTINCT DJXH), IFNULL(ROUND(SUM(MYLAJ)/10000,6), 0), IFNULL(ROUND(SUM(JSJE)/10000,6), 0), IFNULL(ROUND(SUM(TMSE)/10000,6), 0)
      INTO LN_SB_HS, LN_SB_MY, LN_SB_JSJE, LN_SB_TMSE
      FROM (SELECT MDT.DJXH, MDT.MYLAJ, MDT.RMBLAJ AS JSJE, MDT.MDTSE AS TMSE
              FROM CKTS_SB_MDT_CKMX MDT
             WHERE MDT.TSSWJG_DM=V_SWCODE
               AND REGEXP_LIKE(MDT.CKTMSYWLXDMJH ,'^QYGTS')
               AND MDT.SBRQ>=LD_SYSDATE AND MDT.SBRQ<LD_NEXTMONTH
             UNION ALL
            SELECT MTS.DJXH, MTS.MYLAJ, MTS.JSJE, MTS.TSE AS TMSE
              FROM CKTS_SB_MTS_CKMX MTS
             WHERE MTS.TSSWJG_DM=V_SWCODE
               AND REGEXP_LIKE(MTS.CKTMSYWLXDMJH ,'^QYGTS')
               AND MTS.SBRQ>=LD_SYSDATE AND MTS.SBRQ<LD_NEXTMONTH
             UNION ALL
            SELECT WZF.DJXH, WZF.MYLAJ, WZF.JSJE, WZF.TSE AS TMSE
              FROM CKTS_SB_WZF_CKMX WZF
             WHERE WZF.TSSWJG_DM=V_SWCODE
               AND REGEXP_LIKE(WZF.CKTMSYWLXDMJH ,'^QYGTS')
               AND WZF.SBRQ>=LD_SYSDATE AND WZF.SBRQ<LD_NEXTMONTH) T;

    SELECT COUNT(DISTINCT DJXH), IFNULL(ROUND(SUM(MYLAJ)/10000,6), 0), IFNULL(ROUND(SUM(JSJE)/10000,6), 0), IFNULL(ROUND(SUM(TMSE)/10000,6), 0)
      INTO LN_BL_HS, LN_BL_MY, LN_BL_JSJE, LN_BL_TMSE
      FROM (SELECT MDT.DJXH, MDT.MYLAJ, MDT.RMBLAJ AS JSJE, MDT.MDTSE AS TMSE
              FROM CKTS_SB_MDT_CKMX MDT
             WHERE MDT.TSSWJG_DM=V_SWCODE
               AND REGEXP_LIKE(MDT.CKTMSYWLXDMJH ,'^QYGTS')
               AND MDT.FSRQ>=LD_SYSDATE AND MDT.FSRQ<LD_NEXTMONTH
               AND IFNULL(MDT.BYBLBZ, 'N')='N' AND IFNULL(MDT.BYTSBZ, 'N')='N' AND MDT.SJLY='2'
             UNION ALL
            SELECT MTS.DJXH, MTS.MYLAJ, MTS.JSJE, MTS.TSE AS TMSE
              FROM CKTS_SB_MTS_CKMX MTS
             WHERE MTS.TSSWJG_DM=V_SWCODE
               AND REGEXP_LIKE(MTS.CKTMSYWLXDMJH ,'^QYGTS')
               AND MTS.FSRQ>=LD_SYSDATE AND MTS.FSRQ<LD_NEXTMONTH
               AND IFNULL(MTS.BYBLBZ, 'N')='N' AND IFNULL(MTS.BYTSBZ, 'N')='N' AND MTS.SJLY='2'
             UNION ALL
            SELECT WZF.DJXH, WZF.MYLAJ, WZF.JSJE, WZF.TSE AS TMSE
              FROM CKTS_SB_WZF_CKMX WZF
             WHERE WZF.TSSWJG_DM=V_SWCODE
               AND REGEXP_LIKE(WZF.CKTMSYWLXDMJH ,'^QYGTS')
               AND WZF.FSRQ>=LD_SYSDATE AND WZF.FSRQ<LD_NEXTMONTH
               AND IFNULL(WZF.BYBLBZ, 'N')='N' AND IFNULL(WZF.BYTSBZ, 'N')='N' AND WZF.SJLY='2') T;

    INSERT INTO TJBB_DT_B03117 (SSNY, BBLC, SWJGDM,
                CK_HS, CK_MYLAJ, CK_RMBLAJ,
                CK_F1039_HS, CK_F1039_MYLAJ, CK_F1039_RMBLAJ,
                SB_HS, SB_MYXSE, SB_JSJE, SB_TMSE,
                BL_HS, BL_MYXSE, BL_JSJE, BL_TMSE)
         SELECT LC_THISMONTH, '01', V_SWCODE,
                LN_CK_HS, LN_CK_MY, LN_CK_RMB,
                LN_CK_HS_F1039, LN_CK_MY_F1039, LN_CK_RMB_F1039,
                LN_SB_HS, LN_SB_MY, LN_SB_JSJE, LN_SB_TMSE,
                LN_BL_HS, LN_BL_MY, LN_BL_JSJE, LN_BL_TMSE
;
    COMMIT;
  END;

  -- 2、当月陆路启运港
  BEGIN
    SELECT COUNT(DISTINCT BGD.DJXH), IFNULL(ROUND(SUM(BGD.MYLAJ)/10000,6), 0), IFNULL(ROUND(SUM(BGD.RMBLAJ)/10000,6), 0),
           COUNT(DISTINCT CASE WHEN BGD.JGFS_DM='1039' THEN NULL ELSE BGD.DJXH END),
