/*
 * 202210，新增
 * 列参考B01109，行参考B01100（将第39行提到11行，原11-38行依次下移一行）
 * 20260116，根据舟山反馈问题分析，在统计生产企业申报户数、申报出口额、申报免抵退税额口径，提取进料加工数据时加调整数不为0的条件
 */
(
  IN V_SWCODE VARCHAR(4000),
  IN V_SSNY VARCHAR(4000),
  OUT V_ERROR DECIMAL(38,10),
  OUT V_MSG VARCHAR(4000)
)
routine_body: BEGIN
  DECLARE LD_SYSDATE       DATETIME;
  DECLARE LC_THISMONTH     VARCHAR(6);
  DECLARE LD_THISYEAR      DATETIME;
  DECLARE LD_NEXTMONTH     DATETIME;
  DECLARE LC_LASTMONTH     VARCHAR(6);

  DECLARE LN_BAHS          BIGINT;
  DECLARE LN_SBHS          BIGINT;
  DECLARE LN_SB_CKE        DECIMAL(18,6);

  DECLARE LN_SB_ZZS        DECIMAL(18,6);
  DECLARE LN_SH_ZZS        DECIMAL(18,6);
  DECLARE LN_SP_ZZS        DECIMAL(18,6);
  DECLARE LN_BL_ZZS        DECIMAL(18,6);
  DECLARE TSFN_ZZS         DECIMAL(18,6);

  DECLARE LN_SB_XFS        DECIMAL(18,6);
  DECLARE LN_SH_XFS        DECIMAL(18,6);
  DECLARE LN_SP_XFS        DECIMAL(18,6);
  DECLARE LN_BL_XFS        DECIMAL(18,6);
  DECLARE TSFN_XFS         DECIMAL(18,6);

  DECLARE LC_SQL           VARCHAR(4000);
  DECLARE LC_SQL_UPDATEHZ  VARCHAR(4000);

  SET V_ERROR =0;
  SET V_MSG = ' ';

  IF V_SSNY IS NOT NULL THEN
    SET LD_SYSDATE =STR_TO_DATE(ORA_CONCAT(V_SSNY, '01'), '%Y%m%d');
  ELSE
    SET LD_SYSDATE =CAST(DATE_FORMAT(CURRENT_TIMESTAMP, '%Y-%m-01') AS DATETIME);
  END IF;
  SET LC_THISMONTH =DATE_FORMAT(LD_SYSDATE, '%Y%m');
  SET LD_THISYEAR =MAKEDATE(YEAR(LD_SYSDATE), 1);
  SET LD_NEXTMONTH =CAST(DATE_FORMAT(DATE_ADD(LD_SYSDATE, INTERVAL 1 MONTH), '%Y-%m-01') AS DATETIME);
  SET LC_LASTMONTH =DATE_FORMAT(DATE_ADD(LD_SYSDATE, INTERVAL -12 MONTH), '%Y%m');

  -- 0、清除原有制表数据，准备重新制表
  BEGIN
  DECLARE BJTS_SQLCODE_011 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_011 TEXT DEFAULT '';

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_011 = MYSQL_ERRNO, BJTS_SQLERRM_011 = MESSAGE_TEXT;
      SET V_ERROR = BJTS_SQLCODE_011;
      SET V_MSG = BJTS_SQLERRM_011;
      LEAVE routine_body;

  END;
DELETE FROM TJBB_DT_B07101 WHERE SWJGDM=V_SWCODE AND SSNY=LC_THISMONTH;
    COMMIT;
  END;

  -- 1、外贸企业
  BEGIN
  DECLARE BJTS_SQLCODE_010 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_010 TEXT DEFAULT '';
    -- 备案户数

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_010 = MYSQL_ERRNO, BJTS_SQLERRM_010 = MESSAGE_TEXT;
      SET V_ERROR = BJTS_SQLCODE_010;
      SET V_MSG = BJTS_SQLERRM_010;

  END;
SELECT COUNT(1)
      INTO LN_BAHS
      FROM GLXT_BB_SHXT_DJXX T
     WHERE T.SWJGDM=V_SWCODE
       AND T.ZX_FLAG='N'
       AND T.BAJC_YEAR='10';

    -- 申报户数、申报出口额
    SELECT COUNT(DISTINCT DJXH), ROUND(IFNULL(SUM(MYLAJ), 0)/10000,6)
      INTO LN_SBHS, LN_SB_CKE
     FROM (SELECT A.DJXH,C.LCSLID,C.SBXH,C.MYLAJ
              FROM CKTS_LC_SBXX A
             INNER JOIN CKTS_LC_SHXX B ON B.LCSLID_SB=A.LCSLID_SB
             INNER JOIN CKTS_SB_MTS_CKMX C ON C.LCSLID=B.LCSLID AND C.BYBLBZ='N'
             WHERE A.TSSWJG_DM=V_SWCODE
               AND A.QDSJ>=LD_THISYEAR AND A.QDSJ<LD_NEXTMONTH
               AND B.LCTJJC IN ('10','40','50')
           ) T;

    -- 申报退税额
    SELECT ROUND(IFNULL(SUM(CASE WHEN SZ='V' THEN TSE ELSE 0 END), 0)/10000,6),
           ROUND(IFNULL(SUM(CASE WHEN SZ='C' THEN TSE ELSE 0 END), 0)/10000,6)
      INTO LN_SB_ZZS, LN_SB_XFS
      FROM (SELECT A.DJXH,C.LCSLID,C.SBXH,C.SZ,C.TSE
              FROM CKTS_LC_SBXX A
             INNER JOIN CKTS_LC_SHXX B ON B.LCSLID_SB=A.LCSLID_SB
             INNER JOIN CKTS_SB_MTS_JHMX C ON C.LCSLID=B.LCSLID AND C.BYBLBZ='N'
             WHERE A.TSSWJG_DM=V_SWCODE
               AND A.QDSJ>=LD_THISYEAR AND A.QDSJ<LD_NEXTMONTH
               AND B.LCTJJC IN ('10','40','50')
           ) T;

    -- 审核通过退税额
    SELECT ROUND(IFNULL(SUM(T.FS_ZZSTSE), 0)/10000,6),
           ROUND(IFNULL(SUM(T.FS_XFSTSE), 0)/10000,6)
      INTO LN_SH_ZZS, LN_SH_XFS
      FROM CKTS_LC_YWHZXX T
     WHERE T.TSSWJG_DM=V_SWCODE
       AND T.FSRQ>=LD_THISYEAR AND T.FSRQ<LD_NEXTMONTH
       AND T.LCTJJC = '10';

    -- 审批退税额
    SELECT ROUND(IFNULL(SUM(T.SEHZ_ZZSTSE), 0)/10000,6),
           ROUND(IFNULL(SUM(T.SEHZ_XFSTSE), 0)/10000,6)
      INTO LN_SP_ZZS, LN_SP_XFS
      FROM CKTS_LC_SEHZXX T
     WHERE T.TSSWJG_DM=V_SWCODE
       AND T.SEHZRQ>=LD_THISYEAR AND T.SEHZRQ<LD_NEXTMONTH
       AND T.LCTJJC='10';

    -- 国库办理退税额
    SELECT ROUND(IFNULL(SUM(T.GKBL_ZZSTSE), 0)/10000,6),
           ROUND(IFNULL(SUM(T.GKBL_XFSTSE), 0)/10000,6)
      INTO LN_BL_ZZS, LN_BL_XFS
      FROM CKTS_LC_SEHZXX T
     WHERE T.CKTMSJHSSSWJGDM=V_SWCODE
       AND T.XHRQ_TK>=LD_THISYEAR AND T.XHRQ_TK<LD_NEXTMONTH
       AND T.LCTJJC='10';

    -- 返纳
    SELECT IFNULL(ROUND(SUM(CASE WHEN T.ZSXM_DM='10101' THEN T.SJJE ELSE 0 END)/10000,6), 0),
           IFNULL(ROUND(SUM(CASE WHEN T.ZSXM_DM='10102' THEN T.SJJE ELSE 0 END)/10000,6), 0)
      INTO TSFN_ZZS, TSFN_XFS
      FROM FG_CKTSFN_HXZG T, GLXT_BB_SHXT_DJXX S
     WHERE T.SKSSSWJG_DM=V_SWCODE
       AND T.RKRQ>=LD_THISYEAR AND T.RKRQ<LD_NEXTMONTH
       AND T.YWHZBUUID IS NULL
       AND T.CPCODE=S.CPCODE
       AND S.BAJC_YEAR IN ('00','10');

    INSERT INTO TJBB_DT_B07101 (SSNY, BBLC, SWJGDM, RDHS, SBHS, SB_CKE_CUR, SB_TMSE_CUR, SH_TMSE_CUR, SP_TMSE_CUR, TK_CUR)
    SELECT LC_THISMONTH, '05', V_SWCODE, LN_BAHS, LN_SBHS, LN_SB_CKE, LN_SB_ZZS, LN_SH_ZZS, LN_SP_ZZS - TSFN_ZZS, LN_BL_ZZS - TSFN_ZZS
;
    INSERT INTO TJBB_DT_B07101 (SSNY, BBLC, SWJGDM, RDHS, SBHS, SB_CKE_CUR, SB_TMSE_CUR, SH_TMSE_CUR, SP_TMSE_CUR, TK_CUR)
    SELECT LC_THISMONTH, '06', V_SWCODE, 0, 0, 0, LN_SB_XFS, LN_SH_XFS, LN_SP_XFS - TSFN_XFS, LN_BL_XFS - TSFN_XFS
;
    COMMIT;
  END;

  -- 2、外综服企业
  BEGIN
  DECLARE BJTS_SQLCODE_009 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_009 TEXT DEFAULT '';
    -- 备案户数

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_009 = MYSQL_ERRNO, BJTS_SQLERRM_009 = MESSAGE_TEXT;
      SET V_ERROR = BJTS_SQLCODE_009;
      SET V_MSG = BJTS_SQLERRM_009;

  END;
SELECT COUNT(1)
      INTO LN_BAHS
      FROM GLXT_BB_SHXT_DJXX T
     WHERE T.SWJGDM=V_SWCODE
       AND T.ZX_FLAG='N'
       AND T.BAJC_YEAR IN ('70','71','72');

    -- 申报户数、申报出口额
    SELECT COUNT(DISTINCT DJXH),
           ROUND(IFNULL(SUM(MYLAJ), 0)/10000,6)
      INTO LN_SBHS, LN_SB_CKE
      FROM (SELECT A.DJXH,C.LCSLID,C.SBXH,C.MYLAJ
              FROM CKTS_LC_SBXX A
             INNER JOIN CKTS_LC_SHXX B ON B.LCSLID_SB=A.LCSLID_SB
             INNER JOIN CKTS_SB_MTS_CKMX C ON C.LCSLID=B.LCSLID AND C.BYBLBZ='N'
             WHERE A.TSSWJG_DM=V_SWCODE
               AND A.QDSJ>=LD_THISYEAR AND A.QDSJ<LD_NEXTMONTH
               AND B.LCTJJC IN ('70','71')
             UNION ALL
            SELECT A.DJXH,C.LCSLID,C.SBXH,C.MYLAJ
              FROM CKTS_LC_SBXX A
             INNER JOIN CKTS_LC_SHXX B ON B.LCSLID_SB=A.LCSLID_SB
             INNER JOIN CKTS_SB_WZF_CKMX C ON C.LCSLID=B.LCSLID AND C.BYBLBZ='N'
             WHERE A.TSSWJG_DM=V_SWCODE
               AND A.QDSJ>=LD_THISYEAR AND A.QDSJ<LD_NEXTMONTH
               AND B.LCTJJC = '72'
           ) T;

    -- 申报退税额
    SELECT ROUND(IFNULL(SUM(CASE WHEN SZ='V' THEN TSE ELSE 0 END), 0)/10000,6),
           ROUND(IFNULL(SUM(CASE WHEN SZ='C' THEN TSE ELSE 0 END), 0)/10000,6)
      INTO LN_SB_ZZS, LN_SB_XFS
      FROM (SELECT A.DJXH,C.LCSLID,C.SBXH,C.SZ,C.TSE
              FROM CKTS_LC_SBXX A
             INNER JOIN CKTS_LC_SHXX B ON B.LCSLID_SB=A.LCSLID_SB
             INNER JOIN CKTS_SB_MTS_JHMX C ON C.LCSLID=B.LCSLID AND C.BYBLBZ='N'
             WHERE A.TSSWJG_DM=V_SWCODE
               AND A.QDSJ>=LD_THISYEAR AND A.QDSJ<LD_NEXTMONTH
               AND B.LCTJJC IN ('70','71')
             UNION ALL
            SELECT A.DJXH,C.LCSLID,C.SBXH,'V' AS SZ,C.TSE
              FROM CKTS_LC_SBXX A
             INNER JOIN CKTS_LC_SHXX B ON B.LCSLID_SB=A.LCSLID_SB
             INNER JOIN CKTS_SB_WZF_CKMX C ON C.LCSLID=B.LCSLID AND C.BYBLBZ='N'
             WHERE A.TSSWJG_DM=V_SWCODE
               AND A.QDSJ>=LD_THISYEAR AND A.QDSJ<LD_NEXTMONTH
               AND B.LCTJJC = '72'
           ) T;

    -- 审核通过退税额
    SELECT ROUND(IFNULL(SUM(T.FS_ZZSTSE), 0)/10000,6),
           ROUND(IFNULL(SUM(T.FS_XFSTSE), 0)/10000,6)
      INTO LN_SH_ZZS, LN_SH_XFS
      FROM CKTS_LC_YWHZXX T
     WHERE T.TSSWJG_DM=V_SWCODE
       AND T.FSRQ>=LD_THISYEAR AND T.FSRQ<LD_NEXTMONTH
       AND T.LCTJJC IN ('70','71','72');

    -- 审批退税额
    SELECT ROUND(IFNULL(SUM(T.SEHZ_ZZSTSE), 0)/10000,6),
           ROUND(IFNULL(SUM(T.SEHZ_XFSTSE), 0)/10000,6)
      INTO LN_SP_ZZS, LN_SP_XFS
      FROM CKTS_LC_SEHZXX T
     WHERE T.TSSWJG_DM=V_SWCODE
       AND T.SEHZRQ>=LD_THISYEAR AND T.SEHZRQ<LD_NEXTMONTH
       AND T.LCTJJC IN ('70','71','72');

    -- 国库办理退税额
    SELECT ROUND(IFNULL(SUM(T.GKBL_ZZSTSE), 0)/10000,6),
           ROUND(IFNULL(SUM(T.GKBL_XFSTSE), 0)/10000,6)
      INTO LN_BL_ZZS, LN_BL_XFS
      FROM CKTS_LC_SEHZXX T
     WHERE T.CKTMSJHSSSWJGDM=V_SWCODE
       AND T.XHRQ_TK>=LD_THISYEAR AND T.XHRQ_TK<LD_NEXTMONTH
       AND T.LCTJJC IN ('70','71','72');

    -- 返纳
    SELECT IFNULL(ROUND(SUM(CASE WHEN T.ZSXM_DM='10101' THEN T.SJJE ELSE 0 END)/10000,6), 0),
           IFNULL(ROUND(SUM(CASE WHEN T.ZSXM_DM='10102' THEN T.SJJE ELSE 0 END)/10000,6), 0)
      INTO TSFN_ZZS, TSFN_XFS
      FROM FG_CKTSFN_HXZG T, GLXT_BB_SHXT_DJXX S
     WHERE T.SKSSSWJG_DM=V_SWCODE
       AND T.RKRQ>=LD_THISYEAR AND T.RKRQ<LD_NEXTMONTH
       AND T.YWHZBUUID IS NULL
       AND T.CPCODE=S.CPCODE
       AND S.BAJC_YEAR IN ('70','71','72');

    INSERT INTO TJBB_DT_B07101 (SSNY, BBLC, SWJGDM, RDHS, SBHS, SB_CKE_CUR, SB_TMSE_CUR, SH_TMSE_CUR, SP_TMSE_CUR, TK_CUR)
    SELECT LC_THISMONTH, '08', V_SWCODE, LN_BAHS, LN_SBHS, LN_SB_CKE, LN_SB_ZZS, LN_SH_ZZS, LN_SP_ZZS - TSFN_ZZS, LN_BL_ZZS - TSFN_ZZS
;
    INSERT INTO TJBB_DT_B07101 (SSNY, BBLC, SWJGDM, RDHS, SBHS, SB_CKE_CUR, SB_TMSE_CUR, SH_TMSE_CUR, SP_TMSE_CUR, TK_CUR)
    SELECT LC_THISMONTH, '09', V_SWCODE, 0, 0, 0, LN_SB_XFS, LN_SH_XFS, LN_SP_XFS - TSFN_XFS, LN_BL_XFS - TSFN_XFS
;
    COMMIT;

    -- 2.1 符合13号公告规定业务
    -- 备案户数
    SELECT COUNT(1)
      INTO LN_BAHS
      FROM GLXT_BB_SHXT_DJXX T
     WHERE T.SWJGDM=V_SWCODE
       AND T.ZX_FLAG='N'
       AND T.BAJC_YEAR IN ('70','71');

    -- 申报户数、申报出口额
    SELECT COUNT(DISTINCT DJXH),
           ROUND(IFNULL(SUM(MYLAJ), 0)/10000,6)
      INTO LN_SBHS, LN_SB_CKE
      FROM (SELECT A.DJXH,C.LCSLID,C.SBXH,C.MYLAJ
              FROM CKTS_LC_SBXX A
             INNER JOIN CKTS_LC_SHXX B ON B.LCSLID_SB=A.LCSLID_SB
             INNER JOIN CKTS_SB_MTS_CKMX C ON C.LCSLID=B.LCSLID AND C.BYBLBZ='N'
             WHERE A.TSSWJG_DM=V_SWCODE
               AND A.QDSJ>=LD_THISYEAR AND A.QDSJ<LD_NEXTMONTH
               AND B.LCTJJC = '71'
           ) T;

    -- 申报退税额
    SELECT ROUND(IFNULL(SUM(TSE), 0)/10000,6)
      INTO LN_SB_ZZS
      FROM (SELECT A.DJXH,C.LCSLID,C.SBXH,C.SZ,C.TSE
              FROM CKTS_LC_SBXX A
             INNER JOIN CKTS_LC_SHXX B ON B.LCSLID_SB=A.LCSLID_SB
             INNER JOIN CKTS_SB_MTS_JHMX C ON C.LCSLID=B.LCSLID AND C.BYBLBZ='N'
             WHERE A.TSSWJG_DM=V_SWCODE
               AND A.QDSJ>=LD_THISYEAR AND A.QDSJ<LD_NEXTMONTH
               AND B.LCTJJC = '71'
           ) T;

    -- 审核通过退税额
    SELECT ROUND(IFNULL(SUM(T.FS_ZZSTSE+T.FS_XFSTSE), 0)/10000,6)
      INTO LN_SH_ZZS
      FROM CKTS_LC_YWHZXX T
     WHERE T.TSSWJG_DM=V_SWCODE
       AND T.FSRQ>=LD_THISYEAR AND T.FSRQ<LD_NEXTMONTH
       AND T.LCTJJC = '71';

    -- 审批退税额
    SELECT ROUND(IFNULL(SUM(T.SEHZ_ZZSTSE+T.SEHZ_XFSTSE), 0)/10000,6)
      INTO LN_SP_ZZS
      FROM CKTS_LC_SEHZXX T
     WHERE T.TSSWJG_DM=V_SWCODE
       AND T.SEHZRQ>=LD_THISYEAR AND T.SEHZRQ<LD_NEXTMONTH
       AND T.LCTJJC = '71';

    -- 国库办理退税额
    SELECT ROUND(IFNULL(SUM(T.GKBL_ZZSTSE+T.GKBL_XFSTSE), 0)/10000,6)
      INTO LN_BL_ZZS
      FROM CKTS_LC_SEHZXX T
     WHERE T.CKTMSJHSSSWJGDM=V_SWCODE
       AND T.XHRQ_TK>=LD_THISYEAR AND T.XHRQ_TK<LD_NEXTMONTH
       AND T.LCTJJC = '71';

    INSERT INTO TJBB_DT_B07101 (SSNY, BBLC, SWJGDM, RDHS, SBHS, SB_CKE_CUR, SB_TMSE_CUR, SH_TMSE_CUR, SP_TMSE_CUR, TK_CUR)
    SELECT LC_THISMONTH, '10', V_SWCODE, LN_BAHS, LN_SBHS, LN_SB_CKE, LN_SB_ZZS, LN_SH_ZZS, LN_SP_ZZS, LN_BL_ZZS
;
    COMMIT;

    -- 2.2 符合35号公告规定业务
    -- 备案户数
    SELECT COUNT(1)
      INTO LN_BAHS
      FROM GLXT_BB_SHXT_DJXX T
     WHERE T.SWJGDM=V_SWCODE
       AND T.ZX_FLAG='N'
       AND T.BAJC_YEAR IN ('71','72');

    -- 申报户数、申报出口额
    SELECT COUNT(DISTINCT DJXH),
           ROUND(IFNULL(SUM(MYLAJ), 0)/10000,6)
      INTO LN_SBHS, LN_SB_CKE
      FROM (SELECT A.DJXH,C.LCSLID,C.SBXH,C.MYLAJ
              FROM CKTS_LC_SBXX A
             INNER JOIN CKTS_LC_SHXX B ON B.LCSLID_SB=A.LCSLID_SB
             INNER JOIN CKTS_SB_WZF_CKMX C ON C.LCSLID=B.LCSLID AND C.BYBLBZ='N'
             WHERE A.TSSWJG_DM=V_SWCODE
               AND A.QDSJ>=LD_THISYEAR AND A.QDSJ<LD_NEXTMONTH
               AND B.LCTJJC = '72'
           ) T;

    -- 申报退税额
    SELECT ROUND(IFNULL(SUM(TSE), 0)/10000,6)
      INTO LN_SB_ZZS
      FROM (SELECT A.DJXH,C.LCSLID,C.SBXH,'V' AS SZ,C.TSE
              FROM CKTS_LC_SBXX A
             INNER JOIN CKTS_LC_SHXX B ON B.LCSLID_SB=A.LCSLID_SB
             INNER JOIN CKTS_SB_WZF_CKMX C ON C.LCSLID=B.LCSLID AND C.BYBLBZ='N'
             WHERE A.TSSWJG_DM=V_SWCODE
               AND A.QDSJ>=LD_THISYEAR AND A.QDSJ<LD_NEXTMONTH
               AND B.LCTJJC = '72'
           ) T;

    -- 审核通过退税额
    SELECT ROUND(IFNULL(SUM(T.FS_ZZSTSE+T.FS_XFSTSE), 0)/10000,6)
      INTO LN_SH_ZZS
      FROM CKTS_LC_YWHZXX T
     WHERE T.TSSWJG_DM=V_SWCODE
       AND T.FSRQ>=LD_THISYEAR AND T.FSRQ<LD_NEXTMONTH
       AND T.LCTJJC = '72';

    -- 审批退税额
    SELECT ROUND(IFNULL(SUM(T.SEHZ_ZZSTSE+T.SEHZ_XFSTSE), 0)/10000,6)
      INTO LN_SP_ZZS
      FROM CKTS_LC_SEHZXX T
     WHERE T.TSSWJG_DM=V_SWCODE
       AND T.SEHZRQ>=LD_THISYEAR AND T.SEHZRQ<LD_NEXTMONTH
       AND T.LCTJJC = '72';

    -- 国库办理退税额
    SELECT ROUND(IFNULL(SUM(T.GKBL_ZZSTSE+T.GKBL_XFSTSE), 0)/10000,6)
      INTO LN_BL_ZZS
      FROM CKTS_LC_SEHZXX T
     WHERE T.CKTMSJHSSSWJGDM=V_SWCODE
       AND T.XHRQ_TK>=LD_THISYEAR AND T.XHRQ_TK<LD_NEXTMONTH
       AND T.LCTJJC = '72';

    INSERT INTO TJBB_DT_B07101 (SSNY, BBLC, SWJGDM, RDHS, SBHS, SB_CKE_CUR, SB_TMSE_CUR, SH_TMSE_CUR, SP_TMSE_CUR, TK_CUR)
    SELECT LC_THISMONTH, '11', V_SWCODE, LN_BAHS, LN_SBHS, LN_SB_CKE, LN_SB_ZZS, LN_SH_ZZS, LN_SP_ZZS, LN_BL_ZZS
;
    COMMIT;

  END;

  -- 3、生产企业
  BEGIN
  DECLARE BJTS_SQLCODE_008 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_008 TEXT DEFAULT '';
    -- 3.1、自营出口的生产企业
    -- 备案户数

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_008 = MYSQL_ERRNO, BJTS_SQLERRM_008 = MESSAGE_TEXT;
      SET V_ERROR = BJTS_SQLCODE_008;
      SET V_MSG = BJTS_SQLERRM_008;

  END;
SELECT COUNT(1)
      INTO LN_BAHS
      FROM GLXT_BB_SHXT_DJXX T
     WHERE T.SWJGDM=V_SWCODE
       AND T.ZX_FLAG='N'
       AND T.BAJC_YEAR='21';

    -- 申报户数、申报出口额、申报免抵退税额
    SELECT COUNT(DISTINCT DJXH),
           ROUND(IFNULL(SUM(MYLAJ), 0)/10000,6),
           ROUND(IFNULL(SUM(TSE), 0)/10000,6),
           ROUND(IFNULL(SUM(MDE), 0)/10000,6)
      INTO LN_SBHS, LN_SB_CKE, LN_SB_ZZS, LN_SB_XFS
      FROM (SELECT A.DJXH,C.LCSLID,C.SBXH,C.MYLAJ,
                   C.MDTSE * (CASE WHEN A.SB_MDTSE=0 THEN 1 ELSE A.SB_ZZSTSE/A.SB_MDTSE END) AS TSE,
                   C.MDTSE * (CASE WHEN A.SB_MDTSE=0 THEN 1 ELSE A.SB_MDSE  /A.SB_MDTSE END) AS MDE
              FROM CKTS_LC_SBXX A
             INNER JOIN CKTS_LC_SHXX B ON B.LCSLID_SB=A.LCSLID_SB
             INNER JOIN CKTS_SB_MDT_CKMX C ON C.LCSLID=B.LCSLID AND C.BYBLBZ='N'
             WHERE A.TSSWJG_DM=V_SWCODE
               AND A.QDSJ>=LD_THISYEAR AND A.QDSJ<LD_NEXTMONTH
               AND B.LCTJJC IN ('21','41','51','61')
             UNION ALL
            SELECT A.DJXH,C.LCSLID,'00000000' AS SBXH,0 AS MYLAJ,
                   C.JLJGHXYTZMDTSE * (CASE WHEN A.SB_MDTSE=0 THEN 1 ELSE A.SB_ZZSTSE/A.SB_MDTSE END) AS TSE,
                   C.JLJGHXYTZMDTSE * (CASE WHEN A.SB_MDTSE=0 THEN 1 ELSE A.SB_MDSE  /A.SB_MDTSE END) AS MDE
              FROM CKTS_LC_SBXX A
             INNER JOIN CKTS_LC_SHXX B ON B.LCSLID_SB=A.LCSLID_SB
             INNER JOIN CKTS_SB_MDT_SBDSHZ C ON C.LCSLID=B.LCSLID AND C.JLJGHXYTZMDTSE<>0
             WHERE A.TSSWJG_DM=V_SWCODE
               AND A.QDSJ>=LD_THISYEAR AND A.QDSJ<LD_NEXTMONTH
               AND B.LCTJJC IN ('21','41','51','61')
           ) T;

    -- 审核通过免抵退税额
    SELECT ROUND(IFNULL(SUM(T.FS_ZZSTSE+T.FS_XFSTSE), 0)/10000,6),
           ROUND(IFNULL(SUM(T.FS_MDSE), 0)/10000,6)
      INTO LN_SH_ZZS, LN_SH_XFS
      FROM CKTS_LC_YWHZXX T
     WHERE T.TSSWJG_DM=V_SWCODE
       AND T.FSRQ>=LD_THISYEAR AND T.FSRQ<LD_NEXTMONTH
       AND T.LCTJJC = '21';

    -- 审批免抵退税额
    SELECT ROUND(IFNULL(SUM(T.SEHZ_ZZSTSE + T.SEHZ_XFSTSE), 0)/10000,6),
           ROUND(IFNULL(SUM(T.SEHZ_MDSE), 0)/10000,6)
