  -- 4、服务贸易
  BEGIN
  DECLARE BJTS_SQLCODE_007 INT DEFAULT 0;
  DECLARE BJTS_SQLERRM_007 TEXT DEFAULT '';
    -- 4.1、国际运输服务
    -- 备案户数

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 BJTS_SQLCODE_007 = MYSQL_ERRNO, BJTS_SQLERRM_007 = MESSAGE_TEXT;
      SET V_ERROR = BJTS_SQLCODE_007;
      SET V_MSG = BJTS_SQLERRM_007;

  END;
SELECT COUNT(1)
      INTO LN_BAHS
      FROM GLXT_BB_SHXT_DJXX T
     WHERE T.SWJGDM=V_SWCODE
       AND T.ZX_FLAG='N'
       AND T.BAJC_YEAR='60';

    -- 申报户数、申报出口额、申报免抵退税额
    SELECT COUNT(DISTINCT DJXH),
           ROUND(IFNULL(SUM(MYLAJ), 0)/10000,6),
           ROUND(IFNULL(SUM(TSE), 0)/10000,6),
           ROUND(IFNULL(SUM(MDE), 0)/10000,6)
      INTO LN_SBHS, LN_SB_CKE, LN_SB_ZZS, LN_SB_XFS
      FROM (SELECT A.DJXH,C.LCSLID,C.SBXH,C.YSFWYYEMY AS MYLAJ,
                   C.MDTSE * (CASE WHEN A.SB_MDTSE=0 THEN 1 ELSE A.SB_ZZSTSE/A.SB_MDTSE END) AS TSE,
                   C.MDTSE * (CASE WHEN A.SB_MDTSE=0 THEN 1 ELSE A.SB_MDSE  /A.SB_MDTSE END) AS MDE
              FROM CKTS_LC_SBXX A
             INNER JOIN CKTS_LC_SHXX B ON B.LCSLID_SB=A.LCSLID_SB
             INNER JOIN CKTS_SB_MDT_GJYS C ON C.LCSLID=B.LCSLID AND C.BYBLBZ='N'
             WHERE A.TSSWJG_DM=V_SWCODE
               AND A.QDSJ>=LD_THISYEAR AND A.QDSJ<LD_NEXTMONTH
               AND B.LCTJJC IN ('61','62','63')
           ) T;

    -- 审核通过免抵退税额
    SELECT ROUND(IFNULL(SUM(T.FS_ZZSTSE+T.FS_XFSTSE), 0)/10000,6),
           ROUND(IFNULL(SUM(T.FS_MDSE), 0)/10000,6)
      INTO LN_SH_ZZS, LN_SH_XFS
      FROM CKTS_LC_YWHZXX T
     WHERE T.TSSWJG_DM=V_SWCODE
       AND T.FSRQ>=LD_THISYEAR AND T.FSRQ<LD_NEXTMONTH
       AND T.LCTJJC IN ('61','62','63');

    -- 审批免抵退税额
    SELECT ROUND(IFNULL(SUM(T.SEHZ_ZZSTSE + T.SEHZ_XFSTSE), 0)/10000,6),
           ROUND(IFNULL(SUM(T.SEHZ_MDSE), 0)/10000,6)
      INTO LN_SP_ZZS, LN_SP_XFS
      FROM CKTS_LC_SEHZXX T
     WHERE T.TSSWJG_DM=V_SWCODE
       AND T.SEHZRQ>=LD_THISYEAR AND T.SEHZRQ<LD_NEXTMONTH
       AND T.LCTJJC IN ('61','62','63');

    -- 国库办理免抵退税额
    SELECT ROUND(IFNULL(SUM(T.GKBL_ZZSTSE+T.GKBL_XFSTSE), 0)/10000,6)
      INTO LN_BL_ZZS
      FROM CKTS_LC_SEHZXX T
     WHERE T.CKTMSJHSSSWJGDM=V_SWCODE
       AND T.XHRQ_TK>=LD_THISYEAR AND T.XHRQ_TK<LD_NEXTMONTH
       AND T.LCTJJC IN ('61','62','63');
    SELECT ROUND(IFNULL(SUM(T.GKBL_MDSE), 0)/10000,6)
      INTO LN_BL_XFS
      FROM CKTS_LC_SEHZXX T
     WHERE T.MDTKSSSWJGDM=V_SWCODE
       AND T.XHRQ_MD>=LD_THISYEAR AND T.XHRQ_MD<LD_NEXTMONTH
       AND T.LCTJJC IN ('61','62','63');

    -- 返纳
    SELECT IFNULL(ROUND(SUM(T.SJJE)/10000,6), 0)
