    INSERT INTO TJBB_DT_B07101 (SSNY, BBLC, SWJGDM, RDHS, SBHS, SB_CKE_CUR, SB_TMSE_CUR, SH_TMSE_CUR, SP_TMSE_CUR, TK_CUR)
    SELECT LC_THISMONTH, '30', V_SWCODE, 0, 0, 0, LN_SB_XFS, LN_SH_XFS, LN_SP_XFS, LN_BL_XFS
;
    COMMIT;

    -- 4.1、研发设计服务
    -- 备案户数
    SELECT COUNT(1)
      INTO LN_BAHS
      FROM GLXT_BB_SHXT_DJXX T
     WHERE T.SWJGDM=V_SWCODE
       AND T.ZX_FLAG='N'
       AND T.BAJC_YEAR='50';

    -- 申报户数、申报出口额、申报免抵退税额
    SELECT COUNT(DISTINCT DJXH),
           ROUND(IFNULL(SUM(MYLAJ), 0)/10000,6),
