DELIMITER $$

DROP PROCEDURE IF EXISTS TMP_PRO_TJBB_UPDATE_TSSWJG$$

CREATE PROCEDURE TMP_PRO_TJBB_UPDATE_TSSWJG
(
  IN V_SWCODE VARCHAR(4000)
)
routine_body: BEGIN
  DECLARE LN_ERROR         DECIMAL(38,10);
  DECLARE LC_MSG           VARCHAR(2000);

  DELETE FROM TJBB_FHXX_CMCODE AS T WHERE T.SWCODE = V_SWCODE;
  COMMIT;

  INSERT INTO TJBB_FHXX_CMCODE(SBYWBDM,SSNY,SWCODE,XMFL,USD_AMT_ALL,RMB_AMT_ALL,TS_AMT_ALL,USD_AMT_USA,RMB_AMT_USA,TS_AMT_USA)
       SELECT 'A0301001', S.BBNY, T.TSSWJG_DM, SUBSTR(T.CKSP_DM,0,2), SUM(T.MYLAJ), SUM(T.JSJE), SUM(T.TSE),
